globalThis.ANDE_CHUNKS["237b5db3266ce71b32ea6391b1ab829a2a08dace17bd2ea47cb6577397420db1"] = [{"id":"meituan_social:4314551039","sourceKey":"meituan_social","company":"美团","title":"Keeta-PMO","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4314551039&jobShareType=1","duty":"1、协助业务负责人进行国际化新开国的重点项目推进及进度管理工作，包括做好目标及关键任务拆解、资源协调、进度跟进、过程监控、风险识别等，对项目进度负责\nAssist country GM in promoting key projects and managing progress for new international markets, including decomposing goals and key tasks, coordinating resources, following up on progress, monitoring processes, identifying risks, etc., and being responsible for project timelines.\n\n2、深入理解业务，识别组织效率、运营工具等领域的问题，开发适配中东、拉美等新开国业务的项目管理手册，明确跨团队协作SOP，提高决策及执行效率，提升组织效能\nDeeply understand the business, identify issues in organizational efficiency, operational tools, and other areas, develop project management manuals tailored to new markets such as the Middle East and Latin America, clarify cross-team collaboration SOPs, improve decision-making and execution efficiency, and enhance organizational effectiveness.\n\n\n3、跨国管理背景下，设计并实施文化适配机制，建立多时区协作规范与本地化合规框架，制定敏感事项预案，保障跨国团队高效协同\nIn a cross-border management context, design and implement culturally adaptive mechanisms, establish multi-time zone collaboration norms and localized compliance frameworks, formulate contingency plans for sensitive matters, and ensure efficient collaboration of cross-border teams.\n\n4、 具备较强的团队合作精神、执行力及在快节奏环境中的工作能力，能够推动跨部门协作，并确保战略计划的高效执行\nPossess strong teamwork spirit, execution ability, and work capability in a fast-paced environment, able to promote cross-departmental collaboration and ensure the efficient implementation of strategic plans.","requirements":"1、本科及以上学历，7年以上工作经验，3年以上互联网/科技等行业公司项目管理经验\nBachelor's degree or above, with more than 7 years of work experience, including over 3 years of project management experience in internet/technology and other industries.\n\n2、有丰富项目管理和项目管理体系建设经验，有较强的逻辑思考能力、数据洞察和分析能力、复杂问题的发现和拆解能力\nRich experience in project management and project management system construction, with strong logical thinking ability, data insight and analysis ability, and the ability to identify and decompose complex problems.\n\n3、有具备较强的团队合作精神、执行力及在快节奏环境中的工作能力，能够推动跨部门、跨时区协作，并确保战略计划的高效执行\nHave strong teamwork spirit, execution ability, and work capability in a fast-paced environment, able to promote cross-departmental and cross-time zone collaboration, and ensure the efficient implementation of strategic plans.\n\n4、可将英文作为工作语言，具备良好的跨文化适应能力和敏感度，能够在多元文化环境中高效工作\nFluent English capability as primary working language, possess good cross-cultural adaptation ability and sensitivity, and can work efficiently in a multicultural environment.\n\n5、愿意深入国际化业务，进行跨国出差或外派\nPassion for deeply engaging in and driving international business expansion. Willingness and ability to undertake s cross-border travel or medium-to-long-term international assignments based on business needs.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、协助业务负责人进行国际化新开国的重点项目推进及进度管理工作，包括做好目标及关键任务拆解、资源协调、进度跟进、过程监控、风险识别等，对项目进度负责\nAssist country GM in promoting key projects and managing progress for new international markets, including decomposing goals and key tasks, coordinating resources, following up on progress, monitoring processes, identifying risks, etc., and being responsible for project timelines.\n\n2、深入理解业务，识别组织效率、运营工具等领域的问题，开发适配中东、拉美等新开国业务的项目管理手册，明确跨团队协作SOP，提高决策及执行效率，提升组织效能\nDeeply understand the business, identify issues in organizational efficiency, operational tools, and other areas, develop project management manuals tailored to new markets such as the Middle East and Latin America, clarify cross-team collaboration SOPs, improve decision-making and execution efficiency, and enhance organizational effectiveness.\n\n\n3、跨国管理背景下，设计并实施文化适配机制，建立多时区协作规范与本地化合规框架，制定敏感事项预案，保障跨国团队高效协同\nIn a cross-border management context, design and implement culturally adaptive mechanisms, establish multi-time zone collaboration norms and localized compliance frameworks, formulate contingency plans for sensitive matters, and ensure efficient collaboration of cross-border teams.\n\n4、 具备较强的团队合作精神、执行力及在快节奏环境中的工作能力，能够推动跨部门协作，并确保战略计划的高效执行\nPossess strong teamwork spirit, execution ability, and work capability in a fast-paced environment, able to promote cross-departmental collaboration and ensure the efficient implementation of strategic plans.\n\n岗位基本要求\n1、本科及以上学历，7年以上工作经验，3年以上互联网/科技等行业公司项目管理经验\nBachelor's degree or above, with more than 7 years of work experience, including over 3 years of project management experience in internet/technology and other industries.\n\n2、有丰富项目管理和项目管理体系建设经验，有较强的逻辑思考能力、数据洞察和分析能力、复杂问题的发现和拆解能力\nRich experience in project management and project management system construction, with strong logical thinking ability, data insight and analysis ability, and the ability to identify and decompose complex problems.\n\n3、有具备较强的团队合作精神、执行力及在快节奏环境中的工作能力，能够推动跨部门、跨时区协作，并确保战略计划的高效执行\nHave strong teamwork spirit, execution ability, and work capability in a fast-paced environment, able to promote cross-departmental and cross-time zone collaboration, and ensure the efficient implementation of strategic plans.\n\n4、可将英文作为工作语言，具备良好的跨文化适应能力和敏感度，能够在多元文化环境中高效工作\nFluent English capability as primary working language, possess good cross-cultural adaptation ability and sensitivity, and can work efficiently in a multicultural environment.\n\n5、愿意深入国际化业务，进行跨国出差或外派\nPassion for deeply engaging in and driving international business expansion. Willingness and ability to undertake s cross-border travel or medium-to-long-term international assignments based on business needs.\n\n具备以下条件优先\n1、具有外卖、电商或互联网行业的战略规划、商业分析或管理咨询经验，有跨部门协作及项目管理经验加分\nExperience in strategic planning, business analysis, or management consulting in the food delivery, e-commerce, or internet industry, with cross-departmental collaboration and project management experience preferred.\n\n2、对外卖行业的全球商业模式、用户行为、市场动态有深入了解，具备一定的外卖平台运营经验加分\nIn-depth understanding of the global business models, user behavior, and market dynamics of the food delivery industry, with certain operational experience in food delivery platforms preferred.\n\n3、有国际咨询经验，曾成功帮助中国公司出海经验加分\nExperience in top international consulting and successful cases of helping Chinese companies go global preferred\n\n4、可将阿拉伯语、葡萄牙语作为工作语言，对中东、拉美市场有相关经验者加分\nProficiency in Arabic or Portuguese for business communication is advantageous, with relevant experience in the Middle East and Latin American markets preferred.\n\n岗位亮点\n1、与全球竞争者同台竞技：拓宽你的国际商业视野，积累实战经验\n2、与来自26个国家的同事合作：在真正国际化的环境中体验多元文化与创业精神\n3、加入高速发展的业务：参与塑造外卖行业的未来，为这一快速演变的行业做出贡献","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2676335243","sourceKey":"meituan_social","company":"美团","title":"大模型算法专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2676335243&jobShareType=1","duty":"1. 从flops efficiency角度，对大模型预训练过程进行分析与探索，包括不限于对scaling law的研究，数据的认知实验，MoE等模型架构设计，以及其他工程与算法结合的ml sys相关优化等。\n2. 负责原生多模态大模型的构建与预训练，包括各模态分词器设计，合成数据策略，以及跨模态融合训练策略等，提升原生多模态模型在视觉/语音的理解与生成任务上的能力。\n3. 进行大模型reasoning能力的相关研究，研究pre-train / test-time compute对于模型推理能力的影响，借助SFT / DPO / self-play等手段，提高模型在代码数学等推理任务上的表现。\n4. 通过post-training激发模型在各下游任务上的能力，从而构建具有通用问题解决能力的agent。","requirements":"1. 对大模型有技术热情，熟悉GPT/BERT/T5等模型的原理；\n2. 熟悉Python，熟练使用TensorFlow/PyTorch/Megatron/Triton等深度学习训练或推理框架，熟悉java/C++中的一种。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 从flops efficiency角度，对大模型预训练过程进行分析与探索，包括不限于对scaling law的研究，数据的认知实验，MoE等模型架构设计，以及其他工程与算法结合的ml sys相关优化等。\n2. 负责原生多模态大模型的构建与预训练，包括各模态分词器设计，合成数据策略，以及跨模态融合训练策略等，提升原生多模态模型在视觉/语音的理解与生成任务上的能力。\n3. 进行大模型reasoning能力的相关研究，研究pre-train / test-time compute对于模型推理能力的影响，借助SFT / DPO / self-play等手段，提高模型在代码数学等推理任务上的表现。\n4. 通过post-training激发模型在各下游任务上的能力，从而构建具有通用问题解决能力的agent。\n\n岗位基本要求\n1. 对大模型有技术热情，熟悉GPT/BERT/T5等模型的原理；\n2. 熟悉Python，熟练使用TensorFlow/PyTorch/Megatron/Triton等深度学习训练或推理框架，熟悉java/C++中的一种。\n\n具备以下条件优先\n1. 有SIGIR、ACL、WWW等NLP/搜索领域顶会论文发表经验；\n2. 有KDDCup、RecSys、Kaggle、天池等机器学习比赛获奖经验；\n3. 有主流多模态大模型（跨视觉/语音/文本模态，Gemini、GPT-4o、Chameleon、Tortoise TTS等）相关的研究或工作经历\n\n岗位亮点\n1. 团队资源丰富，技术审美优秀，在MoE、原生多模、scaling law、self-play等技术方向都有较为前沿的探索经验。\n2. 原生多模统一理解与生成，探索空间巨大，能力天花板高。团队在原生多模领域起步较早，具有充分的实践经验和行业一流的认知。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4207762592","sourceKey":"meituan_social","company":"美团","title":"Senior Talent Acquisition Manager 海外高级招聘经理","city":"北京市/上海市/深圳市/圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4207762592&jobShareType=1","duty":"1. Work closely with business in order to deeply understand teams’ organization structure, responsibilities, strengths/weaknesses and key business drivers. Utilize this information to develop the most effective recruiting strategies.\n2. Capable to build and maintain network of potential candidates through proactive market research and on-going relationship management, gauging chemistry of candidates for fit and motivation rather than simply sell a role. Meanwhile, manage to ensure all necessary sourcing channels are quickly built up and sufficiently utilized.\n3. Use a sound recruiting process to effectively scale the business, including guidance on job descriptions, levels, selection process & criteria, closing and onboarding.\n4. Have an active participation in the full cycle of recruitment efforts, including emphasis on the ability of assessment skills to help screening, evaluating candidates and ensuring the highest bar.\n5. Lead the hiring calibration and decision making process, while being in charge of the offer proposal and negotiation process.\n6. Have the data acumen. Being able to dive deep the recruiting process as needed to identify the issues ahead and diagnose the root causes effectively.\n7. Emphasis on continuous improvement, as such it is expected that you will spend time to ensure ongoing education/enablement towards hiring managers and interviewers on recruitment “best practice”, to uplift the recruiting skills in the organization wise.\n8. Join or lead cross-team recruiting/HR projects as needed.","requirements":"Bachelor’s degree in Human Resources, Business Administration, or related field.\nMinimum of 5 years of strategic recruiting experience, preferably in an international business context.\nProven track record of successfully recruiting for complex and senior-level positions.\nStrong understanding of global labor markets and international hiring practices.\nExcellent communication and interpersonal skills.\nAbility to work independently and manage multiple priorities in a fast-paced environment.\nProficiency in using Applicant Tracking Systems (ATS) and other recruitment tools.\nHigh level of discretion and professionalism.\nWith experience and ability in using various AI tools.","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. Work closely with business in order to deeply understand teams’ organization structure, responsibilities, strengths/weaknesses and key business drivers. Utilize this information to develop the most effective recruiting strategies.\n2. Capable to build and maintain network of potential candidates through proactive market research and on-going relationship management, gauging chemistry of candidates for fit and motivation rather than simply sell a role. Meanwhile, manage to ensure all necessary sourcing channels are quickly built up and sufficiently utilized.\n3. Use a sound recruiting process to effectively scale the business, including guidance on job descriptions, levels, selection process & criteria, closing and onboarding.\n4. Have an active participation in the full cycle of recruitment efforts, including emphasis on the ability of assessment skills to help screening, evaluating candidates and ensuring the highest bar.\n5. Lead the hiring calibration and decision making process, while being in charge of the offer proposal and negotiation process.\n6. Have the data acumen. Being able to dive deep the recruiting process as needed to identify the issues ahead and diagnose the root causes effectively.\n7. Emphasis on continuous improvement, as such it is expected that you will spend time to ensure ongoing education/enablement towards hiring managers and interviewers on recruitment “best practice”, to uplift the recruiting skills in the organization wise.\n8. Join or lead cross-team recruiting/HR projects as needed.\n\n岗位基本要求\nBachelor’s degree in Human Resources, Business Administration, or related field.\nMinimum of 5 years of strategic recruiting experience, preferably in an international business context.\nProven track record of successfully recruiting for complex and senior-level positions.\nStrong understanding of global labor markets and international hiring practices.\nExcellent communication and interpersonal skills.\nAbility to work independently and manage multiple priorities in a fast-paced environment.\nProficiency in using Applicant Tracking Systems (ATS) and other recruitment tools.\nHigh level of discretion and professionalism.\nWith experience and ability in using various AI tools.\n\n具备以下条件优先\nExperience in the technology or e-commerce industry.\nMultilingual capabilities.\n\n岗位亮点\nKeeta by Meituan is at the forefront of our international expansion, aiming to provide exceptional service and innovative solutions across borders. We are dedicated to fostering a dynamic and diverse workforce that aligns with our global growth strategies.\nWhat We Offer:\nOpportunity to work in an international, dynamic environment.\nCareer growth and development opportunities.\nSupportive and collaborative team culture.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4012014886","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-前置仓主管（杭州）","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4012014886&jobShareType=1","duty":"1.管辖10-13个酒水前置仓的业务开拓和日常管理;\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰;\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标;\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性;\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验;\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题;\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。","requirements":"1.有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验;\n2.熟悉即时配业务特性，关注用户体验;\n3.有较好的团队管理，人员培养的经验和方法沉淀;\n4.有价值观正，能够横向协同多部门，达成公司业务指标;\n5.有较好的数据敏感度，能够透过数据发现问题。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.管辖10-13个酒水前置仓的业务开拓和日常管理;\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰;\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标;\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性;\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验;\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题;\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。\n\n岗位基本要求\n1.有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验;\n2.熟悉即时配业务特性，关注用户体验;\n3.有较好的团队管理，人员培养的经验和方法沉淀;\n4.有价值观正，能够横向协同多部门，达成公司业务指标;\n5.有较好的数据敏感度，能够透过数据发现问题。\n\n具备以下条件优先\n熟悉零售业务，有前置仓管理，商品管理经验优先\n\n岗位亮点\n[歪马业务]是【到家事业群/闪购业务部]下新成立的，由前线业务+运营/采购+产品全闭环的组织\n2.歪马业务聚焦于酒类万亿市场，通过中心仓+前置仓、平台自营模式，为用户提供15分钟送达的买酒业务\n3.业务当前正处于0-1的快速迭代时期，可以从0-1参与新业务的产品建设\n4.全方位深入业务，在全闭环的组织里感受不同职能彼此的输入/输出，同时可以参与业务模式的定义\n5.足够宽的Scope，深入参与自营零售业务的经营","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3912959639","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-区域酒水鉴真师","city":"北京市/上海市/广州市/武汉市/重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3912959639&jobShareType=1","duty":"1、熟练掌握酒水行业鉴真技术及方法，能够输出鉴真策略并协同各方推进策略落地。\n2、负责仓内酒水鉴定，能够输出标准化鉴定程序文件，持续验证并迭代标准，保证标准有效性。\n3、沉淀鉴定数据并进行统计分析，能够快速识别风险并推动治理改善闭环。\n4、定期对总部和仓内相关人员开展鉴定知识培训，协同售后客诉处置，提振用户消费信心。\n5、联合三方服务商开展鉴真专项，优化服务商鉴定流程。","requirements":"1、本科及以上学历，5年及以上行业工作经验，拥有酒水鉴真相关资质证书者优先。\n2、能够鉴定名优白酒、洋酒等，具备培训赋能经验。\n3、拥有行业协会、头部酒企等信息资源，能够对专业知识持续输入与更新。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1、熟练掌握酒水行业鉴真技术及方法，能够输出鉴真策略并协同各方推进策略落地。\n2、负责仓内酒水鉴定，能够输出标准化鉴定程序文件，持续验证并迭代标准，保证标准有效性。\n3、沉淀鉴定数据并进行统计分析，能够快速识别风险并推动治理改善闭环。\n4、定期对总部和仓内相关人员开展鉴定知识培训，协同售后客诉处置，提振用户消费信心。\n5、联合三方服务商开展鉴真专项，优化服务商鉴定流程。\n\n岗位基本要求\n1、本科及以上学历，5年及以上行业工作经验，拥有酒水鉴真相关资质证书者优先。\n2、能够鉴定名优白酒、洋酒等，具备培训赋能经验。\n3、拥有行业协会、头部酒企等信息资源，能够对专业知识持续输入与更新。\n\n岗位亮点\n1、歪马业务聚焦酒类万亿市场，通过前置仓+中心仓，平台自营+加盟模式，为用户提供15分钟送达的买酒服务。\n2、全方位深入业务，在全闭环的组织里感受不同职能彼此的输入/输出，参与业务模式的定义。\n3、足够宽的Scope，深入参与即时零售业务的经营，带动业务和团队一起成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3839988596","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-前置仓区域主管（上海）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3839988596&jobShareType=1","duty":"1.管辖10-13个酒水前置仓的业务开拓和日常管理；\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰；\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标；\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性；\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验；\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题；\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。","requirements":"1.本科学历，有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验；\n2.熟悉即时配业务特性，关注用户体验；\n3.有较好的团队管理，人员培养的经验和方法沉淀；\n4.有价值观正，能够横向协同多部门，达成公司业务指标；\n5.有较好的数据敏感度，能够透过数据发现问题。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.管辖10-13个酒水前置仓的业务开拓和日常管理；\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰；\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标；\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性；\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验；\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题；\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。\n\n岗位基本要求\n1.本科学历，有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验；\n2.熟悉即时配业务特性，关注用户体验；\n3.有较好的团队管理，人员培养的经验和方法沉淀；\n4.有价值观正，能够横向协同多部门，达成公司业务指标；\n5.有较好的数据敏感度，能够透过数据发现问题。\n\n具备以下条件优先\n熟悉零售业务，有销售管理，前置仓管理，商品管理经验优先\n\n岗位亮点\n1.【歪马业务】是【到家事业群/闪购业务部】下新成立的，由前线业务+运营/采购+产品全闭环的组织\n2.歪马业务聚焦于酒类万亿市场，通过中心仓+前置仓、平台自营模式，为用户提供15分钟送达的买酒业务\n3.业务当前正处于0-1的快速迭代时期，可以从0-1参与新业务的产品建设\n4.全方位深入业务，在全闭环的组织里感受不同职能彼此的输入/输出，同时可以参与业务模式的定义\n5.足够宽的Scope，深入参与自营零售业务的经营","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3620775010","sourceKey":"meituan_social","company":"美团","title":"核心本地商业薪酬CBG","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3620775010&jobShareType=1","duty":"1. 薪酬策略：参与制定核心本地商业部门的薪酬绩效策略与政策，确保激励机制与业务目标高度对齐，推动薪酬体系持续优化；需具备5年以上薪酬绩效管理经验，有薪酬政策设计经验者优先。\n2. 薪酬调研：善用 AI 工具开展市场薪酬调研与竞争力评估，结合数据洞察与行业实践，为业务提供兼具竞争力与落地性的薪酬方案。\n3. 数据分析与洞察：构建薪酬健康度分析体系，结合人才策略提炼薪酬核心指标，定期向业务输出薪酬健康度报告及专业解读，支持管理层决策；需具备扎实的数据分析能力，熟练使用数据分析工具，并能借助 AI 提升数据处理与洞察效率。\n4. 人力预算管理：参与人力预算的制定与执行，持续追踪预算执行情况及效率指标变化趋势，结合业务实际主动提出优化建议，确保资源投入的合理性与可持续性。\n5. 沟通协作：负责薪酬政策在业务部门的落地执行与定制化方案输出，具备良好的跨团队沟通与协调能力，能与多方高效协作推动事项落地。\n6. 薪酬运营与 AI 赋能：主导薪酬运营流程的标准化与规范化建设，运用 AI 工具推动数字化转型与全面提效；具备系统化流程思维，能将重复性工作梳理为可复用的标准流程；积极探索 AI 在薪酬分析、报告撰写、流程自动化等场景的创新应用。","requirements":"1.至少5年以上薪酬绩效管理经验，有薪酬政策设计相关经验者优先。\n2.具备良好的数据分析和解决问题的能力，能够根据数据提出有效的薪酬方案。\n3.具备优秀的沟通和协调能力，能够与不同层级的员工进行有效的沟通和合作。\n4.具备团队合作精神，能够在团队中积极参与，推动变化。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 薪酬策略：参与制定核心本地商业部门的薪酬绩效策略与政策，确保激励机制与业务目标高度对齐，推动薪酬体系持续优化；需具备5年以上薪酬绩效管理经验，有薪酬政策设计经验者优先。\n2. 薪酬调研：善用 AI 工具开展市场薪酬调研与竞争力评估，结合数据洞察与行业实践，为业务提供兼具竞争力与落地性的薪酬方案。\n3. 数据分析与洞察：构建薪酬健康度分析体系，结合人才策略提炼薪酬核心指标，定期向业务输出薪酬健康度报告及专业解读，支持管理层决策；需具备扎实的数据分析能力，熟练使用数据分析工具，并能借助 AI 提升数据处理与洞察效率。\n4. 人力预算管理：参与人力预算的制定与执行，持续追踪预算执行情况及效率指标变化趋势，结合业务实际主动提出优化建议，确保资源投入的合理性与可持续性。\n5. 沟通协作：负责薪酬政策在业务部门的落地执行与定制化方案输出，具备良好的跨团队沟通与协调能力，能与多方高效协作推动事项落地。\n6. 薪酬运营与 AI 赋能：主导薪酬运营流程的标准化与规范化建设，运用 AI 工具推动数字化转型与全面提效；具备系统化流程思维，能将重复性工作梳理为可复用的标准流程；积极探索 AI 在薪酬分析、报告撰写、流程自动化等场景的创新应用。\n\n岗位基本要求\n1.至少5年以上薪酬绩效管理经验，有薪酬政策设计相关经验者优先。\n2.具备良好的数据分析和解决问题的能力，能够根据数据提出有效的薪酬方案。\n3.具备优秀的沟通和协调能力，能够与不同层级的员工进行有效的沟通和合作。\n4.具备团队合作精神，能够在团队中积极参与，推动变化。\n\n岗位亮点\n1. 直接参与核心业务团队激励政策设计，具备较强的业务影响力。\n2. 与高层管理团队深度合作，提供专业的薪酬绩效咨询与战略支持。\n3. 深度实践「AI + 薪酬运营」前沿模式，在 HR 数字化方向建立差异化核心竞争力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3997039078","sourceKey":"meituan_social","company":"美团","title":"Key Account Manager","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3997039078&jobShareType=1","duty":"1. Brand Acquisition & Operations\nTake full responsibility for the acquisition, onboarding, and ongoing operations of chain restaurant brands. Conduct market research and establish relationships with target clients in new markets, and manage the entire brand integration process from onboarding to day-to-day operations. Own key performance indicators—including foundational business metrics and growth results—and drive deep collaboration between brands and the platform across brand marketing, promotional strategies, and joint campaigns. Ensure effective execution of the company’s sales strategies and achievement of performance targets.\n\n2. Industry Insight & Analysis\nDevelop comprehensive insights into the business status and strategic needs of each brand based on industry characteristics and operational models. Utilize data-driven analysis to design professional and actionable food delivery growth solutions, and lead their implementation to improve operational efficiency and online performance.\n\n3. Cross-Functional Collaboration\nEstablish efficient collaboration mechanisms with internal cross-functional teams. Act as the key liaison between brands and the platform, coordinating resources across delivery, product, operations, and marketing teams. Ensure high-quality project execution and continuously optimize coordination efficiency and operational outcomes.\n\n4. Market Intelligence & Feedback\nProactively gather frontline market intelligence and provide actionable strategic insights. This includes industry trends, user feedback, competitive dynamics, and local market movements. Deliver valuable recommendations to support company decision-making and drive continuous business optimization.","requirements":"1、Demonstrates strong business negotiation and market development capabilities, maintains clear goal orientation, has keen insight into user needs, and is willing to take on challenges.\n\n2、Possesses solid data analysis skills, is proficient in using office software, and has practical experience in analyzing and presenting data through charts and visual tools.\n\n3、Has experience in food delivery operations or internet operations, understands basic operational logic, learns quickly, and can grow rapidly in real business scenarios.\n\n4、Shows integrity, reliability, and professionalism, with strong stress tolerance, high work enthusiasm, and excellent team spirit.\n\n5、Able to use English and Portuguese proficiently as daily working languages.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. Brand Acquisition & Operations\nTake full responsibility for the acquisition, onboarding, and ongoing operations of chain restaurant brands. Conduct market research and establish relationships with target clients in new markets, and manage the entire brand integration process from onboarding to day-to-day operations. Own key performance indicators—including foundational business metrics and growth results—and drive deep collaboration between brands and the platform across brand marketing, promotional strategies, and joint campaigns. Ensure effective execution of the company’s sales strategies and achievement of performance targets.\n\n2. Industry Insight & Analysis\nDevelop comprehensive insights into the business status and strategic needs of each brand based on industry characteristics and operational models. Utilize data-driven analysis to design professional and actionable food delivery growth solutions, and lead their implementation to improve operational efficiency and online performance.\n\n3. Cross-Functional Collaboration\nEstablish efficient collaboration mechanisms with internal cross-functional teams. Act as the key liaison between brands and the platform, coordinating resources across delivery, product, operations, and marketing teams. Ensure high-quality project execution and continuously optimize coordination efficiency and operational outcomes.\n\n4. Market Intelligence & Feedback\nProactively gather frontline market intelligence and provide actionable strategic insights. This includes industry trends, user feedback, competitive dynamics, and local market movements. Deliver valuable recommendations to support company decision-making and drive continuous business optimization.\n\n岗位基本要求\n1、Demonstrates strong business negotiation and market development capabilities, maintains clear goal orientation, has keen insight into user needs, and is willing to take on challenges.\n\n2、Possesses solid data analysis skills, is proficient in using office software, and has practical experience in analyzing and presenting data through charts and visual tools.\n\n3、Has experience in food delivery operations or internet operations, understands basic operational logic, learns quickly, and can grow rapidly in real business scenarios.\n\n4、Shows integrity, reliability, and professionalism, with strong stress tolerance, high work enthusiasm, and excellent team spirit.\n\n5、Able to use English and Portuguese proficiently as daily working languages.\n\n具备以下条件优先\n1. Possesses relevant work experience in the food delivery, restaurant, or retail industry.\n2. Has working proficiency in Chinese–English–Portuguese or English–Portuguese communication.\n\n岗位亮点\n1、Hands-on Experience in Global Market Expansion — Deeply engage in cross-border collaboration and drive business rollout in a diverse, multicultural environment.\n\n2、Drive New Business from 0 to 1 — Participate end-to-end in brand acquisition, onboarding processes, promotion strategies, and data-driven growth initiatives, contributing directly to building a new market from the ground up.\n\n3、Opportunities to Work with Top Brazilian Restaurant Chains — Collaborate directly with leading foodservice groups, advance partnership discussions, and co-develop strategic growth plans.\n\n4、Comprehensive Understanding of Platform Operations — Work closely with product, operations, delivery, legal, finance, and other cross-functional teams to strengthen full-chain operational capabilities.\n\n5、Develop Operational Methodologies in an Innovation-Driven Environment — Engage deeply in core strategic mechanisms such as subsidies, promotion logic, and delivery capacity building, and develop replicable, scalable growth methodologies.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3936259093","sourceKey":"meituan_social","company":"美团","title":"眼镜KA大客户销售经理（北京+上海）","city":"北京市/上海市/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3936259093&jobShareType=1","duty":"1.负责管理眼镜行业KA重点客户达成业务交易份额和广告份额，实现合理增量；\n2.负责制定并实施市场推广策略，提升重点客户在市场的知名度和销售额；\n3.协调内外部资源，深入大客户经营管理，与大客户深入合作，建立并维护良好的客户关系；\n4.监控市场动态，分析竞争对手的策略和行动，及时调整销售策略以保持市场竞争力；\n5.负责个人目标的设定与达成，参与制定并执行销售计划，完成销售目标，并定期向上级汇报工作进展和销售情况；","requirements":"1.大学本科及以上学历，具备眼镜行业或连锁行业经验背景优先。\n2.至少3年以上大客户拓展或销售管理经验，具备较好的用户需求和客户需求洞察力、市场行业洞察力和商务谈判能力。\n3.具备良好的沟通能力和团队合作精神，能够有效协调内外部资源，解决问题并达成共识。\n4.具备较强的自我驱动能力，能够承担较大的工作压力和销售目标。\n5.具备团队管理经验优先考虑。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.负责管理眼镜行业KA重点客户达成业务交易份额和广告份额，实现合理增量；\n2.负责制定并实施市场推广策略，提升重点客户在市场的知名度和销售额；\n3.协调内外部资源，深入大客户经营管理，与大客户深入合作，建立并维护良好的客户关系；\n4.监控市场动态，分析竞争对手的策略和行动，及时调整销售策略以保持市场竞争力；\n5.负责个人目标的设定与达成，参与制定并执行销售计划，完成销售目标，并定期向上级汇报工作进展和销售情况；\n\n岗位基本要求\n1.大学本科及以上学历，具备眼镜行业或连锁行业经验背景优先。\n2.至少3年以上大客户拓展或销售管理经验，具备较好的用户需求和客户需求洞察力、市场行业洞察力和商务谈判能力。\n3.具备良好的沟通能力和团队合作精神，能够有效协调内外部资源，解决问题并达成共识。\n4.具备较强的自我驱动能力，能够承担较大的工作压力和销售目标。\n5.具备团队管理经验优先考虑。\n\n岗位亮点\n1.作为大客户经理，将直接参与公司的业务拓展和市场渗透，为公司的发展做出重要贡献。\n2.在担任大客户经理的岗位上，将有机会与知名连锁企业展开合作，提升个人销售能力和人际交往能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3260961013","sourceKey":"meituan_social","company":"美团","title":"履约-渠道经理-汕头、惠州、揭阳、潮州","city":"潮州市/汕头市/惠州市/揭阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3260961013&jobShareType=1","duty":"1.负责美团外卖配送业务在辖区内配送渠道商的选、用、育、留等工作，促进辖区内营商环境改善，优化渠道商组织能力，促进渠道商盈亏分析能力提升及业务运营能力提升；\n2.负责美团外卖配送渠道政策在辖区内配送渠道商的贯彻执行，按节点部署管理政策执行，并达成预期效果形成反馈；\n3.负责辖区内合作商赋能，通过业务辅导、经验总结，组织培训等管理方法提升合作商能力，保障配送业务目标达成；\n4.负责辖区内业务优化，通过联动总部以及多部门协同综效，实现履约目标达成、履约经营效率和用户体验提升；\n5.对渠道商的整体配送行为进行质量管理和监控，监督并检核渠道商各种非公平竞争手段和违约操作行为，完成虚假申诉等行为的审核及处罚；\n6.协同总部推动新业务或新项目的推广工作，从一线角度推进新业务或新产品项目试点落地，达成阶段性项目目标并及时给出反馈；\n7.负责辖区安全工作的推进及协同，处理突发事件及异常事故，通过事前宣导、检核事中积极处置应对、事后复盘等进行风险规避及处置。","requirements":"1.本科及以上学历，3年及以上渠道商管理经验，互联网配送行业、快递物流行业管理经验者优先考虑;\n2.业务管理：具有一定的行业认知，能够了解业务关键要素，有数据分析能力，能够根据业务现状进行目标拆解和策略制定;\n3.商赋能：有一定渠道管理经验，能对商内部业务运营、组织能力、盈亏方面整体赋能，推动合作商成长;\n4.通用能力：工作中坚持客户导向、有较好的人际沟通能力、学习能力和问题解决能力。","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n1.负责美团外卖配送业务在辖区内配送渠道商的选、用、育、留等工作，促进辖区内营商环境改善，优化渠道商组织能力，促进渠道商盈亏分析能力提升及业务运营能力提升；\n2.负责美团外卖配送渠道政策在辖区内配送渠道商的贯彻执行，按节点部署管理政策执行，并达成预期效果形成反馈；\n3.负责辖区内合作商赋能，通过业务辅导、经验总结，组织培训等管理方法提升合作商能力，保障配送业务目标达成；\n4.负责辖区内业务优化，通过联动总部以及多部门协同综效，实现履约目标达成、履约经营效率和用户体验提升；\n5.对渠道商的整体配送行为进行质量管理和监控，监督并检核渠道商各种非公平竞争手段和违约操作行为，完成虚假申诉等行为的审核及处罚；\n6.协同总部推动新业务或新项目的推广工作，从一线角度推进新业务或新产品项目试点落地，达成阶段性项目目标并及时给出反馈；\n7.负责辖区安全工作的推进及协同，处理突发事件及异常事故，通过事前宣导、检核事中积极处置应对、事后复盘等进行风险规避及处置。\n\n岗位基本要求\n1.本科及以上学历，3年及以上渠道商管理经验，互联网配送行业、快递物流行业管理经验者优先考虑;\n2.业务管理：具有一定的行业认知，能够了解业务关键要素，有数据分析能力，能够根据业务现状进行目标拆解和策略制定;\n3.商赋能：有一定渠道管理经验，能对商内部业务运营、组织能力、盈亏方面整体赋能，推动合作商成长;\n4.通用能力：工作中坚持客户导向、有较好的人际沟通能力、学习能力和问题解决能力。\n\n具备以下条件优先\n1.具备良好的商管意识，在合作商选、育、励、汰环节，有基础的方法和技巧；\n2.出色的人际沟通能力、团队协作精神、积极乐观，敢于挑战，为人正直，诚实可靠；\n3.有较好的适应能力，能接受区域内轮岗。\n\n岗位亮点\n1.该岗位信息量摄取丰富而全面，加入我们可锻炼并提高前线加盟管理能力及后线策略协同能力，帮助你快速发展成为行业复合专业人才；\n2.大平台管理体系学习机会：能够深入学习O2O行业成熟的大数据管理体系，以及平台运营和管理的高效流程机制；\n3.成长空间大：业务发展前景好，可以全面提升个人综合能力，助力个人成长；\n4.岗位晋升机制完善，整体晋升成长体系健全，晋升机会较多。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4130756170","sourceKey":"meituan_social","company":"美团","title":"小象超市-品控运营-流程管理方向","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4130756170&jobShareType=1","duty":"1. 负责制定和优化商品品质管理流程，确保流程高效且符合行业标准。  \n2. 主导跨部门协作，推动流程落地并持续改进，提升整体运营效率。  \n3. 建立并维护品控运营标准，监督执行效果，推动流程持续优化迭代。\n4. 全生命周期做流程管理项目，包括需求分析、流程方案设计、实施与复盘。  \n5. 监控关键质量指标，识别风险并制定应对措施，保障业务稳定运行。","requirements":"1. 大学本科及以上学历，供应链管理、质量管理或相关专业优先。  \n2. 5年以上商品与供应链品质管理或流程优化相关经验，具备流程设计或项目管理经验。  \n3. 具备较强的数据分析能力和跨团队沟通能力，能自主闭环推动复杂项目落地。\n4.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责制定和优化商品品质管理流程，确保流程高效且符合行业标准。  \n2. 主导跨部门协作，推动流程落地并持续改进，提升整体运营效率。  \n3. 建立并维护品控运营标准，监督执行效果，推动流程持续优化迭代。\n4. 全生命周期做流程管理项目，包括需求分析、流程方案设计、实施与复盘。  \n5. 监控关键质量指标，识别风险并制定应对措施，保障业务稳定运行。\n\n岗位基本要求\n1. 大学本科及以上学历，供应链管理、质量管理或相关专业优先。  \n2. 5年以上商品与供应链品质管理或流程优化相关经验，具备流程设计或项目管理经验。  \n3. 具备较强的数据分析能力和跨团队沟通能力，能自主闭环推动复杂项目落地。\n4.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1. 参与公司核心业务，直接影响商品品质流程顺畅及部门运转效能。\n2. 提供系统化培训与职业发展通道，助力个人能力提升。  \n3. 团队氛围开放，鼓励创新并注重结果导向。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4233893869","sourceKey":"meituan_social","company":"美团","title":"资深渠道经理","city":"郑州市/武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4233893869&jobShareType=1","duty":"工作职责：\n1. 负责完成渠道合作伙伴，帮助合伙人快速建立运营机制与管理，并把业务下沉，达成目标；\n2. 研究分析渠道组成和特点，发展渠道合作伙伴，并对所负责的渠道进行规划和培养，推动渠道合作伙伴达成经营目标任务；\n3. 跟踪考核渠道商，并及时发现合作过程的问题并进行总结和反馈，跟进问题的优化；\n4. 负责合作伙伴的培训和其他相关支持的落地，辅助商项目所涉及的内部部门沟通协调；\n6. 搜集反馈市场信息，分析市场数据；\n7. 传达公司政策及市场活动等信息，保证和商之间的沟通顺畅。","requirements":"1. 有丰富的渠道开发和渠道维护经验，或互联网销售管理经验者优先考虑；\n2. 学习能力强，对渠道销售模式有比较深刻的认知，有能力总结不同类型渠道合作伙伴的合作模式；\n3. 沟通能力强，有能力协调并解决联合落地项目中遇到的问题；\n4. 能够承受压力和挑战，有团队协作精神和较强的服务意识。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n工作职责：\n1. 负责完成渠道合作伙伴，帮助合伙人快速建立运营机制与管理，并把业务下沉，达成目标；\n2. 研究分析渠道组成和特点，发展渠道合作伙伴，并对所负责的渠道进行规划和培养，推动渠道合作伙伴达成经营目标任务；\n3. 跟踪考核渠道商，并及时发现合作过程的问题并进行总结和反馈，跟进问题的优化；\n4. 负责合作伙伴的培训和其他相关支持的落地，辅助商项目所涉及的内部部门沟通协调；\n6. 搜集反馈市场信息，分析市场数据；\n7. 传达公司政策及市场活动等信息，保证和商之间的沟通顺畅。\n\n岗位基本要求\n1. 有丰富的渠道开发和渠道维护经验，或互联网销售管理经验者优先考虑；\n2. 学习能力强，对渠道销售模式有比较深刻的认知，有能力总结不同类型渠道合作伙伴的合作模式；\n3. 沟通能力强，有能力协调并解决联合落地项目中遇到的问题；\n4. 能够承受压力和挑战，有团队协作精神和较强的服务意识。\n\n具备以下条件优先\n有渠道代理商开发经验者优先\n\n岗位亮点\n聚焦于商开发和维护，跨区域管理成长更快、广阔晋升空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:1051080585","sourceKey":"meituan_social","company":"美团","title":"乐生活西南大区-产品销售","city":"武汉市/成都市/重庆市/海口市/昆明市/南宁市/三亚市/中山市/珠海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=1051080585&jobShareType=1","duty":"1、通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2、执行公司的销售策略及政策，达成业绩目标；\n3、与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4、归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","requirements":"1、大专及以上学历，有销售工作经验优先；\n2、有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛，具备出色完成任务的能力；\n3、具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4、富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6、为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1、通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2、执行公司的销售策略及政策，达成业绩目标；\n3、与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4、归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位基本要求\n1、大专及以上学历，有销售工作经验优先；\n2、有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛，具备出色完成任务的能力；\n3、具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4、富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6、为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n发展路径广阔，沟通机制畅通，行业潜力大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4112656343","sourceKey":"meituan_social","company":"美团","title":"资金管理-资金运营-境外","city":"利雅得/圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4112656343&jobShareType=1","duty":"1、负责境外交易结算工作，处理各国结算相关问题，合理规划付款路径，在保障资金安全的同时提高付款效率；\n2、监控境外资金流动，确保合规性并优化资金使用效率；  \n3、持续优化付款流程，建立并完善标准化境内外资金操作SOP，协助制定和执行境外资金风险管理策略\n4、了解并遵循反洗钱、制裁等方面的政策，确保所有资金操作严格符合海外属地法规；\n5、梳理所负责工作中的人工操作痛点和风险点，对于可通过系统化解决的，明确需求并推进上线；\n6、其他工作：定期输出各类相关报表，如线下付款分析报告、月度质量事件分析等；配合月结、年度及专项审计等工作，协调并提供资金相关资料；完成主管临时安排的其他工作；\n7、推动该领域AI 化提效： 梳理资金高频工作场景，建立标准化 AI 辅助工作流与 Prompt 模板，沉淀团队操作规范，持续提升人均处理效率与决策质量。","requirements":"学历：财务、金融类本科及以上学历，海外背景优先。\n经验：3年以上全球资金管理经验，有跨国公司资金管理岗或海外工作背景优先。熟悉企业资金管理流程及账务处理，了解企业资金内控规范。\n专业：精通国际结算流程、了解外汇管制国家如巴西的外汇政策。\n技能：有较强的逻辑思维，具备复杂问题拆解的能力，较好的归纳总结能力，善于跨部门沟通和团队协作、可熟练使用常用办公软件。\n语言：英语可作为工作语言，同时会葡萄牙语会优先。\n其他要求：具备高度风险敏感性，能够有效平衡资金安全、工作效率与成本控制；拥有跨时区协作能力，适应紧急突发业务的处理及频繁差旅需求；快速学习能力，敢于挑战。\n关注大模型、AI Agent 等前沿技术在资金领域的应用进展，有参与或推动资金场景/AI/数字化工具落地经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、负责境外交易结算工作，处理各国结算相关问题，合理规划付款路径，在保障资金安全的同时提高付款效率；\n2、监控境外资金流动，确保合规性并优化资金使用效率；  \n3、持续优化付款流程，建立并完善标准化境内外资金操作SOP，协助制定和执行境外资金风险管理策略\n4、了解并遵循反洗钱、制裁等方面的政策，确保所有资金操作严格符合海外属地法规；\n5、梳理所负责工作中的人工操作痛点和风险点，对于可通过系统化解决的，明确需求并推进上线；\n6、其他工作：定期输出各类相关报表，如线下付款分析报告、月度质量事件分析等；配合月结、年度及专项审计等工作，协调并提供资金相关资料；完成主管临时安排的其他工作；\n7、推动该领域AI 化提效： 梳理资金高频工作场景，建立标准化 AI 辅助工作流与 Prompt 模板，沉淀团队操作规范，持续提升人均处理效率与决策质量。\n\n岗位基本要求\n学历：财务、金融类本科及以上学历，海外背景优先。\n经验：3年以上全球资金管理经验，有跨国公司资金管理岗或海外工作背景优先。熟悉企业资金管理流程及账务处理，了解企业资金内控规范。\n专业：精通国际结算流程、了解外汇管制国家如巴西的外汇政策。\n技能：有较强的逻辑思维，具备复杂问题拆解的能力，较好的归纳总结能力，善于跨部门沟通和团队协作、可熟练使用常用办公软件。\n语言：英语可作为工作语言，同时会葡萄牙语会优先。\n其他要求：具备高度风险敏感性，能够有效平衡资金安全、工作效率与成本控制；拥有跨时区协作能力，适应紧急突发业务的处理及频繁差旅需求；快速学习能力，敢于挑战。\n关注大模型、AI Agent 等前沿技术在资金领域的应用进展，有参与或推动资金场景/AI/数字化工具落地经验者优先。\n\n岗位亮点\n参与全球化资金运营，接触国际金融市场；积累资金管理运营经验，内部多岗位锻炼机会，为深耕资金管理领域做准备。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4089006601","sourceKey":"meituan_social","company":"美团","title":"国际资金","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4089006601&jobShareType=1","duty":"1. 业务支持与定制化方案：深入理解海外业务特点（如区域分布、商业模式、结算特征），提供定制化资金解决方案。为海外经销商提供融资支持方案，增强渠道竞争力。确保海外资金运作符合当地政策要求（反洗钱、外汇管制、税务合规等），了解当地货币政策变动并寻找业务机会点。\n2. 结算体系建设：设计并实施全球结算框架，解决汇困、跨时区结算、跨境资金池等痛点；建立境内外资金高效调拨机制（注资、借款、分红等），压降资金闲置成本。\n3.外汇管理体系建设：建立外汇风险识别、计量、评估模型（交易风险、折算风险、经济风险），制定差异化外汇套保策略，优化自然对冲方案，降低套保成本。\n4.银行关系与生态构建：建立并维护与国际主流银行（如汇丰、花旗、渣打、当地头部银行）的战略合作关系，评估不同银行的差异化服务能力，针对融资、结算、外汇、政策响应等需求进行资源配置。组织银行能力评估与定期复盘，建立海外银行资源库及分级管理机制。\n5. 推动该领域AI 化提效： 梳理资金高频工作场景，建立标准化 AI 辅助工作流与 Prompt 模板，沉淀团队操作规范，持续提升人均处理效率与决策质量。","requirements":"1. 核心经验与能力：深度熟悉国际金融市场规则（如国际结算、外汇衍生品、跨境融资政策），具备全球视野及政策敏感度；具备同行业资金管理经验，熟悉出海企业资金需求及解决方案设计。\n2. 资源整合与协作能力：熟悉海外银行服务及差异化合作模式，具备海外银行关系管理经验；精通国际结算系统（如SWIFT、ACH）及资金管理工具。优秀的跨文化沟通能力，能协调海外分支机构、总部及外部合作伙伴高效协作。\n3. 英语流利（商务级），可处理海外业务沟通及文档撰写。\n4. 关注大模型、AI Agent 等前沿技术在资金领域的应用进展，有参与或推动资金场景/AI/数字化工具落地经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 业务支持与定制化方案：深入理解海外业务特点（如区域分布、商业模式、结算特征），提供定制化资金解决方案。为海外经销商提供融资支持方案，增强渠道竞争力。确保海外资金运作符合当地政策要求（反洗钱、外汇管制、税务合规等），了解当地货币政策变动并寻找业务机会点。\n2. 结算体系建设：设计并实施全球结算框架，解决汇困、跨时区结算、跨境资金池等痛点；建立境内外资金高效调拨机制（注资、借款、分红等），压降资金闲置成本。\n3.外汇管理体系建设：建立外汇风险识别、计量、评估模型（交易风险、折算风险、经济风险），制定差异化外汇套保策略，优化自然对冲方案，降低套保成本。\n4.银行关系与生态构建：建立并维护与国际主流银行（如汇丰、花旗、渣打、当地头部银行）的战略合作关系，评估不同银行的差异化服务能力，针对融资、结算、外汇、政策响应等需求进行资源配置。组织银行能力评估与定期复盘，建立海外银行资源库及分级管理机制。\n5. 推动该领域AI 化提效： 梳理资金高频工作场景，建立标准化 AI 辅助工作流与 Prompt 模板，沉淀团队操作规范，持续提升人均处理效率与决策质量。\n\n岗位基本要求\n1. 核心经验与能力：深度熟悉国际金融市场规则（如国际结算、外汇衍生品、跨境融资政策），具备全球视野及政策敏感度；具备同行业资金管理经验，熟悉出海企业资金需求及解决方案设计。\n2. 资源整合与协作能力：熟悉海外银行服务及差异化合作模式，具备海外银行关系管理经验；精通国际结算系统（如SWIFT、ACH）及资金管理工具。优秀的跨文化沟通能力，能协调海外分支机构、总部及外部合作伙伴高效协作。\n3. 英语流利（商务级），可处理海外业务沟通及文档撰写。\n4. 关注大模型、AI Agent 等前沿技术在资金领域的应用进展，有参与或推动资金场景/AI/数字化工具落地经验者优先。\n\n岗位亮点\n1. 参与全球化业务，接触国际前沿资金运作模式。  \n2. 团队氛围开放，注重专业成长与职业发展。  \n3. 提供有竞争力的薪酬和国际化工作机会。  \n4. 与高层及海外团队紧密协作，提升战略视野。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2459467874","sourceKey":"meituan_social","company":"美团","title":"基座大模型算法专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2459467874&jobShareType=1","duty":"1. 基座大模型预训练，包括但不限于不同规模、不同结构的语言模型和多模态模型的数据准备和优化、模型预训练、训练加速与框架优化等；\n\n2. 大模型对齐技术（SFT、RLHF等）链路整体优化，包括数据探索与增强、对齐流程探索、奖励模型优化、强化学习策略迭代等，持续提升对齐效果；\n\n3. 大模型训练和推理优化，包括但不限于高效训练技术和框架设计与实现、模型小型化技术（稀疏化、压缩、剪枝、蒸馏等）探索与落地、高效推理技术实现等；\n\n4. 大模型相关技术前沿探索，包括但不限于Scaling Law、模型架构探索（MoE、MAMBA等）、训练范式探索、长序列技术探索、高效训推框架探索等；\n\n5. 支撑内部应用需求，对接搜索、推荐、广告等实际业务场景，实现大模型应用落地。","requirements":"1. 对大模型开发流程有深入认知，熟悉预训练、指令微调、RLHF等流程与框架，具备模型预训练、对齐、训练和推理加速、模型小型化和部署等方面的经验；\n\n2. 熟悉Transformer等模型架构，对GPT系列、LLAMA系列和MoE等模型架构有深入理解并拥有大规模训练经验；\n\n3. 具备扎实的算法和数学理论基础及良好的编程基础，熟悉自然语言处理、生成式AI和机器学习等技术，熟悉Python、Java等至少一种编程语言，熟悉PyTorch、Tensorflow等深度学习框架，对技术开发及应用有热情；\n\n4. 目标感强，善于分析和发现问题，拆解简化，有想法并乐于挑战自我，能够从日常工作中发现新的空间；\n\n5. 条理性强且有推动力，能够梳理繁杂的工作并建立有效机制，推动上下游配合完成目标。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 基座大模型预训练，包括但不限于不同规模、不同结构的语言模型和多模态模型的数据准备和优化、模型预训练、训练加速与框架优化等；\n\n2. 大模型对齐技术（SFT、RLHF等）链路整体优化，包括数据探索与增强、对齐流程探索、奖励模型优化、强化学习策略迭代等，持续提升对齐效果；\n\n3. 大模型训练和推理优化，包括但不限于高效训练技术和框架设计与实现、模型小型化技术（稀疏化、压缩、剪枝、蒸馏等）探索与落地、高效推理技术实现等；\n\n4. 大模型相关技术前沿探索，包括但不限于Scaling Law、模型架构探索（MoE、MAMBA等）、训练范式探索、长序列技术探索、高效训推框架探索等；\n\n5. 支撑内部应用需求，对接搜索、推荐、广告等实际业务场景，实现大模型应用落地。\n\n岗位基本要求\n1. 对大模型开发流程有深入认知，熟悉预训练、指令微调、RLHF等流程与框架，具备模型预训练、对齐、训练和推理加速、模型小型化和部署等方面的经验；\n\n2. 熟悉Transformer等模型架构，对GPT系列、LLAMA系列和MoE等模型架构有深入理解并拥有大规模训练经验；\n\n3. 具备扎实的算法和数学理论基础及良好的编程基础，熟悉自然语言处理、生成式AI和机器学习等技术，熟悉Python、Java等至少一种编程语言，熟悉PyTorch、Tensorflow等深度学习框架，对技术开发及应用有热情；\n\n4. 目标感强，善于分析和发现问题，拆解简化，有想法并乐于挑战自我，能够从日常工作中发现新的空间；\n\n5. 条理性强且有推动力，能够梳理繁杂的工作并建立有效机制，推动上下游配合完成目标。\n\n具备以下条件优先\n1. 在ACL、EMNLP、NeurIPS、ICLR、ICML等计算机学会推荐的国际会议和期刊发表过论文者优先；\n\n2. 在国际或国内权威赛事或评测中取得优秀名次者优先；\n\n3. 有大模型训练和调优经验，熟悉分布式和混合精度训练基本方法与框架。\n\n岗位亮点\n1. 团队具备良好的技术氛围，与志同道合的技术牛人一起工作；\n\n2. 能够参与到大模型核心研发工作中，为AGI目标躬身奋斗。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4167963082","sourceKey":"meituan_social","company":"美团","title":"美团骑行-区域安全事务负责人","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4167963082&jobShareType=1","duty":"1.统筹区域安全组的各项工作，负责各类危机事件的处置、案事件打击、朋友圈建设，以及助力业务发展工作的落地推进：\n2.针对业务风险可以提供切实有效的优化管控方案，对负责业务安全实行管理、监督、协调、培训和考核，协助业务完善风险管控制度；\n3.基于业务流程梳理和风险分析，制定、验证并持续优化安全指标体系及风险预警机制，建设风控系统并落地追踪；\n4.配合业务主管部门的工作，并保持良好沟通。\n5.团队管理与跨部门协同， 负责团队建设、目标管理、绩效评估、人才培养及预算资源配置。","requirements":"1.资深安全事务管理经验与战略领导力\n· 本科及以上学历，10年以上安全事务或相关领域工作经验，其中包含5年以上团队管理经验。\n· 具备卓越的战略规划与执行能力，能带领团队在复杂环境中达成目标。\n2.熟悉业务主管部门的工作方式、语言行为规则和决策流程，熟悉互联网行业，拥有一定行业资源；\n3.具有较强处理复杂事物的能力和团队合作意识，能接受高频出差；\n4.具有较强的总结分析能力、公文写作能力，语言表达能力。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.统筹区域安全组的各项工作，负责各类危机事件的处置、案事件打击、朋友圈建设，以及助力业务发展工作的落地推进：\n2.针对业务风险可以提供切实有效的优化管控方案，对负责业务安全实行管理、监督、协调、培训和考核，协助业务完善风险管控制度；\n3.基于业务流程梳理和风险分析，制定、验证并持续优化安全指标体系及风险预警机制，建设风控系统并落地追踪；\n4.配合业务主管部门的工作，并保持良好沟通。\n5.团队管理与跨部门协同， 负责团队建设、目标管理、绩效评估、人才培养及预算资源配置。\n\n岗位基本要求\n1.资深安全事务管理经验与战略领导力\n· 本科及以上学历，10年以上安全事务或相关领域工作经验，其中包含5年以上团队管理经验。\n· 具备卓越的战略规划与执行能力，能带领团队在复杂环境中达成目标。\n2.熟悉业务主管部门的工作方式、语言行为规则和决策流程，熟悉互联网行业，拥有一定行业资源；\n3.具有较强处理复杂事物的能力和团队合作意识，能接受高频出差；\n4.具有较强的总结分析能力、公文写作能力，语言表达能力。\n\n具备以下条件优先\n具备交通行业相关安全事务管理经验者优先\n\n岗位亮点\n1.大平台，有长远的成长发展空间，贴近业务侧更容易沉淀公共资源；\n2.具备较好的发展空间，表现优异者可以往管理方面培养；\n3.公司Ai工具多多帮你从事务工作中解放出来\n3.高水平专业团队，拥有专家型同事和完善培训体系，为个人成长提供广阔环境。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4155441908","sourceKey":"meituan_social","company":"美团","title":"美团骑行-政企大客户专家（内蒙）","city":"呼和浩特市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4155441908&jobShareType=1","duty":"1.在所负责区域，制定共享骑行发展计划，为业务在当地落地打好基础；2.与合作方建立良好的沟通及合作关系，为业务的稳定运营提供保障；3.了解行业及市场动态，适时调整城市相关的节奏和计划。","requirements":"1.本科及以上学历，5年以上工作经验；2.建立和维护客户关系，善于沟通和协同合作伙伴推动业务落地，有较强的销售能力，公文写作能力，有同业项目经验优先；3.熟悉政府部门体系组织架构和主要工作流程，了解政府管理方式方法；4.具有良好的团队协作和敬业精神，执行力强。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.在所负责区域，制定共享骑行发展计划，为业务在当地落地打好基础；2.与合作方建立良好的沟通及合作关系，为业务的稳定运营提供保障；3.了解行业及市场动态，适时调整城市相关的节奏和计划。\n\n岗位基本要求\n1.本科及以上学历，5年以上工作经验；2.建立和维护客户关系，善于沟通和协同合作伙伴推动业务落地，有较强的销售能力，公文写作能力，有同业项目经验优先；3.熟悉政府部门体系组织架构和主要工作流程，了解政府管理方式方法；4.具有良好的团队协作和敬业精神，执行力强。\n\n具备以下条件优先\nTO-B行业销售经验，政企项目管理经验，政府工作经历，公共事务经验优先\n\n岗位亮点\n带薪年假、定期体检、五险一金、发展空间大、个人能力提升快等","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4098290985","sourceKey":"meituan_social","company":"美团","title":"美团骑行-政企大客户专家","city":"兰州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4098290985&jobShareType=1","duty":"1.负责甘青宁区域高校、部分地市共享电单车业务拓展；\n2.与高校后勤处、地市公安、城管、交通等部门建立良好的沟通及合作关系，为业务落地取得准入资格，并跟进项目落地；","requirements":"1.本科及以上学历，5年以上工作经验；\n2.有较强的销售能力，公文写作能力，有同业项目经验优先；\n3.熟悉政府部门组织架构和工作流程，了解政府管理方式方法，有相关部门对接经验优先；\n4.具有良好的团队协作和敬业精神，执行力强，适应出差。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责甘青宁区域高校、部分地市共享电单车业务拓展；\n2.与高校后勤处、地市公安、城管、交通等部门建立良好的沟通及合作关系，为业务落地取得准入资格，并跟进项目落地；\n\n岗位基本要求\n1.本科及以上学历，5年以上工作经验；\n2.有较强的销售能力，公文写作能力，有同业项目经验优先；\n3.熟悉政府部门组织架构和工作流程，了解政府管理方式方法，有相关部门对接经验优先；\n4.具有良好的团队协作和敬业精神，执行力强，适应出差。\n\n具备以下条件优先\n行业经验，政企项目管理经验，政府工作经历，政府事务经验\n\n岗位亮点\n大厂重点项目，成长路径明确，五险一金，团队气氛好","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2901951725","sourceKey":"meituan_social","company":"美团","title":"三四星酒店大客户经理-全国","city":"常州市/无锡市/苏州市/金华市/烟台市/威海市/广州市/昆明市/贵阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2901951725&jobShareType=1","duty":"1、高星酒店业务的拓展，包含产品开发、采购、运营和维护；\n2、了解区域酒店合作需求，基于收益最大化给予酒店专业的合作方案和建议，达成双赢；\n3、了解各大平台运营规则，能快速学习美团运营规则，善于发现酒店在平台经营的生意增长点，明确提升方案；\n4、善于分析市场动态，洞察用户需求，在日常工作中微创新，为客户和平台带来价值。","requirements":"1、具备较强的沟通能力和销售技巧，以及客户服务意识；\n2、了解酒店行业和市场情况，两年或以上的销售岗位从业经历以及OTA从业经历者优先；\n3、较强的学习力，韧性足。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、高星酒店业务的拓展，包含产品开发、采购、运营和维护；\n2、了解区域酒店合作需求，基于收益最大化给予酒店专业的合作方案和建议，达成双赢；\n3、了解各大平台运营规则，能快速学习美团运营规则，善于发现酒店在平台经营的生意增长点，明确提升方案；\n4、善于分析市场动态，洞察用户需求，在日常工作中微创新，为客户和平台带来价值。\n\n岗位基本要求\n1、具备较强的沟通能力和销售技巧，以及客户服务意识；\n2、了解酒店行业和市场情况，两年或以上的销售岗位从业经历以及OTA从业经历者优先；\n3、较强的学习力，韧性足。\n\n岗位亮点\n住宿业务大客户开发岗位，充分深入住宿业务核心商家，并增加大客户维护经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4258804757","sourceKey":"meituan_social","company":"美团","title":"美团快驴K项目--急聘江西省BD","city":"南昌市/景德镇市/九江市/新余市/鹰潭市/赣州市/吉安市/宜春市/抚州市/上饶市/黄冈市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4258804757&jobShareType=1","duty":"1. 面向本地水果商家，拓展及维护新老客户去使用美团旗下的快驴平台进行采购，独立完成相应服务目标；\n2. 负责区域内水果客户的回访和维护，建立稳定的合作关系，使其长期保持复购；\n3. 结合公司的营销活动和销售策略，完成服务考核指标；\n4. 根据市场现状和客户反应，及时反馈产品存在的问题，实时调整业务策略；\n5. 与被服务方部门有效配合，并快速解决突发问题，以提高商户满意度；","requirements":"1. 大专及以上学历要求，学历以学信网可查到为准；\n2. 优先具备生鲜供应链行业经验与认知、有餐饮销售及服务经验、有互联网直销团队经验、有食材供应链销售及服务经验；\n3. 从事过其他销售工作；\n4. 认可销售行业，愿意长期在生鲜销售行业发展的非销售从业者。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 面向本地水果商家，拓展及维护新老客户去使用美团旗下的快驴平台进行采购，独立完成相应服务目标；\n2. 负责区域内水果客户的回访和维护，建立稳定的合作关系，使其长期保持复购；\n3. 结合公司的营销活动和销售策略，完成服务考核指标；\n4. 根据市场现状和客户反应，及时反馈产品存在的问题，实时调整业务策略；\n5. 与被服务方部门有效配合，并快速解决突发问题，以提高商户满意度；\n\n岗位基本要求\n1. 大专及以上学历要求，学历以学信网可查到为准；\n2. 优先具备生鲜供应链行业经验与认知、有餐饮销售及服务经验、有互联网直销团队经验、有食材供应链销售及服务经验；\n3. 从事过其他销售工作；\n4. 认可销售行业，愿意长期在生鲜销售行业发展的非销售从业者。\n\n岗位亮点\n大平台发展历练，同时内部具备完善的培养、晋升体系","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4242640496","sourceKey":"meituan_social","company":"美团","title":"闪购-超市便利KA-商家运营（便利店）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4242640496&jobShareType=1","duty":"1、负责便利店KA头部连锁商家，在美团闪购的即时零售业务运营开展和日常管理，面向包括业务规模、盈亏、流量、营销、商品、服务等各项经营指标负责；\n2、能够基于便利店业务特性和不同商家及用户特征，形成商家运营策略并协同商家执行落地；\n3、通过指导商家进行门店上线、优化商品、营销活动、流量获取、履约改善等作业流程持续提升商家线上经营能力，并探索形成可复制的标准化流程；\n4、理解商家的业务模式、成本结构，能根据业务发展和行业理解，挖掘商家及日常团队的运营痛点，对外改善商家合作深度，对内面向产品体验升级方向提出优化建议；\n5、定期如月度、季度等进行合作伙伴拜访和业务复盘总结，形成商家成长路径和业务达成探索的沉淀输出。","requirements":"1、本科以上学历，3年以上平台运营或者大客户销售运营相关从业经验，有电商、O2O、零售行业经验优先；\n2、具备成熟的商户运营经验和方法，可以从零售行业和商家区域差异视角洞悉用户消费习惯，负责过零售运营项目或者餐饮外卖商户运营者优先；\n3、具备良好商务洽谈能力，能够全面看问题，逻辑清晰，具备成熟的数据分析能力，发现问题及提供解决方案能力；\n4、具备优秀的跨部门沟通协调能力。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1、负责便利店KA头部连锁商家，在美团闪购的即时零售业务运营开展和日常管理，面向包括业务规模、盈亏、流量、营销、商品、服务等各项经营指标负责；\n2、能够基于便利店业务特性和不同商家及用户特征，形成商家运营策略并协同商家执行落地；\n3、通过指导商家进行门店上线、优化商品、营销活动、流量获取、履约改善等作业流程持续提升商家线上经营能力，并探索形成可复制的标准化流程；\n4、理解商家的业务模式、成本结构，能根据业务发展和行业理解，挖掘商家及日常团队的运营痛点，对外改善商家合作深度，对内面向产品体验升级方向提出优化建议；\n5、定期如月度、季度等进行合作伙伴拜访和业务复盘总结，形成商家成长路径和业务达成探索的沉淀输出。\n\n岗位基本要求\n1、本科以上学历，3年以上平台运营或者大客户销售运营相关从业经验，有电商、O2O、零售行业经验优先；\n2、具备成熟的商户运营经验和方法，可以从零售行业和商家区域差异视角洞悉用户消费习惯，负责过零售运营项目或者餐饮外卖商户运营者优先；\n3、具备良好商务洽谈能力，能够全面看问题，逻辑清晰，具备成熟的数据分析能力，发现问题及提供解决方案能力；\n4、具备优秀的跨部门沟通协调能力。\n\n岗位亮点\n1、公司核心业务，与行业专家共同在新零售行业探索；\n2、团队年轻充满热情，氛围轻松富有激情，个人成长空间大；\n3、能在快速发展的平台级业务中，参与规模化的过程，并在其中担任核心角色。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4158083555","sourceKey":"meituan_social","company":"美团","title":"品类运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4158083555&jobShareType=1","duty":"1、数据驱动的品类策略支持：基于冻品业务场景，通过数据分析制定品类规划、选品逻辑及规则，为策略制定提供量化依据；\n2、指标体系构建与监控：设计并迭代经营/运营指标体系，监控品类商品、商家、业态、PB等核心数据，通过量化分析定位趋势变化及驱动因素；\n3、深度业务洞察挖掘：结合业务逻辑分析数据，识别运营缺陷与增长机会，输出可落地的数据洞察报告，支撑业务决策；\n4、专题分析与策略输出：主导业务议题复盘，通过归因分析提炼结论，输出宏观-中观-微观策略建议，推动业务结果达成；\n5、目标拆解与路径规划：基于数据分析拆解业务目标，设计实现路径，为管理层策略制定提供数据支持。","requirements":"1、行业经验：3年以上零售/电商行业数据分析经验，食杂冻品领域优先；\n2、专业能力：\n①强数据敏感度与逻辑分析能力，熟练运用统计学方法解决问题；\n②精通SQL及Python/R等分析工具，掌握Power BI等可视化工具；\n③具备预测建模、归因分析等量化分析经验者优先；\n3、软性素质：\n①优秀的跨团队沟通与协调能力，能清晰传递分析结论；\n②自驱力强，具备结果导向思维；\n③注重团队协作，善于整合资源推进项目。\n6. 自驱力强，具有较好的学习能力，愿意主动思考AI如何进一步优化工作流程。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、数据驱动的品类策略支持：基于冻品业务场景，通过数据分析制定品类规划、选品逻辑及规则，为策略制定提供量化依据；\n2、指标体系构建与监控：设计并迭代经营/运营指标体系，监控品类商品、商家、业态、PB等核心数据，通过量化分析定位趋势变化及驱动因素；\n3、深度业务洞察挖掘：结合业务逻辑分析数据，识别运营缺陷与增长机会，输出可落地的数据洞察报告，支撑业务决策；\n4、专题分析与策略输出：主导业务议题复盘，通过归因分析提炼结论，输出宏观-中观-微观策略建议，推动业务结果达成；\n5、目标拆解与路径规划：基于数据分析拆解业务目标，设计实现路径，为管理层策略制定提供数据支持。\n\n岗位基本要求\n1、行业经验：3年以上零售/电商行业数据分析经验，食杂冻品领域优先；\n2、专业能力：\n①强数据敏感度与逻辑分析能力，熟练运用统计学方法解决问题；\n②精通SQL及Python/R等分析工具，掌握Power BI等可视化工具；\n③具备预测建模、归因分析等量化分析经验者优先；\n3、软性素质：\n①优秀的跨团队沟通与协调能力，能清晰传递分析结论；\n②自驱力强，具备结果导向思维；\n③注重团队协作，善于整合资源推进项目。\n6. 自驱力强，具有较好的学习能力，愿意主动思考AI如何进一步优化工作流程。\n\n岗位亮点\n1、团队氛围好；\n2、福利待遇完善；\n3、晋升机会多，公平、透明。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4113672979","sourceKey":"meituan_social","company":"美团","title":"SaaS财务运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4113672979&jobShareType=1","duty":"1、AI赋能业务支持：负责对接SaaS业务需求，结合会计准则、结算规则、合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案；主动运用AI工具（如大模型、智能分析平台）辅助业务场景分析与财务方案设计，提升决策支持效率；\n\n2、智能财务信息化建设：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；积极探索AI技术在财务流程中的落地应用，推动人机协作模式创新；\n\n3、AI驱动流程优化：借助AI工具对财务运营流程进行系统性梳理与优化，识别可自动化的重复性工作环节，提高财务结果的效率和准确性，释放人力聚焦高价值工作；\n\n4、智能风险监控及数据分析：建立并优化运营监控机制，运用AI数据分析工具识别财务风险，整理、输出分析报告，协助拟定治理策略并跟踪运营落地；\n\n5、其他：与财务其他团队积极协调，完成其他指定任务。","requirements":"1. 本科及以上学历，会计、经济、管理类等相关专业，具备财会相关工作经验，有核算相关经验以及财务系统对接经验优先；鼓励有AI工具落地实践经验者，年限要求可适当放宽；\n\n2. 具备AI工具使用能力，熟悉主流大模型工具（如ChatGPT、Copilot等）在财务场景中的应用，有AI辅助数据分析、报告生成等实际经验者优先；\n\n3. 具备较强的沟通、协调能力，能够独立与其他部门和合作伙伴进行有效沟通和协调；\n\n4. 具备优秀的逻辑思维和分析能力，能快速识别、拆解问题并推动问题有效解决；善于借助AI工具提升分析效率；\n\n5. 工作认真细心、责任心强，具有良好的团队协作精神和服务意识，对AI技术在财务领域的应用保持持续学习热情。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、AI赋能业务支持：负责对接SaaS业务需求，结合会计准则、结算规则、合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案；主动运用AI工具（如大模型、智能分析平台）辅助业务场景分析与财务方案设计，提升决策支持效率；\n\n2、智能财务信息化建设：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；积极探索AI技术在财务流程中的落地应用，推动人机协作模式创新；\n\n3、AI驱动流程优化：借助AI工具对财务运营流程进行系统性梳理与优化，识别可自动化的重复性工作环节，提高财务结果的效率和准确性，释放人力聚焦高价值工作；\n\n4、智能风险监控及数据分析：建立并优化运营监控机制，运用AI数据分析工具识别财务风险，整理、输出分析报告，协助拟定治理策略并跟踪运营落地；\n\n5、其他：与财务其他团队积极协调，完成其他指定任务。\n\n岗位基本要求\n1. 本科及以上学历，会计、经济、管理类等相关专业，具备财会相关工作经验，有核算相关经验以及财务系统对接经验优先；鼓励有AI工具落地实践经验者，年限要求可适当放宽；\n\n2. 具备AI工具使用能力，熟悉主流大模型工具（如ChatGPT、Copilot等）在财务场景中的应用，有AI辅助数据分析、报告生成等实际经验者优先；\n\n3. 具备较强的沟通、协调能力，能够独立与其他部门和合作伙伴进行有效沟通和协调；\n\n4. 具备优秀的逻辑思维和分析能力，能快速识别、拆解问题并推动问题有效解决；善于借助AI工具提升分析效率；\n\n5. 工作认真细心、责任心强，具有良好的团队协作精神和服务意识，对AI技术在财务领域的应用保持持续学习热情。\n\n岗位亮点\n1、AI工具资源丰富：公司为员工提供完善的AI工具生态，包括内部智能助手、数据分析平台、自动化流程工具等，助力财务人员从繁琐重复工作中解放，聚焦高价值创造；\n\n2、人机协作成长价值：在AI深度介入财务工作的前沿阵地，你将有机会亲历并主导财务智能化转型，积累稀缺的AI+财务复合能力，成为未来财务领域的核心竞争力；\n\n3、学习成长机会：互联网和资产相结合的新兴业态，模式复杂多变，在这里既可以体验传统行业的经验，也可以体验互联网特色，以及互联网和传统行业的有机碰撞；\n\n4、轻松高效的团队氛围：我们注重专业，注重团队协作，团队内部相互帮助、相互学习、共同进步，团队外部互助共赢，共同探索AI时代财务工作的新范式。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4230068798","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-内外饰工程师","city":"上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4230068798&jobShareType=1","duty":"负责车型内外饰前期工程可行性及竞争性研究，通过AI工具辅助标杆分析/成本测算，快速输出技术路线对比报告\n\n主导内外饰项目集成管理（开发范围/成本/重量/计划/性能/工艺），运用AI辅助进度跟踪/风险识别/变更影响分析\n\n负责内外饰零部件设计开发和数据发布，探索AI辅助造型可行性分析/间隙面差预测，承接质量/成本/重量/性能目标\n\n主导供应商评价与选型，运用AI工具辅助供应商评估/PPAP审查/技术发包文件生成，持续开展降本优化\n\n负责外饰系统新技术/新工艺/新材料技术积累，利用AI驱动材料选型对比，加速技术落地\n\n主导AI工具在内外饰开发流程的落地推广，建立AI辅助工程的标准规范","requirements":"学历：本科及以上；机械类/车辆工程/材料等相关专业\n\n经验：8年以上（preferred），具有2个以上正向开发项目经验\n\n熟悉内外饰常用结构及断面，熟悉间隙面差控制/成型工艺及表面处理；熟悉整车内外饰目标制定与进度/重量/成本控制\n\nAI能力：能使用AI工具（大模型/设计分析AI/自动化脚本等）重构开发工作流程，有AI辅助设计/文档经验者优先","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n负责车型内外饰前期工程可行性及竞争性研究，通过AI工具辅助标杆分析/成本测算，快速输出技术路线对比报告\n\n主导内外饰项目集成管理（开发范围/成本/重量/计划/性能/工艺），运用AI辅助进度跟踪/风险识别/变更影响分析\n\n负责内外饰零部件设计开发和数据发布，探索AI辅助造型可行性分析/间隙面差预测，承接质量/成本/重量/性能目标\n\n主导供应商评价与选型，运用AI工具辅助供应商评估/PPAP审查/技术发包文件生成，持续开展降本优化\n\n负责外饰系统新技术/新工艺/新材料技术积累，利用AI驱动材料选型对比，加速技术落地\n\n主导AI工具在内外饰开发流程的落地推广，建立AI辅助工程的标准规范\n\n岗位基本要求\n学历：本科及以上；机械类/车辆工程/材料等相关专业\n\n经验：8年以上（preferred），具有2个以上正向开发项目经验\n\n熟悉内外饰常用结构及断面，熟悉间隙面差控制/成型工艺及表面处理；熟悉整车内外饰目标制定与进度/重量/成本控制\n\nAI能力：能使用AI工具（大模型/设计分析AI/自动化脚本等）重构开发工作流程，有AI辅助设计/文档经验者优先\n\n具备以下条件优先\n1、兼具有整车厂和设计公司经历、整车内外饰开发经验者优先；\n2、商用车背景优先\n3、具有高阶智能驾驶车辆内外饰开发经验者优先\n\n岗位亮点\n🏭 L4自动驾驶量产一线：参与无人车H24/S26正向开发，内外饰工程师直接影响交付质量和用户体验\n\n🤖 AI赋能工具链：公司AI工具完善，用AI替代重复劳动（文档/报告/对标），精力聚焦在有价值的设计决策\n\n🌏 整车厂+自动驾驶双重经历，商用车/智能驾驶背景，个人市场价值显著提升","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4259595935","sourceKey":"meituan_social","company":"美团","title":"火石业务中心-东南区-产品销售","city":"杭州市/宁波市/温州市/嘉兴市/台州市/福州市/厦门市/泉州市/南昌市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4259595935&jobShareType=1","duty":"1. 面向工厂、工地、学校、企事业单位食堂等团餐类客户，拓展及维护新老客户去使用美团旗下的快驴平台进行食材采购，独立完成相应绩效目标；\n\n2. 负责区域内客户的回访和维护，建立稳定的合作关系；\n\n3. 结合公司的营销活动和销售策略，完成公司下达的工作指标；\n\n4. 根据市场现状和客户反应，及时反馈产品存在的问题，实时调整业务策略；\n\n5. 与公司各部门有效配合，并快速解决突发问题，以提高商户满意度。","requirements":"1. 学历大专及以上，注重长远职业发展，学习能力强且勤奋努力；\n\n2. 1年以上相关职位经验，对本地生活服务行业有一定的认知和快速的学习能力；\n\n3. 执行性力强，有实践或创业经验者优先，熟悉供应链行业的优先；\n\n4. 精力充沛，有较强的进取心；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 面向工厂、工地、学校、企事业单位食堂等团餐类客户，拓展及维护新老客户去使用美团旗下的快驴平台进行食材采购，独立完成相应绩效目标；\n\n2. 负责区域内客户的回访和维护，建立稳定的合作关系；\n\n3. 结合公司的营销活动和销售策略，完成公司下达的工作指标；\n\n4. 根据市场现状和客户反应，及时反馈产品存在的问题，实时调整业务策略；\n\n5. 与公司各部门有效配合，并快速解决突发问题，以提高商户满意度。\n\n岗位基本要求\n1. 学历大专及以上，注重长远职业发展，学习能力强且勤奋努力；\n\n2. 1年以上相关职位经验，对本地生活服务行业有一定的认知和快速的学习能力；\n\n3. 执行性力强，有实践或创业经验者优先，熟悉供应链行业的优先；\n\n4. 精力充沛，有较强的进取心；\n\n具备以下条件优先\n1.有团餐行业经验\n2.具备交通工具汽车\n3.有电销能力\n\n岗位亮点\n新业务，行业前景巨大，成长机会多，欢迎更多优秀","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3574258006","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-车辆动力学工程师","city":"上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3574258006&jobShareType=1","duty":"负责悬架及整车动力学模型搭建/K&C分析/操稳分析/平顺性分析，通过AI工具辅助模型参数优化和分析结果解读\n\n负责底盘方案评估与选型对标，运用AI辅助性能目标分解/分析/技术路线对比，提升决策效率\n\n负责操稳/平顺性试验规划和验证，探索AI辅助试验数据快速分析/异常检测和性能达成预测\n\n负责车辆运营中动力学相关问题分析，运用AI辅助故障根因分析/仿真复现，加速问题闭环\n\n探索AI辅助动力学仿真自动化/电控联合仿真优化，主导AI工具在动力学开发流程中的落地应用","requirements":"学历：硕士研究生及以上（preferred）；车辆工程或相关专业\n\n经验：5年以上（preferred），有整车底盘/动力学相关工作经验\n\n掌握动力学优化仿真，能熟练使用动力学分析相关软件，具备一定编程能力\n\nAI能力：能使用AI工具（大模型/数据分析AI/仿真优化工具等）重构动力学工作流程，有AI辅助仿真/试验数据分析经验者优先","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n负责悬架及整车动力学模型搭建/K&C分析/操稳分析/平顺性分析，通过AI工具辅助模型参数优化和分析结果解读\n\n负责底盘方案评估与选型对标，运用AI辅助性能目标分解/分析/技术路线对比，提升决策效率\n\n负责操稳/平顺性试验规划和验证，探索AI辅助试验数据快速分析/异常检测和性能达成预测\n\n负责车辆运营中动力学相关问题分析，运用AI辅助故障根因分析/仿真复现，加速问题闭环\n\n探索AI辅助动力学仿真自动化/电控联合仿真优化，主导AI工具在动力学开发流程中的落地应用\n\n岗位基本要求\n学历：硕士研究生及以上（preferred）；车辆工程或相关专业\n\n经验：5年以上（preferred），有整车底盘/动力学相关工作经验\n\n掌握动力学优化仿真，能熟练使用动力学分析相关软件，具备一定编程能力\n\nAI能力：能使用AI工具（大模型/数据分析AI/仿真优化工具等）重构动力学工作流程，有AI辅助仿真/试验数据分析经验者优先\n\n具备以下条件优先\n具有底盘操稳调校、悬架系统开发、车辆动力学与电控联合仿真等经验者优先。\n\n岗位亮点\n🚗 L4自动驾驶核心底盘能力：参与高级别自动驾驶物流车整车架构搭建，积累自动驾驶车辆动力学能力\n\n🤖 AI增强动力学分析：AI辅助仿真迭代/试验数据分析，在自动驾驶量产场景实践AI+动力学的前沿应用\n\n💡 优先补缺的核心岗：车辆动力学是建立整车硬件能力的基础，团队急需，成长空间和影响力大","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4257769651","sourceKey":"meituan_social","company":"美团","title":"PC生产主管","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4257769651&jobShareType=1","duty":"1. 负责PC生产线的日常运营管理，确保生产计划按时完成。  \n2. 组织协调仓储物流环节，优化物料流转效率，降低库存成本。  \n3. 管理100人团队，包括排班、培训、绩效考核及人员调配。  \n4. 监控生产过程中的质量与安全标准，推动持续改进措施。  \n5. 与采购、质量、工程等部门协作，解决生产中的异常问题。","requirements":"1. 大学专科及以上学历，物流、仓储、生产管理或相关专业优先。  \n2. 具备5年以上物流/仓储或生产管理经验，有团队管理经验。  \n3. 熟悉PC制造流程及仓储物流操作规范。  \n4. 具备良好的沟通协调能力\n5. 工作地点为北京市，能适应倒班及现场管理工作。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责PC生产线的日常运营管理，确保生产计划按时完成。  \n2. 组织协调仓储物流环节，优化物料流转效率，降低库存成本。  \n3. 管理100人团队，包括排班、培训、绩效考核及人员调配。  \n4. 监控生产过程中的质量与安全标准，推动持续改进措施。  \n5. 与采购、质量、工程等部门协作，解决生产中的异常问题。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、仓储、生产管理或相关专业优先。  \n2. 具备5年以上物流/仓储或生产管理经验，有团队管理经验。  \n3. 熟悉PC制造流程及仓储物流操作规范。  \n4. 具备良好的沟通协调能力\n5. 工作地点为北京市，能适应倒班及现场管理工作。\n\n岗位亮点\n1. 提供完善的培训体系和职业发展通道。  \n2. 团队规模大，管理挑战与成长空间并存。  \n3. 位于北京核心区域，交通便利，办公环境优良。  \n4. 享有具有竞争力的薪酬福利及绩效奖金。  \n5. 参与智能制造升级项目，积累前沿行业经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4236138859","sourceKey":"meituan_social","company":"美团","title":"美团骑行-资产城市经理-云南","city":"昆明市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4236138859&jobShareType=1","duty":"1.负责所辖城市运营资源供给保障及仓库管理；2.执行落地相关管理要求及流程标准；3.对仓库进行现场管理，持续提升作业效率；4.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险。","requirements":"1.本科及以上学历，具有3年以上团队管理经验，有相关物流仓储工作经验优先；2.具有较强的人际交往能力和应变能力；3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力；4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所辖城市运营资源供给保障及仓库管理；2.执行落地相关管理要求及流程标准；3.对仓库进行现场管理，持续提升作业效率；4.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险。\n\n岗位基本要求\n1.本科及以上学历，具有3年以上团队管理经验，有相关物流仓储工作经验优先；2.具有较强的人际交往能力和应变能力；3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力；4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。\n\n具备以下条件优先\n同行业、快递、物流、仓储、重资产业务管理等行业经验者优先\n\n岗位亮点\n带薪年假、定期体检、五险一金、发展空间大、个人能力提升快等","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3661720123","sourceKey":"meituan_social","company":"美团","title":"创新项目组渠道经理","city":"广州市/深圳市/武汉市/西安市/成都市/杭州市/南京市/重庆市/长沙市/昆明市/乌鲁木齐市/福州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3661720123&jobShareType=1","duty":"1.服务商团队招募与体系建设，负责服务商团队（如地推、运维服务商等）的招募、筛选及引入，建立标准化合作流程与评估体系。制定服务商团队的KPI考核机制，确保其高效完成存量设备的铺设、维护及问题响应。\n\n2.统筹服务商团队资源，推动充电宝设备的精准铺设（如高流量场景覆盖）及动态调优（根据数据调整点位）。监督服务商团队的日常运维质量（门店补宝、冗余宝回收、断电处理等），确保充电宝设备使用率达标。\n\n3.赋能与问题解决，为服务商团队提供培训（如门店上单、异议处理、进店工具使用），提升其业务能力。\n\n4.数据驱动与业绩达成，监控服务商团队的铺设/运维数据，定期复盘并优化策略。协同服务商团队完成公司下达的铺设机柜及存量设备维护等核心指标。\n\n5.政策传达与关系维护，准确传递公司政策，确保服务商与公司目标一致。建立长期稳定的合作关系，处理合作中的争议，提升第三方团队黏性。","requirements":"1.大专及以上学历，3年以上渠道管理或服务商团队运营经验。\n\n2.熟悉服务商团队招募、培训、考核全流程。\n\n3.能协调多方资源，推动复杂问题的解决。\n\n4.商务谈判能力：擅长与第三方团队、商户、内部部门多方协调，平衡利益关系。\n\n5.能适应高频出差，结果导向。\n\n6.有团队协作意识，能带领服务商共同达成目标。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.服务商团队招募与体系建设，负责服务商团队（如地推、运维服务商等）的招募、筛选及引入，建立标准化合作流程与评估体系。制定服务商团队的KPI考核机制，确保其高效完成存量设备的铺设、维护及问题响应。\n\n2.统筹服务商团队资源，推动充电宝设备的精准铺设（如高流量场景覆盖）及动态调优（根据数据调整点位）。监督服务商团队的日常运维质量（门店补宝、冗余宝回收、断电处理等），确保充电宝设备使用率达标。\n\n3.赋能与问题解决，为服务商团队提供培训（如门店上单、异议处理、进店工具使用），提升其业务能力。\n\n4.数据驱动与业绩达成，监控服务商团队的铺设/运维数据，定期复盘并优化策略。协同服务商团队完成公司下达的铺设机柜及存量设备维护等核心指标。\n\n5.政策传达与关系维护，准确传递公司政策，确保服务商与公司目标一致。建立长期稳定的合作关系，处理合作中的争议，提升第三方团队黏性。\n\n岗位基本要求\n1.大专及以上学历，3年以上渠道管理或服务商团队运营经验。\n\n2.熟悉服务商团队招募、培训、考核全流程。\n\n3.能协调多方资源，推动复杂问题的解决。\n\n4.商务谈判能力：擅长与第三方团队、商户、内部部门多方协调，平衡利益关系。\n\n5.能适应高频出差，结果导向。\n\n6.有团队协作意识，能带领服务商共同达成目标。\n\n具备以下条件优先\n1.有共享经济（共享充电宝等）、本地生活服务、硬件运维行业背景优先。\n\n2.有从0到1搭建渠道体系经验者优先\n\n岗位亮点\n1.定义行业创新标准，参与共享充电宝行业前沿模式探索，主导从0到1的创新项目，积累行业标杆经验。\n\n2.高成长性舞台、资源杠杆优势，依托部门优势，日常工作可对接渠道前线各战区、中台等部门，提供高成长性舞台，获得战略级项目曝光；能力模型覆盖“创新-执行-风控-成交”全链路，加速复合型成长。\n\n3.岗位晋升机制完善，双晋升通道（管理晋升&专业晋升），成熟且上升的行业&创新业务部门、拥有无限可能。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3063988004","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-运力供给系统负责人","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3063988004&jobShareType=1","duty":"1.主导运力供给管理系统的全球化架构设计，构建支持多国家政策、动态合规校验、智能排班调度的核心能力；\n2.深度理解多区域运力供给差异，与产品团队协同将业务逻辑抽象为可配置化系统规则；\n3.设计配送合作商管理工具（如自动化入驻审核、绩效管理系统），提升生态合作伙伴协同效率；\n4.从0到1完成运力供给团队搭建；\n5.探索AI技术在运力供给场景中的工程应用，借助AI Coding工具提升系统研发效率，推动合规校验、智能排班等模块的智能化演进。","requirements":"1.具备较好的业务理解力，能够与业务、产品、算法沟通，有主动帮助业务达成目标的精神；\n2.在物流/即时配送领域有深厚的积累，在复杂业务系统设计、系统稳定性上有丰富的经验；\n3.有良好的沟通能力，工作积极主动、责任心强，极度关注客户；\n4.具备创业精神和创业心态，不自设边界，能够快速学习，广泛支撑业务；\n5.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发与系统设计流程；有国际化系统建设经验、有较好的英语水平能够作为工作语言交流者优先。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.主导运力供给管理系统的全球化架构设计，构建支持多国家政策、动态合规校验、智能排班调度的核心能力；\n2.深度理解多区域运力供给差异，与产品团队协同将业务逻辑抽象为可配置化系统规则；\n3.设计配送合作商管理工具（如自动化入驻审核、绩效管理系统），提升生态合作伙伴协同效率；\n4.从0到1完成运力供给团队搭建；\n5.探索AI技术在运力供给场景中的工程应用，借助AI Coding工具提升系统研发效率，推动合规校验、智能排班等模块的智能化演进。\n\n岗位基本要求\n1.具备较好的业务理解力，能够与业务、产品、算法沟通，有主动帮助业务达成目标的精神；\n2.在物流/即时配送领域有深厚的积累，在复杂业务系统设计、系统稳定性上有丰富的经验；\n3.有良好的沟通能力，工作积极主动、责任心强，极度关注客户；\n4.具备创业精神和创业心态，不自设边界，能够快速学习，广泛支撑业务；\n5.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发与系统设计流程；有国际化系统建设经验、有较好的英语水平能够作为工作语言交流者优先。\n\n具备以下条件优先\n有国际化系统建设经验、有较好的英语水平，能够作为工作语言交流\n\n岗位亮点\n参与建设并见证业务的高速发展，直接影响业务走向，技术驱动业务进步成就感。\n团队积极拥抱AI工作方式，日常研发全面接入AI Coding工具，持续探索AI驱动的全球化运力系统智能化实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4257395428","sourceKey":"meituan_social","company":"美团","title":"商业地产财务解决方案","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4257395428&jobShareType=1","duty":"1、负责商业地产项目（购物中心、写字楼、产业园区等）从开发阶段到持有运营阶段的全流程账务处理，包括资产核算、成本归集、收入确认、费用分摊及资产减值测试等；\n2、处理商户租金、物业费、推广费、停车费等收入的确认；\n3、归集开发成本（土地、建安、资本化利息等）及运营期费用（工程维护、招商佣金、能源费等）；\n4、通过AI工具设计并优化核算流程，推动业务系统与核算系统的开发与应用，推动AI介入会计处理的方案落地；\n5、配合内外部审计，提供资产盘点、凭证抽查等支持工作；","requirements":"1、本科及以上学历，会计、经济、管理类等相关专业；\n2、8年以上商业地产（购物中心/写字楼/产业园）财务核算经验，熟悉商业地产开发到运营的全周期会计处理，有大型商业地产工作经验者优先；\n3、熟悉商业地产相关会计准则及商业地产行业政策，具备较强的数据分析能力及风险识别意识；\n4、熟悉商业地产相关业务系统与核算系统，有全流程参与搭建商业地产系统经验者优先；\n5、熟悉当前市面上主流AI产品的应用场景并熟练使用；\n6、具备良好的解决问题能力，能够应对复杂的财务运营情况","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、负责商业地产项目（购物中心、写字楼、产业园区等）从开发阶段到持有运营阶段的全流程账务处理，包括资产核算、成本归集、收入确认、费用分摊及资产减值测试等；\n2、处理商户租金、物业费、推广费、停车费等收入的确认；\n3、归集开发成本（土地、建安、资本化利息等）及运营期费用（工程维护、招商佣金、能源费等）；\n4、通过AI工具设计并优化核算流程，推动业务系统与核算系统的开发与应用，推动AI介入会计处理的方案落地；\n5、配合内外部审计，提供资产盘点、凭证抽查等支持工作；\n\n岗位基本要求\n1、本科及以上学历，会计、经济、管理类等相关专业；\n2、8年以上商业地产（购物中心/写字楼/产业园）财务核算经验，熟悉商业地产开发到运营的全周期会计处理，有大型商业地产工作经验者优先；\n3、熟悉商业地产相关会计准则及商业地产行业政策，具备较强的数据分析能力及风险识别意识；\n4、熟悉商业地产相关业务系统与核算系统，有全流程参与搭建商业地产系统经验者优先；\n5、熟悉当前市面上主流AI产品的应用场景并熟练使用；\n6、具备良好的解决问题能力，能够应对复杂的财务运营情况\n\n具备以下条件优先\n1、有参与大型AI财务项目经验优先；\n2、有全流程参与商业地产规划、建设、运营并负责主要会计核算经验优先。\n\n岗位亮点\n1、学习成长机会：互联网和资产相结合的新兴业态，模式复杂多变，在这里既可以体验传统行业的经验，也可以体验互联网特色，以及互联网和传统行业的有机碰撞； \n2、接触前沿的AI协同办公应用以及更多元化的AI使用场景，直接参与人机协同的能力建设，感受AI带来的办公效率提升；\n3、轻松高效的团队氛围：我们注重专业，注重团队协作，注重合作共赢，注重纳新聚力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:1539727162","sourceKey":"meituan_social","company":"美团","title":"商户运营专员-商户运营二区","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=1539727162&jobShareType=1","duty":"1.通过电话方式为合作商户提供线上运营方案及售后服务，完成个人业绩指标；\n2.根据公司策略，协助商户完成团购套餐搭配，提供营销活动的策略支持，帮助商户提升线上售卖量，提高门店运营效率；\n3.及时处理商户在交易类产品、线上营销活动、商家系统使用中遇到的问题，提高商户及用户满意度，帮助公司了解市场的变化规律并给出建议。","requirements":"1.大专及以上学历，有销售工作经验优先；\n2.有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛；\n3.具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4.富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6.为人正直，诚实可靠，以公司利益为重；\n7.可接受优秀应届毕业生。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1.通过电话方式为合作商户提供线上运营方案及售后服务，完成个人业绩指标；\n2.根据公司策略，协助商户完成团购套餐搭配，提供营销活动的策略支持，帮助商户提升线上售卖量，提高门店运营效率；\n3.及时处理商户在交易类产品、线上营销活动、商家系统使用中遇到的问题，提高商户及用户满意度，帮助公司了解市场的变化规律并给出建议。\n\n岗位基本要求\n1.大专及以上学历，有销售工作经验优先；\n2.有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛；\n3.具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4.富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6.为人正直，诚实可靠，以公司利益为重；\n7.可接受优秀应届毕业生。\n\n岗位亮点\n1.能够与下沉市场生活服务行业中小商户深度沟通，运用专业帮他们经营更好； 2.年轻团队、富有活力，入职即有师傅带教，将获得运营、销售、沟通等技能的专人辅导 3.发展空间大，向上可晋升至管理岗。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2035082744","sourceKey":"meituan_social","company":"美团","title":"中小发华北大区-产品销售","city":"哈尔滨市/巴彦淖尔市/包头市/赤峰市/鄂尔多斯市/呼和浩特市/通辽市/乌海市/乌兰察布市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2035082744&jobShareType=1","duty":"1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","requirements":"1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生；\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位基本要求\n1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生；\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n1.能够与下沉市场生活服务行业中小商户深度沟通，运用专业帮他们经营更好； 2.年轻团队、富有活力，入职即有师傅带教，将获得运营、销售、沟通等技能的专人辅导 3.发展空间大，向上可晋升至管理岗。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4237927186","sourceKey":"meituan_social","company":"美团","title":"小象超市-储备城市品控负责人","city":"济南市/青岛市/太原市/沈阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4237927186&jobShareType=1","duty":"1.负责城市品控团队的日常管理和指导，确保团队高效运转；\n2.负责城市商品与供应链管理/品质管理的工作，监督和协调产品采购、库存管理等工作；\n3.负责城市供应商管理，建立和维护良好的合作关系，确保供应链畅通；\n4.负责城市商品质量管理，监督产品质量，及时解决质量问题；\n5.参与制定城市品控策略和目标，确保城市品控工作符合公司标准。","requirements":"1.本科及以上学历，专业不限；\n2.10年以上商品与供应链管理/品质管理相关工作经验；\n3.具备良好的团队管理能力和沟通协调能力；\n4.熟悉城市商品供应链管理流程，具有较强的问题解决能力；\n5.具备良好的执行力。\n6.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责城市品控团队的日常管理和指导，确保团队高效运转；\n2.负责城市商品与供应链管理/品质管理的工作，监督和协调产品采购、库存管理等工作；\n3.负责城市供应商管理，建立和维护良好的合作关系，确保供应链畅通；\n4.负责城市商品质量管理，监督产品质量，及时解决质量问题；\n5.参与制定城市品控策略和目标，确保城市品控工作符合公司标准。\n\n岗位基本要求\n1.本科及以上学历，专业不限；\n2.10年以上商品与供应链管理/品质管理相关工作经验；\n3.具备良好的团队管理能力和沟通协调能力；\n4.熟悉城市商品供应链管理流程，具有较强的问题解决能力；\n5.具备良好的执行力。\n6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\na. 热爱互联网和新零售行业，具有极强的快速学习能力；\nb. 有较强的质量管理方法论且可以快速结合业务特点落地能力。\n\n岗位亮点\n1.可在多个一二线城市展开工作，拓展城市品控管理经验；\n2.资深职级，享受高薪待遇和广阔的晋升空间；\n3.可带领大型团队，挑战管理能力和领导力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4258888433","sourceKey":"meituan_social","company":"美团","title":"成都交付-招聘经理","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4258888433&jobShareType=1","duty":"1. 根据业务发展阶段，制定合适的招聘策略，保障业务发展所需的人才供给，包括但不限于确定招聘目标、招聘渠道选择等；\n2. 对招聘需求及招聘数据进行分析，提供有效的招聘解决方案，提升招聘交付的质量和效率。招聘解决方案包括但不限于招聘需求与目标人才市场匹配度分析、人才寻访、有效的薪酬策略以及面试流程优化；\n3. 通过行业人才地图，为业务管理者搭建团队提供有效信息输入，包括市场趋势分析、竞争对手人才动态等，持续提升招聘工作对于业务发展的价值；\n4. 帮助业务管理者与行业资深人士建立链接，为业务团队持续储备引入优秀人才，同时建立和维护人才储备库，确保快速响应招聘需求；\n5. 配合招聘流程的管理和优化，确保招聘流程的合规性、效率性和体验感，包括简历筛选、面试安排、候选人体验管理等，提出招聘流程的改进建议。\n6. 主动使用AI工具提升招聘效率，包括但不限于：用AI辅助撰写职位描述、候选人沟通话术、面试评估报告；\n7. 用AI工具快速搜索和筛选候选人；探索AI在招聘场景中的创新应用；\n岗位要求：对AI工具有实际使用经历，能够将AI应用于日常工作（如文案撰写、信息检索、数据整理等），有持续学习新工具的习惯和意愿","requirements":"1.一年以上HR经验，对招聘工作有热情并有成功案例；\n2.自驱力强，勤奋好学，能够主动学习和理解业务需求及行业动态，对招聘过程中的数据进行分析，以便更好地适应和预测招聘需求；\n3.具备良好的沟通协调能力和人选管理技巧，能够有效地参与跨团队和跨职能的协同合作。\n4. 具备AI工具使用经验","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 根据业务发展阶段，制定合适的招聘策略，保障业务发展所需的人才供给，包括但不限于确定招聘目标、招聘渠道选择等；\n2. 对招聘需求及招聘数据进行分析，提供有效的招聘解决方案，提升招聘交付的质量和效率。招聘解决方案包括但不限于招聘需求与目标人才市场匹配度分析、人才寻访、有效的薪酬策略以及面试流程优化；\n3. 通过行业人才地图，为业务管理者搭建团队提供有效信息输入，包括市场趋势分析、竞争对手人才动态等，持续提升招聘工作对于业务发展的价值；\n4. 帮助业务管理者与行业资深人士建立链接，为业务团队持续储备引入优秀人才，同时建立和维护人才储备库，确保快速响应招聘需求；\n5. 配合招聘流程的管理和优化，确保招聘流程的合规性、效率性和体验感，包括简历筛选、面试安排、候选人体验管理等，提出招聘流程的改进建议。\n6. 主动使用AI工具提升招聘效率，包括但不限于：用AI辅助撰写职位描述、候选人沟通话术、面试评估报告；\n7. 用AI工具快速搜索和筛选候选人；探索AI在招聘场景中的创新应用；\n岗位要求：对AI工具有实际使用经历，能够将AI应用于日常工作（如文案撰写、信息检索、数据整理等），有持续学习新工具的习惯和意愿\n\n岗位基本要求\n1.一年以上HR经验，对招聘工作有热情并有成功案例；\n2.自驱力强，勤奋好学，能够主动学习和理解业务需求及行业动态，对招聘过程中的数据进行分析，以便更好地适应和预测招聘需求；\n3.具备良好的沟通协调能力和人选管理技巧，能够有效地参与跨团队和跨职能的协同合作。\n4. 具备AI工具使用经验\n\n岗位亮点\n1.招聘专业能力的体系化培养；\n2.清晰的发展路径：零售领域招聘专家或横向发展机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4208753649","sourceKey":"meituan_social","company":"美团","title":"商家及策略运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4208753649&jobShareType=1","duty":"1.策略制定与规划\n结合总部核心策略，基于城市洞察，制定差异化城市运营策略（商户拓展、运营提效、资源投放等）\n设计城市试点方案，验证策略有效性后规模化推广\n运营团队资源协同产品、销售团队，推动策略落地所需资源支持\n\n2.业务落地与执行\n推动策略在城市的执行，监控关键指标（商户数、GTV、财务收入、动销率、留存率等）\n通过商户培训、运营活动、资源对接等方式提升商户经营能力\n建立城市案例库，提炼可复制的成功方法论\n\n3.区域协同与赋能\n支持大区/区域负责人进行业务规划与目标拆解\n为城市一线团队提供策略指导、工具支持和培训赋能\n搭建区域信息共享机制，促进跨城市经验交流\n\n4.城市机会洞察\n负责区域市场分析，包括竞争格局、商户结构、用户需求、政策环境等\n识别高潜力城市、高增长品类、未被满足的市场需求\n建立城市分级评估体系，明确各城市发展优先级与策略重点\n\n5.数据驱动迭代\n建立城市级数据监控体系，定期输出经营分析报告\n通过数据监控及业务理解持续优化策略，提升投入产出比\n预警业务风险，提出应对建议\n\n6.借助LLM商户诊断工具快速识别不同城市的高潜力商户和未被满足的市场需求，利用AI辅助经营分析报告生成工具完成城市级数据监控和策略复盘。","requirements":"1.学历与经验\n本科及以上学历，3年以上互联网平台策略运营、商业分析、区域运营或咨询相关经验\n有本地生活、电商、O2O或医药健康行业经验者优先\n具备城市级市场拓展或运营实战经验者优先\n\n2.核心能力\n数据分析能力：熟练使用数据处理及分析工具，能独立完成城市市场分析、商户特征分析等\n策略规划能力：具备从洞察到策略设计、试点到规模化的完整方法论\n业务落地能力：能推动策略执行，解决一线实际问题，拿到业务结果\n沟通协同能力：能有效联动区域销售、产品、市场等多团队协作\n能使用AI数据分析工具辅助城市市场分析和商户特征画像构建，有将智能化工具融入区域运营工作流的经验者优先。\n\n3.特质要求\n结果导向，对业务增长有强烈责任感\n具备城市视角，理解不同层级城市差异\n适应区域出差（预计10%-20%左右时间）\n具备综合能力，能在不确定环境中推进工作","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.策略制定与规划\n结合总部核心策略，基于城市洞察，制定差异化城市运营策略（商户拓展、运营提效、资源投放等）\n设计城市试点方案，验证策略有效性后规模化推广\n运营团队资源协同产品、销售团队，推动策略落地所需资源支持\n\n2.业务落地与执行\n推动策略在城市的执行，监控关键指标（商户数、GTV、财务收入、动销率、留存率等）\n通过商户培训、运营活动、资源对接等方式提升商户经营能力\n建立城市案例库，提炼可复制的成功方法论\n\n3.区域协同与赋能\n支持大区/区域负责人进行业务规划与目标拆解\n为城市一线团队提供策略指导、工具支持和培训赋能\n搭建区域信息共享机制，促进跨城市经验交流\n\n4.城市机会洞察\n负责区域市场分析，包括竞争格局、商户结构、用户需求、政策环境等\n识别高潜力城市、高增长品类、未被满足的市场需求\n建立城市分级评估体系，明确各城市发展优先级与策略重点\n\n5.数据驱动迭代\n建立城市级数据监控体系，定期输出经营分析报告\n通过数据监控及业务理解持续优化策略，提升投入产出比\n预警业务风险，提出应对建议\n\n6.借助LLM商户诊断工具快速识别不同城市的高潜力商户和未被满足的市场需求，利用AI辅助经营分析报告生成工具完成城市级数据监控和策略复盘。\n\n岗位基本要求\n1.学历与经验\n本科及以上学历，3年以上互联网平台策略运营、商业分析、区域运营或咨询相关经验\n有本地生活、电商、O2O或医药健康行业经验者优先\n具备城市级市场拓展或运营实战经验者优先\n\n2.核心能力\n数据分析能力：熟练使用数据处理及分析工具，能独立完成城市市场分析、商户特征分析等\n策略规划能力：具备从洞察到策略设计、试点到规模化的完整方法论\n业务落地能力：能推动策略执行，解决一线实际问题，拿到业务结果\n沟通协同能力：能有效联动区域销售、产品、市场等多团队协作\n能使用AI数据分析工具辅助城市市场分析和商户特征画像构建，有将智能化工具融入区域运营工作流的经验者优先。\n\n3.特质要求\n结果导向，对业务增长有强烈责任感\n具备城市视角，理解不同层级城市差异\n适应区域出差（预计10%-20%左右时间）\n具备综合能力，能在不确定环境中推进工作\n\n具备以下条件优先\n熟悉医药健康行业政策、商户生态、用户行为\n有成功城市从0到1拓展或增长案例\n具备基础的项目管理、流程优化经验\n了解广告相关商业逻辑\n\n岗位亮点\n1.发展平台\n参与医药健康产业前沿业务\n深入区域市场实战，积累城市运营方法论\n职业发展通道清晰\n\n2.团队支持\n策略分析工具与数据平台\n区域团队一线落地支持\n定期策略复盘与专业培训\n人员包容开放，成长氛围好","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2959988082","sourceKey":"meituan_social","company":"美团","title":"境外门票-大客户经理","city":"上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2959988082&jobShareType=1","duty":"1.负责拓展和维护具备优质出境旅游景区的供给资源，建立合作关系\n2.负责商家在平台的运营辅导，对商家在平台的产出和成长负责\n3.负责商家在目的地的产品选品、上线、运营、营销推广等工作\n4.对负责的市场进行日常的信息收集，数据分析，用户需求的洞察，输出区域内商家、商品的运营优化计划并执行","requirements":"1）有旅游OTA、境外景区、旅游局等资源者优先\n2）具备优秀的商务沟通、拓展能力和大客户服务意识\n3）熟悉有产品设计、资源采购、平台运营经验优先\n4）具备境外业务的基础运营知识，数据分析能力，了解互联网的运营和工作方式","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.负责拓展和维护具备优质出境旅游景区的供给资源，建立合作关系\n2.负责商家在平台的运营辅导，对商家在平台的产出和成长负责\n3.负责商家在目的地的产品选品、上线、运营、营销推广等工作\n4.对负责的市场进行日常的信息收集，数据分析，用户需求的洞察，输出区域内商家、商品的运营优化计划并执行\n\n岗位基本要求\n1）有旅游OTA、境外景区、旅游局等资源者优先\n2）具备优秀的商务沟通、拓展能力和大客户服务意识\n3）熟悉有产品设计、资源采购、平台运营经验优先\n4）具备境外业务的基础运营知识，数据分析能力，了解互联网的运营和工作方式\n\n具备以下条件优先\n旅游管理、酒店管理、市场营销、外语专业优先\n\n岗位亮点\n1）能参与并推动美团境外业务发展过程，主导潜力项目\n2）有机会参与到部门管理与策略制定的过程\n3）有良好的自主空间，有大量创新、探索、验证自己的机会\n4）能和互联网行业的优秀人才共事，横向接触多品类多业务，获取高质量输入和广阔的学习空间","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4255061187","sourceKey":"meituan_social","company":"美团","title":"大模型风险防控技术专家","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4255061187&jobShareType=1","duty":"1. 负责大模型风险防控技术体系的设计与落地，包括内容安全、合规检测、对抗攻击防御等方向。  \n2. 构建并优化大模型风险识别与拦截系统，提升对有害信息、偏见输出、隐私泄露等风险的识别准确率与响应速度。  \n3. 跟踪国内外大模型安全领域最新技术动态，研究前沿算法并推动在业务场景中的创新应用。  \n4. 协同产品、算法与工程团队，制定风险防控策略，保障大模型服务的合规性与安全性。","requirements":"1. 硕士研究生及以上学历，计算机科学、人工智能、信息安全等相关专业。  \n2. 具备4年以上大模型或AI安全相关研发经验，熟悉大模型运行机制及常见风险类型。  \n3. 有内容安全、对抗样本、模型鲁棒性增强等实际项目经验。  \n4. 具备良好的系统架构能力与跨团队协作能力，承担技术攻坚任务。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责大模型风险防控技术体系的设计与落地，包括内容安全、合规检测、对抗攻击防御等方向。  \n2. 构建并优化大模型风险识别与拦截系统，提升对有害信息、偏见输出、隐私泄露等风险的识别准确率与响应速度。  \n3. 跟踪国内外大模型安全领域最新技术动态，研究前沿算法并推动在业务场景中的创新应用。  \n4. 协同产品、算法与工程团队，制定风险防控策略，保障大模型服务的合规性与安全性。\n\n岗位基本要求\n1. 硕士研究生及以上学历，计算机科学、人工智能、信息安全等相关专业。  \n2. 具备4年以上大模型或AI安全相关研发经验，熟悉大模型运行机制及常见风险类型。  \n3. 有内容安全、对抗样本、模型鲁棒性增强等实际项目经验。  \n4. 具备良好的系统架构能力与跨团队协作能力，承担技术攻坚任务。\n\n具备以下条件优先\n有大厂工作经验，在合规风险、内容风险、资金风险、舆情风险等领域有2年以上系统开发和架构经验，并当前专注于大模型风险防控领域的人才优先。\n\n岗位亮点\n1. 参与前沿大模型安全技术研究，与算法团队共同探索大模型安全边界，技术挑战性强。  \n3. 工作地点位于成都，享有具有竞争力的薪酬与完善的职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4248318022","sourceKey":"meituan_social","company":"美团","title":"医药-区域连锁运营-大客户经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4248318022&jobShareType=1","duty":"1、助力医药连锁提升O2O业务运营能力，包含但不限于商品供给、用户增长、流量效率、履约体验、商品营销等，并在合作中建立良好客情关系；\n2、负责对应医药连锁的日常运营管理，对连锁客户在平台经营的GTV等业绩目标结果负责，过程中需要对线上用户用药习惯和需求进行分析，识别商品生意机会，为客户提供定制化商品增长策略；\n3、基于连锁增长策略联动药企及平台资源，对经营投资和效果进行统筹管理，以满足连锁和药企的经营目标；","requirements":"1、本科及以上学历，3年以上医药零售运营相关工作经验；\n2、逻辑性强，善于分析总结，有较强的数据分析能力和业务敏感度；\n3、自我驱动，结果导向，有良好的沟通、表达和跨团队协调能力；\n4、较好项目管理能力，具备主动思考和创造性思维。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1、助力医药连锁提升O2O业务运营能力，包含但不限于商品供给、用户增长、流量效率、履约体验、商品营销等，并在合作中建立良好客情关系；\n2、负责对应医药连锁的日常运营管理，对连锁客户在平台经营的GTV等业绩目标结果负责，过程中需要对线上用户用药习惯和需求进行分析，识别商品生意机会，为客户提供定制化商品增长策略；\n3、基于连锁增长策略联动药企及平台资源，对经营投资和效果进行统筹管理，以满足连锁和药企的经营目标；\n\n岗位基本要求\n1、本科及以上学历，3年以上医药零售运营相关工作经验；\n2、逻辑性强，善于分析总结，有较强的数据分析能力和业务敏感度；\n3、自我驱动，结果导向，有良好的沟通、表达和跨团队协调能力；\n4、较好项目管理能力，具备主动思考和创造性思维。\n\n具备以下条件优先\n1、有药企新零售或连锁药店商品运营经验优先；\n2、有平台药品经验者优先；\n\n岗位亮点\n1、医药即时零售业务高速发展，业务市场机会大；\n2、团队氛围坦诚直接、能够在学习型组织中快速成长","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4012084517","sourceKey":"meituan_social","company":"美团","title":"小象超市-品控高阶交流岗","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4012084517&jobShareType=1","duty":"1.负责设计和实施小象业务的食品安全管理体系，确保其符合国家法规和行业标准。\n2.持续优化食品安全管理体系，提升其有效性和可操作性。\n3.负责快检实验室管控机制和体系的迭代，确保生鲜品满足小象的食品安全标准。\n4.推进抽检系统的线上化迭代，实现抽检过程的数字化和自动化；有效分析和跟踪商品的食品安全数据，及时发现和处理食品安全问题。\n5.跟进食品安全客诉的识别、治理、管控，确保改善闭环。\n6.开展食品安全风险监测，识别潜在的安全隐患；进行食品安全风险评估，量化风险的严重性和发生概率；制定和实施风险治理措施，降低食品安全风险。","requirements":"1.大学本科及以上学历，食品安全相关专业。\n2.至少5年以上品质管理相关工作经验，具备丰富的质量管理经验和技能。\n3.熟悉质量管理体系和相关标准，如ISO9001、22000、BRCGS、IFS等。\n4.具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n5.具备较强的问题分析能力和解决能力，能够快速识别并解决问题。\n6.具有较强的责任心，自驱力强，能够主动推进工作。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责设计和实施小象业务的食品安全管理体系，确保其符合国家法规和行业标准。\n2.持续优化食品安全管理体系，提升其有效性和可操作性。\n3.负责快检实验室管控机制和体系的迭代，确保生鲜品满足小象的食品安全标准。\n4.推进抽检系统的线上化迭代，实现抽检过程的数字化和自动化；有效分析和跟踪商品的食品安全数据，及时发现和处理食品安全问题。\n5.跟进食品安全客诉的识别、治理、管控，确保改善闭环。\n6.开展食品安全风险监测，识别潜在的安全隐患；进行食品安全风险评估，量化风险的严重性和发生概率；制定和实施风险治理措施，降低食品安全风险。\n\n岗位基本要求\n1.大学本科及以上学历，食品安全相关专业。\n2.至少5年以上品质管理相关工作经验，具备丰富的质量管理经验和技能。\n3.熟悉质量管理体系和相关标准，如ISO9001、22000、BRCGS、IFS等。\n4.具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n5.具备较强的问题分析能力和解决能力，能够快速识别并解决问题。\n6.具有较强的责任心，自驱力强，能够主动推进工作。\n\n具备以下条件优先\n具有线下超市、互联网零售丰富的食品安全管理经验者优先。\n\n岗位亮点\n1.专业发展：推动业务食品安全管理体系的建设、运行和改进，拓展专业领域和实践经验。\n2.创新机会：推动食品安全管理的数字化和智能化。\n3.团队管理：带领团队，与多部门合作，提升整体食品安全管理水平，确保消费者的健康和安全。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3849092678","sourceKey":"meituan_social","company":"美团","title":"品牌传播与创意营销设计师（线下）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3849092678&jobShareType=1","duty":"1.主导创意营销活动全案视觉设计，主要涉及线下传播物料、美陈、品牌传播、品牌周边等设计工作。\n2.把控设计全流程，从创意提案到落地执行（含工艺选材、印刷制作），保障视觉高品质与一致性。\n3.协同部门，结合业务目标与用户洞察，输出策略性视觉解决方案。\n4.统筹外包团队与供应商，制定设计标准并监督，确保项目高效交付。\n5.了解商业美陈设计，借其吸引顾客、强化品牌形象与营销效果。","requirements":"1.本科及以上学历，视觉传达等相关专业，3 年以上整合营销视觉设计经验，线下超市/美陈相关设计背景优先。\n2.有前瞻性审美与商业思维，能输出完整设计方案。\n3.精通设计工具，熟悉 AIGC辅助设计及实景合成技术者加分。\n4.掌握印刷工艺等线下制作全流程，可控制成本、规避风险。\n5.跨团队协作能力出色，有团队管理或外包统筹经验，能借视觉语言推行业务目标。\n6.有品牌设计经验，熟悉品牌相关设计及传播策略，有成功案例优先。\n7.对市场趋势和消费者行为洞察力敏锐，能转化品牌理念为视觉表达。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.主导创意营销活动全案视觉设计，主要涉及线下传播物料、美陈、品牌传播、品牌周边等设计工作。\n2.把控设计全流程，从创意提案到落地执行（含工艺选材、印刷制作），保障视觉高品质与一致性。\n3.协同部门，结合业务目标与用户洞察，输出策略性视觉解决方案。\n4.统筹外包团队与供应商，制定设计标准并监督，确保项目高效交付。\n5.了解商业美陈设计，借其吸引顾客、强化品牌形象与营销效果。\n\n岗位基本要求\n1.本科及以上学历，视觉传达等相关专业，3 年以上整合营销视觉设计经验，线下超市/美陈相关设计背景优先。\n2.有前瞻性审美与商业思维，能输出完整设计方案。\n3.精通设计工具，熟悉 AIGC辅助设计及实景合成技术者加分。\n4.掌握印刷工艺等线下制作全流程，可控制成本、规避风险。\n5.跨团队协作能力出色，有团队管理或外包统筹经验，能借视觉语言推行业务目标。\n6.有品牌设计经验，熟悉品牌相关设计及传播策略，有成功案例优先。\n7.对市场趋势和消费者行为洞察力敏锐，能转化品牌理念为视觉表达。\n\n具备以下条件优先\n1.有线下设计经验者优先\n2.有品牌设计相关经验者优先\n\n岗位亮点\n1.行业影响力：深度参与大型全案设计，作品覆盖千万级流量场景，助力个人与行业声量提升。\n2.个人成长：与多行业专业同学合作，加速专业及横向能力提升。\n3.创新实践机遇：主导从 0 到 1 的突破性设计项目，影响用户体验与购物习惯。\n4.设计沉淀分享：设计部有优质项目、多行业设计沉淀及知识供学习。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4176380411","sourceKey":"meituan_social","company":"美团","title":"上海青浦仓—晚班调度主管","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4176380411&jobShareType=1","duty":"1、负责司机及司机日常履约作业的监控和管理，客诉等履约问题的处理和异常信息同步；\n2、关注当日订单量，负责配送排线管理和路径规划，对配送司机进行排班管理；\n3、对现场司机作业异常情况的监控和问题处理，对有客诉、产生晚点等异常司机专项跟进和问题处理；\n4、新司机招募、司机配送事项培训和管理，提升司机服务质量；\n5、配合总部配送政策的落地实施和经营指标的达成；\n6、配送履约信息处理和数据监控，BD/客户/司机等多方的协同沟通；","requirements":"、三年以上物流或电商行业配送运营管理经验；\n2、熟悉城市配送运力结构和配送模式管理；\n3、从事过司机组织相关工作，对本城市交通较为熟悉；\n4、负责过车队管理工作，可快速组织运力；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、负责司机及司机日常履约作业的监控和管理，客诉等履约问题的处理和异常信息同步；\n2、关注当日订单量，负责配送排线管理和路径规划，对配送司机进行排班管理；\n3、对现场司机作业异常情况的监控和问题处理，对有客诉、产生晚点等异常司机专项跟进和问题处理；\n4、新司机招募、司机配送事项培训和管理，提升司机服务质量；\n5、配合总部配送政策的落地实施和经营指标的达成；\n6、配送履约信息处理和数据监控，BD/客户/司机等多方的协同沟通；\n\n岗位基本要求\n、三年以上物流或电商行业配送运营管理经验；\n2、熟悉城市配送运力结构和配送模式管理；\n3、从事过司机组织相关工作，对本城市交通较为熟悉；\n4、负责过车队管理工作，可快速组织运力；\n\n具备以下条件优先\n1、生鲜行业者优先考虑；\n2、有一定城配资源者优先考虑。\n\n岗位亮点\n1、在初创期投入生鲜电商领域，作为先驱者和公司共同摸索成长，锤炼对仓储管理的认识。\n2、知名互联网公司与传统物流行业的深度结合，与来自供应链领域的精英共事。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3930181446","sourceKey":"meituan_social","company":"美团","title":"医疗健康大客户销售经理","city":"北京市/上海市/广州市/深圳市/武汉市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3930181446&jobShareType=1","duty":"1.负责民营医疗行业大客户的合作和管理，通过市场调研和客户沟通，建立并维护与目标客户高层的良好合作关系。\n2.根据业务目标，制定有效的策略方案，达成深度业务合作，提升客户产值。\n3.负责开展市场信息收集、分析和整理，为公司决策提供参考依据。\n4.负责协调内部资源，与产品、运营、市场等部门紧密合作，推动项目的顺利进行。","requirements":"1.大学本科以上学历，医学、市场营销、商务管理等相关专业优先。\n2.具备5年以上医疗行业大客户销售经验，熟悉互联网行业、医疗行业市场和产品，熟悉各类销售渠道和销售技巧。\n3.具备良好的沟通和谈判能力，能够与高层管理人员进行有效沟通和合作。\n4.具备良好的逻辑思维和问题解决能力，能够独立思考和解决工作中的各种问题。\n5.具备较强的应变能力，能够在有挑战的工作环境下保持良好的工作状态。\n6.知名互联网平台企业工作经验者，有互联网广告销售运营的相关经验优先。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.负责民营医疗行业大客户的合作和管理，通过市场调研和客户沟通，建立并维护与目标客户高层的良好合作关系。\n2.根据业务目标，制定有效的策略方案，达成深度业务合作，提升客户产值。\n3.负责开展市场信息收集、分析和整理，为公司决策提供参考依据。\n4.负责协调内部资源，与产品、运营、市场等部门紧密合作，推动项目的顺利进行。\n\n岗位基本要求\n1.大学本科以上学历，医学、市场营销、商务管理等相关专业优先。\n2.具备5年以上医疗行业大客户销售经验，熟悉互联网行业、医疗行业市场和产品，熟悉各类销售渠道和销售技巧。\n3.具备良好的沟通和谈判能力，能够与高层管理人员进行有效沟通和合作。\n4.具备良好的逻辑思维和问题解决能力，能够独立思考和解决工作中的各种问题。\n5.具备较强的应变能力，能够在有挑战的工作环境下保持良好的工作状态。\n6.知名互联网平台企业工作经验者，有互联网广告销售运营的相关经验优先。\n\n岗位亮点\n1.有机会在民营医疗行业大客户销售领域展示个人能力和实现职业发展。\n2.薪资福利优厚，提供良好的晋升空间和职业发展通道。\n3.公司氛围轻松和谐，提供专业的培训和发展机会，打造专业销售团队。\n4.与民营医疗行业头部客户的关键人物对话合作，积累优质行业人脉。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2407060185","sourceKey":"meituan_social","company":"美团","title":"乐生活南部战区-产品销售","city":"福州市/厦门市/泉州市/广州市/深圳市/珠海市/汕头市/惠州市/东莞市/中山市/佛山市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2407060185&jobShareType=1","duty":"1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","requirements":"1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生。\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位基本要求\n1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生。\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n有机会学习并掌握互联网本地生活的工作方式","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3709635184","sourceKey":"meituan_social","company":"美团","title":"策略运营负责人","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3709635184&jobShareType=1","duty":"1.负责管理外卖配送业务一个或多个方向，包括：骑手定价补贴、供需管理、合作商考核运营、产品建设等策略的设计和优化；\n2.调研当地市场需求，对当时市场的运力管理和对应策略有洞察，制定具有竞争优势的运力模式和相关运力策略\n3.了解商户需求，对针对商流需求进行配送模式的创新，指定对应的一体化配送解决方案。","requirements":"1.有丰富策略运营经验，在O2O、互联网电商等相关行业，带领过复杂业务的策略运营或策略产品团队，并有成功案例；\n2.具备良好的团队管理能力和沟通协调能力，能够有效领导和激励团队成员，并推动团队之间合作；\n3.结果导向，具备较强的自驱力、学习能力，韧性强，能够从不同领域汲取经验并迅速应用，能够适应市场不确定性，勇于创新和突破。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1.负责管理外卖配送业务一个或多个方向，包括：骑手定价补贴、供需管理、合作商考核运营、产品建设等策略的设计和优化；\n2.调研当地市场需求，对当时市场的运力管理和对应策略有洞察，制定具有竞争优势的运力模式和相关运力策略\n3.了解商户需求，对针对商流需求进行配送模式的创新，指定对应的一体化配送解决方案。\n\n岗位基本要求\n1.有丰富策略运营经验，在O2O、互联网电商等相关行业，带领过复杂业务的策略运营或策略产品团队，并有成功案例；\n2.具备良好的团队管理能力和沟通协调能力，能够有效领导和激励团队成员，并推动团队之间合作；\n3.结果导向，具备较强的自驱力、学习能力，韧性强，能够从不同领域汲取经验并迅速应用，能够适应市场不确定性，勇于创新和突破。\n\n岗位亮点\n1.从零到一参与一个国家的业务成长，有机会接触到不同的商业机会和合作伙伴；\n1. Participate in the business growth of a country from scratch, with opportunities to explore diverse business prospects and partnerships;\n\n2.参与业务目标与策略制定，对Keeta业务目标和发展方向起到关键作用。\n2. Engage in business goal and strategy formulation, playing a pivotal role in Keeta's business objectives and development direction.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4016359499","sourceKey":"meituan_social","company":"美团","title":"解决方案专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4016359499&jobShareType=1","duty":"1. 负责为客户提供定制化解决方案，确保方案与业务目标高度匹配。  \n2. 协调跨部门资源，推动解决方案从设计到落地的全流程执行。  \n3. 分析客户需求及行业趋势，持续优化现有解决方案框架。  \n4. 主导解决方案的文档撰写、演示及客户培训工作。  \n5. 收集并反馈客户使用体验，推动产品迭代与改进。","requirements":"1.本科或以上学历 \n2. 有较好的中英文书写基础 \n3. 较为丰富的客户交流经验，有咨询规划、解决方案设计、项目售前经验者优先\n4. 医药相关专业优先考虑，有咨询公司工作经验优先考虑\n5. 较强的协作能力和团队合作能力 \n6. 良好的办公技能","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1. 负责为客户提供定制化解决方案，确保方案与业务目标高度匹配。  \n2. 协调跨部门资源，推动解决方案从设计到落地的全流程执行。  \n3. 分析客户需求及行业趋势，持续优化现有解决方案框架。  \n4. 主导解决方案的文档撰写、演示及客户培训工作。  \n5. 收集并反馈客户使用体验，推动产品迭代与改进。\n\n岗位基本要求\n1.本科或以上学历 \n2. 有较好的中英文书写基础 \n3. 较为丰富的客户交流经验，有咨询规划、解决方案设计、项目售前经验者优先\n4. 医药相关专业优先考虑，有咨询公司工作经验优先考虑\n5. 较强的协作能力和团队合作能力 \n6. 良好的办公技能\n\n岗位亮点\n1. 参与高复杂度项目，直接接触行业头部客户。  \n2. 提供跨领域学习机会，快速提升综合解决方案能力。  \n3. 完善的职业发展路径，可横向拓展至产品或战略方向","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4173912988","sourceKey":"meituan_social","company":"美团","title":"美团酒店业务经理","city":"郑州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4173912988&jobShareType=1","duty":"1、酒店新签：邀约未和美团合作的酒店商家入驻平台\n2、酒店运营：通过线下上门拜访和线上的方式，做好合作商家的经营诊断分析，优化线上经营方案，从而帮助商家获得更多订单和收入；\n3、维护好跟酒店商家的关系，协助商家处理售后问题，同时落地平台的策略和活动；\n4、关注所负责市场的旅游和消费动态，及时根据市场变化调整运营策略。","requirements":"1、具备较强的销售沟通技巧、运营思维、市场敏锐度；喜欢酒店和旅游行业；\n2、大专及以上学历；\n3、可以接受出差（有补贴）；\n4、有较强适应能力、执行力、学习能力与意愿。\n5、具备OTA行业、酒店运营经验以及酒店管理专业优先（应届生没有行业经验要求）；\n6、熟练使用office等办公与数据分析软件。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、酒店新签：邀约未和美团合作的酒店商家入驻平台\n2、酒店运营：通过线下上门拜访和线上的方式，做好合作商家的经营诊断分析，优化线上经营方案，从而帮助商家获得更多订单和收入；\n3、维护好跟酒店商家的关系，协助商家处理售后问题，同时落地平台的策略和活动；\n4、关注所负责市场的旅游和消费动态，及时根据市场变化调整运营策略。\n\n岗位基本要求\n1、具备较强的销售沟通技巧、运营思维、市场敏锐度；喜欢酒店和旅游行业；\n2、大专及以上学历；\n3、可以接受出差（有补贴）；\n4、有较强适应能力、执行力、学习能力与意愿。\n5、具备OTA行业、酒店运营经验以及酒店管理专业优先（应届生没有行业经验要求）；\n6、熟练使用office等办公与数据分析软件。\n\n岗位亮点\n1、酒店行业发展空间大，互联网大厂发展稳定\n2、6险一金，周末双休、带薪年假、每年免费体检\n3、底薪+绩效；在保障基础收入的前提下，能力越强薪资越高\n4、互联网黄埔军校，在职业发展的每个阶段都有完善的培训体系\n5、晋升公开透明，标准明确公开\n6、负责旅游景区市场，适合喜欢旅游的年轻人。\n7、团队氛围好，年轻群体，没有办公室政治","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4149125966","sourceKey":"meituan_social","company":"美团","title":"下沉市场-渠道经理（黑龙江区域）","city":"哈尔滨市/大庆市/齐齐哈尔市/牡丹江市/佳木斯市/鸡西市/鹤岗市/双鸭山市/伊春市/七台河市/黑河市/绥化市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4149125966&jobShareType=1","duty":"1.协助合作商组建和管理团队，辅导和监督合作商做好团队的管理工作；\n2.给合作商团队成员有效的培训和辅导；\n3.总结梳理合作商团队工作中的关键动作，使之流程标准化并落地执行；\n4.从外卖业务数据、配送数据、团购业务数据中发现问题，持续优化合作商的业务和管理；\n6.从合作商的角度出发思考问题，保证合作商与美团外卖在资源互补、目标一致的方向健康发展；\n7.对合作商团队进行公平公正且有效的工作考核，对不符合考核标准的合作商进行坚决清退。","requirements":"1.有强大的自驱力，渴望成功；\n2.出色的人际沟通能力、团队协作精神与团队建设能力；\n3.能接受黑龙江省内每月20天左右的出差；\n4.精力充沛，能出色完成任务；\n5.认同并有意愿去学习打造超强执行力的团队；\n6.为人力行正道，强烈认同以客户为中心、团队合作、拥抱变化、诚信、勤俭、敬业、学习成长的美团价值观。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.协助合作商组建和管理团队，辅导和监督合作商做好团队的管理工作；\n2.给合作商团队成员有效的培训和辅导；\n3.总结梳理合作商团队工作中的关键动作，使之流程标准化并落地执行；\n4.从外卖业务数据、配送数据、团购业务数据中发现问题，持续优化合作商的业务和管理；\n6.从合作商的角度出发思考问题，保证合作商与美团外卖在资源互补、目标一致的方向健康发展；\n7.对合作商团队进行公平公正且有效的工作考核，对不符合考核标准的合作商进行坚决清退。\n\n岗位基本要求\n1.有强大的自驱力，渴望成功；\n2.出色的人际沟通能力、团队协作精神与团队建设能力；\n3.能接受黑龙江省内每月20天左右的出差；\n4.精力充沛，能出色完成任务；\n5.认同并有意愿去学习打造超强执行力的团队；\n6.为人力行正道，强烈认同以客户为中心、团队合作、拥抱变化、诚信、勤俭、敬业、学习成长的美团价值观。\n\n具备以下条件优先\n有渠道管理、物流管理、运营管理、外卖、团购、零售相关行业经验优先；26年应届生可聊，公司有专项发展培养计划。\n\n岗位亮点\n完善的晋升&考核机制，负责管理区域内外卖&团购业务视野宽阔，良好的公司文化以及团队氛围，成长空间大 。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4208762093","sourceKey":"meituan_social","company":"美团","title":"美团骑行-运营主管（杭州）","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4208762093&jobShareType=1","duty":"1、负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2、通实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3、根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4、配合政府部门对城市运营问题进行管理；\n5、协助运营经理管理运营团队，提升团队工作效率和结果。","requirements":"1．本科及以上学历。\n2、1一年以上团队管理经验。\n3、善于用开拓性思维解决问题，有较强的执行力和多部门协调能力。\n4、过往有相关行业经验。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2、通实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3、根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4、配合政府部门对城市运营问题进行管理；\n5、协助运营经理管理运营团队，提升团队工作效率和结果。\n\n岗位基本要求\n1．本科及以上学历。\n2、1一年以上团队管理经验。\n3、善于用开拓性思维解决问题，有较强的执行力和多部门协调能力。\n4、过往有相关行业经验。\n\n具备以下条件优先\n1、出行行业或互联网行业经验，\n2、有快消品区域覆盖或互联网城市地推管理经验者优先；\n3、善于数据分析，并能通过数据分析的结果不断优整工作。\n4、接受区域调配者优先。\n\n岗位亮点\n互联网大厂的广阔发展空间，未来负责多城运营，有晋升空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3290476537","sourceKey":"meituan_social","company":"美团","title":"渠道经理","city":"盐城市/常州市/湖州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3290476537&jobShareType=1","duty":"1.负责区域内合作商的挖掘和洽谈合作，制定招商规划，并在规定时间周期内完成招商目标；\n2.基于招商政策，客观评估合作商能力，进行信息提报，跟进招商进展；\n3.负责区域内合作商选、用、育、励、汰，培养更多优质合作商；\n4.协助合作商完成招管培汰、盈亏改善等环节，并就各环节问题，及时反馈给总部协同部门；\n5.负责管辖区内市场及行业信息收集反馈。","requirements":"1.专科及以上学历，2年以上渠道商管理经验；\n2.良好的商务谈判能力，沟通协调能力，能够制定招商规划，对招商结果负责；\n3.具备良好的渠道维护意识，在合作商选、育、用、励、汰环节，有基础的方法和技巧；\n4.积极乐观，敢于挑战，为人正直，诚实可靠。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1.负责区域内合作商的挖掘和洽谈合作，制定招商规划，并在规定时间周期内完成招商目标；\n2.基于招商政策，客观评估合作商能力，进行信息提报，跟进招商进展；\n3.负责区域内合作商选、用、育、励、汰，培养更多优质合作商；\n4.协助合作商完成招管培汰、盈亏改善等环节，并就各环节问题，及时反馈给总部协同部门；\n5.负责管辖区内市场及行业信息收集反馈。\n\n岗位基本要求\n1.专科及以上学历，2年以上渠道商管理经验；\n2.良好的商务谈判能力，沟通协调能力，能够制定招商规划，对招商结果负责；\n3.具备良好的渠道维护意识，在合作商选、育、用、励、汰环节，有基础的方法和技巧；\n4.积极乐观，敢于挑战，为人正直，诚实可靠。\n\n具备以下条件优先\n1.具备O2O相关行业从业经验，有收银业务经历优先；\n2.能够接受异地出差者优先。\n\n岗位亮点\n1.有机会全身心地参与美团餐饮系统发展机会中，和团队一起探索未来；\n2.我们有开放、直接的工作氛围，以逻辑和事实说话，而不是岗位级别和层级。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4127151218","sourceKey":"meituan_social","company":"美团","title":"餐饮SaaS渠道经理（华中）","city":"郑州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4127151218&jobShareType=1","duty":"1.负责制定和执行公司的渠道发展策略，推动业务拓展和市场份额增长。\n2.负责渠道资源的开发和管理，建立并维护与渠道伙伴的良好合作关系。\n3.负责渠道销售团队的组建和管理，包括团队目标设定、业绩管理和团队培训等。\n4.负责市场调研和竞争对手分析，为渠道销售策略提供数据支持。\n5.监测和分析渠道销售数据，及时调整销售策略和方案。","requirements":"1.大学专科及以上学历，市场营销、商务管理或相关专业优先。\n2.具备3年以上渠道销售或业务开发经验，熟悉渠道管理流程和销售模式。\n3.具备良好的沟通能力和团队合作精神，能够有效协调内外部资源。\n4.具备较强的市场洞察力和分析能力，能够准确判断市场需求并制定相应销售策略。\n5.具备一定的管理经验，能够带领团队实现销售目标。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1.负责制定和执行公司的渠道发展策略，推动业务拓展和市场份额增长。\n2.负责渠道资源的开发和管理，建立并维护与渠道伙伴的良好合作关系。\n3.负责渠道销售团队的组建和管理，包括团队目标设定、业绩管理和团队培训等。\n4.负责市场调研和竞争对手分析，为渠道销售策略提供数据支持。\n5.监测和分析渠道销售数据，及时调整销售策略和方案。\n\n岗位基本要求\n1.大学专科及以上学历，市场营销、商务管理或相关专业优先。\n2.具备3年以上渠道销售或业务开发经验，熟悉渠道管理流程和销售模式。\n3.具备良好的沟通能力和团队合作精神，能够有效协调内外部资源。\n4.具备较强的市场洞察力和分析能力，能够准确判断市场需求并制定相应销售策略。\n5.具备一定的管理经验，能够带领团队实现销售目标。\n\n岗位亮点\n1.丰富的业务开发和渠道管理经验，能够在市场竞争激烈的环境中有效推动业务增长。\n2.提供良好的晋升机会和职业发展空间，能够快速成长为高级渠道经理。\n3.所在工作城市为长沙市，享受良好的生活和工作环境，拥有广阔的市场发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4095015424","sourceKey":"meituan_social","company":"美团","title":"美团酒店SaaS销售（广州优先）","city":"广州市/南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4095015424&jobShareType=1","duty":"1.负责所属区域酒店SaaS的推广，为商家赋能，帮助商家向数字化方向转型，执行公司销售策略，达成业绩考核及个人成长的各项目标。\n2.负责所属区域的客户的开发、产品演示、商务谈判、签署合同、款项收回。\n3.开拓、维护客户网络，与客户建立良好关系，维护企业形象。\n4.与公司各部门配合，及时处理商家反馈、投诉和建议，提高商家满意度。","requirements":"1.大专以上学历，具备一年以上的销售工作经验，热爱销售工作，有SaaS、酒店相关销售经验优先。\n2.备较强的商务谈判能力，思维敏捷，能够熟练掌握产品功能和优势卖点，能够高效整合内外部资源独自促成销售业绩达成。\n3.结果导向，有强烈的事业心、使命感和和自我驱动。\n4.有较强的自我学习、自我驱动力。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.负责所属区域酒店SaaS的推广，为商家赋能，帮助商家向数字化方向转型，执行公司销售策略，达成业绩考核及个人成长的各项目标。\n2.负责所属区域的客户的开发、产品演示、商务谈判、签署合同、款项收回。\n3.开拓、维护客户网络，与客户建立良好关系，维护企业形象。\n4.与公司各部门配合，及时处理商家反馈、投诉和建议，提高商家满意度。\n\n岗位基本要求\n1.大专以上学历，具备一年以上的销售工作经验，热爱销售工作，有SaaS、酒店相关销售经验优先。\n2.备较强的商务谈判能力，思维敏捷，能够熟练掌握产品功能和优势卖点，能够高效整合内外部资源独自促成销售业绩达成。\n3.结果导向，有强烈的事业心、使命感和和自我驱动。\n4.有较强的自我学习、自我驱动力。\n\n岗位亮点\n我们是一个充满激情和梦想的创业团队，我们为您提供发挥个人才能的舞台、有竞争力的薪酬待遇，以及宽阔的职业成长空间。我们正在寻找的是，志同道合、热忱、敏捷、主动，能一起愉快玩耍并共同成长的小伙伴们。请加入我们，和我们一起，共同打造一家优秀的高成长企业，并分享丰硕的成果。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3482325813","sourceKey":"meituan_social","company":"美团","title":"下沉市场 - 渠道经理（陕宁区域）","city":"西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3482325813&jobShareType=1","duty":"1.负责区域内目标合作商的挖掘和洽谈合作工作，并带领合作商完成美团外卖的业务目标；\n2.协助合作商组建和管理团队，辅导和监督合作商做好团队的管理工作；\n3.给合作商团队成员有效的培训和辅导；\n4.总结梳理合作商团队工作中的关键动作，使之流程标准化并落地执行；\n5.从外卖业务数据和配送数据中发现问题，持续优化合作商的业务和管理；\n6.从合作商的角度出发思考问题，保证合作商与美团外卖在资源互补、目标一致的方向健康发展；\n7.对合作商团队进行公平公正且有效的工作考核，对不符合考核标准的合作商进行坚决清退。","requirements":"1.能接受区域内长期出差\n2.出色的人际沟通能力、团队协作精神与团队建设能力\n3.商超、大型连锁便利店的2年以上店铺运营经验：鲜花、水果品类经验是为主，所涉及其他品类越多越好\n4.在和区域/城市对接上，能有全面经营视角赋能合作商长短期价值回报，驱动合作商去做长短期投入\n5.认同并有意愿去学习打造超强执行力的团队； 6.为人力行正道，强烈认同以客户为中心、团队合作、拥抱变化、诚信、勤俭、敬业、学习成长的美团价值观。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.负责区域内目标合作商的挖掘和洽谈合作工作，并带领合作商完成美团外卖的业务目标；\n2.协助合作商组建和管理团队，辅导和监督合作商做好团队的管理工作；\n3.给合作商团队成员有效的培训和辅导；\n4.总结梳理合作商团队工作中的关键动作，使之流程标准化并落地执行；\n5.从外卖业务数据和配送数据中发现问题，持续优化合作商的业务和管理；\n6.从合作商的角度出发思考问题，保证合作商与美团外卖在资源互补、目标一致的方向健康发展；\n7.对合作商团队进行公平公正且有效的工作考核，对不符合考核标准的合作商进行坚决清退。\n\n岗位基本要求\n1.能接受区域内长期出差\n2.出色的人际沟通能力、团队协作精神与团队建设能力\n3.商超、大型连锁便利店的2年以上店铺运营经验：鲜花、水果品类经验是为主，所涉及其他品类越多越好\n4.在和区域/城市对接上，能有全面经营视角赋能合作商长短期价值回报，驱动合作商去做长短期投入\n5.认同并有意愿去学习打造超强执行力的团队； 6.为人力行正道，强烈认同以客户为中心、团队合作、拥抱变化、诚信、勤俭、敬业、学习成长的美团价值观。\n\n具备以下条件优先\n有团购、外卖、众包等经验优先\n\n岗位亮点\n完善的晋升&考核机制，负责管理区域内外卖渠道业务的全闭环，良好的公司文化以及团队氛围，成长空间大 。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3992546370","sourceKey":"meituan_social","company":"美团","title":"SaaS软件渠道销售经理","city":"北京市/上海市/广州市/深圳市/武汉市/西安市/成都市/天津市/杭州市/济南市/郑州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3992546370&jobShareType=1","duty":"1. 负责美容、美发、美甲和足疗SaaS系统在指定区的代理商渠道拓展工作。  \n2. 与代理商建立并维护长期合作关系，完成销售目标。  \n3. 分析市场动态和客户需求，制定并执行有效的销售策略。  \n4. 协调内部资源，推动项目落地及客户成功。  \n5. 定期汇报销售进展，优化销售流程。","requirements":"1. 大学专科及以上学历。  \n2. 具备至少3年以上美业产品销售经验或渠道代理商开发经验。  \n3. 熟悉美容、美发、美甲和足疗系统或相关行业知识。  \n4. 具备良好的沟通能力和拿结果能力。  \n5. 能适应高频出差，工作地点为北京、西安、沈阳、郑州、长沙、杭州、上海、成都、广州、深圳等。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责美容、美发、美甲和足疗SaaS系统在指定区的代理商渠道拓展工作。  \n2. 与代理商建立并维护长期合作关系，完成销售目标。  \n3. 分析市场动态和客户需求，制定并执行有效的销售策略。  \n4. 协调内部资源，推动项目落地及客户成功。  \n5. 定期汇报销售进展，优化销售流程。\n\n岗位基本要求\n1. 大学专科及以上学历。  \n2. 具备至少3年以上美业产品销售经验或渠道代理商开发经验。  \n3. 熟悉美容、美发、美甲和足疗系统或相关行业知识。  \n4. 具备良好的沟通能力和拿结果能力。  \n5. 能适应高频出差，工作地点为北京、西安、沈阳、郑州、长沙、杭州、上海、成都、广州、深圳等。\n\n具备以下条件优先\n酒店三美一足相关销售从业经验，软件渠道销售相关从业经验\n\n岗位亮点\n1. 加入快速发展的三美一足行业，接触前沿数字化解决方案。  \n2. 提供系统的销售培训和职业发展通道。  \n3. 弹性工作制，注重结果导向。  \n4. 团队氛围开放，鼓励创新和协作。  \n5. 薪资结构包含高比例绩效奖金，激励性强。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4097725157","sourceKey":"meituan_social","company":"美团","title":"美团骑行-渠道经理（辽宁）","city":"沈阳市/大连市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4097725157&jobShareType=1","duty":"1.负责完成城市群的渠道下沉市场合作商的管理维护工作和合作商运营相关指标业绩达成；\n2.研究分析负责城市运营和特点，并对所负责的渠道进行规划和培养，推动渠道合作伙伴投入人力、资源达成任务；\n3.跟踪考核渠道商，并及时发现合作过程的问题并进行总结和反馈，跟进问题的优化；\n4.负责合作商的培训和其他相关支持的落地，辅助合作商项目所涉及的内部部门沟通协调；\n5.搜集反馈市场信息，分析市场数据，储备优质合作商资源；\n6.传达公司政策及市场活动等信息，保证和合作商之间的沟通顺畅。","requirements":"1.本科学历及以上，3年以上渠道业务开发和渠道管理经验；\n2.学习并好奇，对渠道业务管理模式有较深的认知，有较丰富的跨区域管理经验；\n3.商务沟通能力强，有协调并处置联合落地项目中，遇到的复杂博弈问题类经验；\n4.有直接对接政府单位沟通和维护经验；\n5.能够接受区域内高频出差。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责完成城市群的渠道下沉市场合作商的管理维护工作和合作商运营相关指标业绩达成；\n2.研究分析负责城市运营和特点，并对所负责的渠道进行规划和培养，推动渠道合作伙伴投入人力、资源达成任务；\n3.跟踪考核渠道商，并及时发现合作过程的问题并进行总结和反馈，跟进问题的优化；\n4.负责合作商的培训和其他相关支持的落地，辅助合作商项目所涉及的内部部门沟通协调；\n5.搜集反馈市场信息，分析市场数据，储备优质合作商资源；\n6.传达公司政策及市场活动等信息，保证和合作商之间的沟通顺畅。\n\n岗位基本要求\n1.本科学历及以上，3年以上渠道业务开发和渠道管理经验；\n2.学习并好奇，对渠道业务管理模式有较深的认知，有较丰富的跨区域管理经验；\n3.商务沟通能力强，有协调并处置联合落地项目中，遇到的复杂博弈问题类经验；\n4.有直接对接政府单位沟通和维护经验；\n5.能够接受区域内高频出差。\n\n岗位亮点\n1.提供良好的晋升空间和发展机会；\n2.团队氛围融洽，工作氛围轻松愉快；\n3.公司福利完善，提供具有竞争力的薪酬待遇。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3911884511","sourceKey":"meituan_social","company":"美团","title":"美团酒店SaaS销售（北京 石家庄优先）","city":"北京市/石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3911884511&jobShareType=1","duty":"1.负责业务开发和地面产品销售工作，完成销售目标。\n2.负责管理北京组的产品销售团队，指导团队成员完成销售任务。\n3.负责与客户建立良好的关系，维护客户的满意度。\n4.负责制定销售计划和策略，推动销售业绩的提升。","requirements":"1.大学专科以上学历，市场营销、销售管理等相关专业优先。\n2.有2年以上业务开发或产品销售经验，有团队管理经验者优先考虑。\n3.具备良好的沟通能力、团队合作精神和酒店运营能力。\n4.熟悉北京市场，有一定的客户资源和销售渠道。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.负责业务开发和地面产品销售工作，完成销售目标。\n2.负责管理北京组的产品销售团队，指导团队成员完成销售任务。\n3.负责与客户建立良好的关系，维护客户的满意度。\n4.负责制定销售计划和策略，推动销售业绩的提升。\n\n岗位基本要求\n1.大学专科以上学历，市场营销、销售管理等相关专业优先。\n2.有2年以上业务开发或产品销售经验，有团队管理经验者优先考虑。\n3.具备良好的沟通能力、团队合作精神和酒店运营能力。\n4.熟悉北京市场，有一定的客户资源和销售渠道。\n\n岗位亮点\n1.可以在北京市场拓展个人影响力，实现个人职业发展。\n2.可以带领团队完成销售目标，获得团队合作的快乐和成就感。\n3.能够接触到各种类型的客户，拓展人脉关系，为未来的事业发展奠定基础。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3342130787","sourceKey":"meituan_social","company":"美团","title":"大模型应用算法专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3342130787&jobShareType=1","duty":"1、负责大模型技术在核心业务场景的落地应用，0到1设计AI解决方案，重塑用户体验与业务流程；\n2、主导大模型应用架构设计，包括但不限于Prompt工程、Agent系统开发、模型微调、分布式推理优化等关键技术突破；\n3、深入理解业务场景与用户痛点，将LLM、多模态等前沿技术与业务需求深度结合，打造差异化智能产品；\n4、构建大模型应用评估体系，持续优化效果、性能及成本指标，建立可复用的技术资产与最佳实践；\n5、跟踪AIGC领域最新进展，推动技术选型与架构演进；\n6、负责跨团队协作，联动算法工程、产品、设计等角色，确保项目高质量交付；\n7、培养AI应用人才梯队，建设大模型应用方法论与技术标准。","requirements":"1、硕士及以上学历，计算机/人工智能等相关专业，3年以上AI算法研发经验；\n2、具备大模型落地项目全流程经验；\n3、具备大模型推理优化经验，熟悉主流大模型技术栈；\n4、扎实的算法基础，在NLP/CV/多模态至少一个领域有深入研究，顶会论文或专利成果优先；\n5、优秀的业务抽象能力，能将复杂场景转化为可量化的技术问题；\n6、强烈的技术热情与创新意识，对AI&大模型相关的技术演进有独到见解；\n7、出色的跨团队协作能力，能同时应对技术攻关与业务落地双重挑战。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1、负责大模型技术在核心业务场景的落地应用，0到1设计AI解决方案，重塑用户体验与业务流程；\n2、主导大模型应用架构设计，包括但不限于Prompt工程、Agent系统开发、模型微调、分布式推理优化等关键技术突破；\n3、深入理解业务场景与用户痛点，将LLM、多模态等前沿技术与业务需求深度结合，打造差异化智能产品；\n4、构建大模型应用评估体系，持续优化效果、性能及成本指标，建立可复用的技术资产与最佳实践；\n5、跟踪AIGC领域最新进展，推动技术选型与架构演进；\n6、负责跨团队协作，联动算法工程、产品、设计等角色，确保项目高质量交付；\n7、培养AI应用人才梯队，建设大模型应用方法论与技术标准。\n\n岗位基本要求\n1、硕士及以上学历，计算机/人工智能等相关专业，3年以上AI算法研发经验；\n2、具备大模型落地项目全流程经验；\n3、具备大模型推理优化经验，熟悉主流大模型技术栈；\n4、扎实的算法基础，在NLP/CV/多模态至少一个领域有深入研究，顶会论文或专利成果优先；\n5、优秀的业务抽象能力，能将复杂场景转化为可量化的技术问题；\n6、强烈的技术热情与创新意识，对AI&大模型相关的技术演进有独到见解；\n7、出色的跨团队协作能力，能同时应对技术攻关与业务落地双重挑战。\n\n岗位亮点\n1、有机会参与行业的大型项目，挑战性和发展空间大；\n2、团队氛围好，成员技术实力雄厚，有良好的学习和成长机会；\n3、公司提供具有竞争力的薪酬福利和晋升机制，为优秀人才提供广阔的发展平台。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4146597332","sourceKey":"meituan_social","company":"美团","title":"食安巡检","city":"苏州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4146597332&jobShareType=1","duty":"1、负责属地门店食品安全巡检工作及对巡检问题的改善跟进至闭环。\n\n2、食安风险预防与管控，识别存在或潜在的食安风险，量化风险的严重性和发生概率，制定和实施风险治理措施，降低食品安全风险。\n\n3、食安培训：制定食安培训计划，定期进行食安文化宣导，确保人员掌握食安要求，提升一线标准化操作与执行力，强化员工的服务意识和专业技能。","requirements":"1、本科及以上学历，食品药品相关专业，具备3-5年及以上连锁餐饮、连锁食品零售行业等相关领域工作经验。\n\n2、有较强的逻辑思维能力、表达能力、总结沉淀能力、较强的分析解决问题能力，\n\n3、具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n\n4、具有较强的责任心，自驱力强，能够主动推进工作。\n\n5、熟悉食品安全法等法律法规。\n\n6、接受区域内短期跨城出差。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责属地门店食品安全巡检工作及对巡检问题的改善跟进至闭环。\n\n2、食安风险预防与管控，识别存在或潜在的食安风险，量化风险的严重性和发生概率，制定和实施风险治理措施，降低食品安全风险。\n\n3、食安培训：制定食安培训计划，定期进行食安文化宣导，确保人员掌握食安要求，提升一线标准化操作与执行力，强化员工的服务意识和专业技能。\n\n岗位基本要求\n1、本科及以上学历，食品药品相关专业，具备3-5年及以上连锁餐饮、连锁食品零售行业等相关领域工作经验。\n\n2、有较强的逻辑思维能力、表达能力、总结沉淀能力、较强的分析解决问题能力，\n\n3、具备良好的团队合作能力和沟通能力，能够与不同部门进行有效地合作和沟通。\n\n4、具有较强的责任心，自驱力强，能够主动推进工作。\n\n5、熟悉食品安全法等法律法规。\n\n6、接受区域内短期跨城出差。\n\n具备以下条件优先\n具备一定的数据分析、内控审计经验、SQL能力者，线下超市、互联网零售丰富的食品安全管理经验者优先\n\n岗位亮点\n1、专业发展：推动业务食品安全管理体系的建设、运行和改进，提升品质管理水平和效率，拓展专业领域和实践经验。\n\n2、创新机会：推动食品安全管理的数字化和智能化。\n\n3、团队管理：与多部门合作，提升整体食品安全管理水平，确保消费者的健康和安全。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3815790286","sourceKey":"meituan_social","company":"美团","title":"商品分析策略","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3815790286&jobShareType=1","duty":"1. 经营指标体系搭建：以品类经营全链条视角，搭建并持续完善数据驱动的商品经营指标框架；通过多维度数据刻画业务表现与策略效果，灵敏反映经营现状；积极探索 AI 工具在指标体系搭建与监控中的应用，帮助管理层清晰判断形势、识别机会，为一线团队提供量化的动作指引与决策依据。\n2. 机会洞察与策略输出：针对识别的经营机会，以供给视角出发产出深度数据分析报告与可落地的解决方案；通过周/月度经营分析会场景影响业务决策，持续追踪策略落地效果并将成功经验沉淀为标准化指标与方法论；借助 AI 辅助工具提升数据提取、分析与报告生成效率。\n3. 复盘分析与决策支持：负责业务重要议题的复盘分析，运用结构化分析方法提炼关键结论，输出宏观-中观-微观多层次业务策略建议，用数据支撑业务决策并追踪结果达成。","requirements":"1. 教育背景：本科及以上学历，统计学、数学、经济学、商业分析或相关专业优先。\n2. 工作经验：具备商业分析、数据分析或经营分析相关工作经验；有生鲜零售、电商、自有品牌或快消行业经验者优先。\n3. 数据能力（核心）：\n熟悉数据分析工具进行数据提取与分析\n熟悉互联网常见的数据分析方法论（如归因分析、漏斗分析、同期群分析等）\n了解或熟悉 AI 辅助分析工具（如大语言模型辅助数据处理、报告生成），有将 AI 工具应用于实际业务分析场景的经验者优先\n4. 专业素质：具备出色的数据敏感性与商业洞察力，逻辑清晰，善于从复杂数据中提炼核心观点并转化为可执行的业务建议。\n沟通协作：优秀的沟通表达与协调能力，能够有效对接采购、运营、供应链等多方团队；具备较强的自驱力与快速学习能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 经营指标体系搭建：以品类经营全链条视角，搭建并持续完善数据驱动的商品经营指标框架；通过多维度数据刻画业务表现与策略效果，灵敏反映经营现状；积极探索 AI 工具在指标体系搭建与监控中的应用，帮助管理层清晰判断形势、识别机会，为一线团队提供量化的动作指引与决策依据。\n2. 机会洞察与策略输出：针对识别的经营机会，以供给视角出发产出深度数据分析报告与可落地的解决方案；通过周/月度经营分析会场景影响业务决策，持续追踪策略落地效果并将成功经验沉淀为标准化指标与方法论；借助 AI 辅助工具提升数据提取、分析与报告生成效率。\n3. 复盘分析与决策支持：负责业务重要议题的复盘分析，运用结构化分析方法提炼关键结论，输出宏观-中观-微观多层次业务策略建议，用数据支撑业务决策并追踪结果达成。\n\n岗位基本要求\n1. 教育背景：本科及以上学历，统计学、数学、经济学、商业分析或相关专业优先。\n2. 工作经验：具备商业分析、数据分析或经营分析相关工作经验；有生鲜零售、电商、自有品牌或快消行业经验者优先。\n3. 数据能力（核心）：\n熟悉数据分析工具进行数据提取与分析\n熟悉互联网常见的数据分析方法论（如归因分析、漏斗分析、同期群分析等）\n了解或熟悉 AI 辅助分析工具（如大语言模型辅助数据处理、报告生成），有将 AI 工具应用于实际业务分析场景的经验者优先\n4. 专业素质：具备出色的数据敏感性与商业洞察力，逻辑清晰，善于从复杂数据中提炼核心观点并转化为可执行的业务建议。\n沟通协作：优秀的沟通表达与协调能力，能够有效对接采购、运营、供应链等多方团队；具备较强的自驱力与快速学习能力。\n\n具备以下条件优先\n1. 有生鲜零售、自有品牌或快消行业商品经营/品类管理经验者优先\n2. 有商品生命周期分析、定价策略分析或供应链优化相关项目经验者优先\n3. 有 Python/R 编程基础或有 A/B Test 实验设计经验者加分\n4. 有 DS 经验和商业 sense 优秀是加分项\n\n岗位亮点\n1. 在美团食杂零售核心业务线上，实现从数据研究→策略规划→方案落地的完整闭环，工作内容复杂度高、挑战性大，个人成长空间广阔。\n2. 与零售、采购等行业资深专家紧密协作，深入理解生鲜零售全链条经营逻辑；同时接触前沿的智能化商品经营决策体系，培养 \"业务+数据+AI\"复合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3671395241","sourceKey":"meituan_social","company":"美团","title":"中医KA大客户销售","city":"北京市/上海市/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3671395241&jobShareType=1","duty":"1.负责制定并执行中医大客户销售业务发展计划，完成销售指标；\n2.负责开拓并维护中医领域的大客户关系，建立长期合作伙伴关系；\n3.跟进客户需求，协调内部资源，解决客户问题，确保客户满意度；\n4.定期汇报销售业绩及市场动态，提出改进建议。\n5.根据中医市场发展趋势，拉动头部机构在平台的货架供给，医生供给等，优化提升品牌在平台的运营效能。\n6.通过销运提升品牌线上化率，树立头部标杆和合作案例。扩大美团中医在市场的影响力。","requirements":"1.大学本科以上学历，中医，医疗相关专业优先；\n2.三年以上大客户销售经验，有医疗类成功案例者优先考虑；\n3.具备优秀的沟通能力、谈判技巧和团队管理能力；\n4.具备较强的学习能力和谈判能力，有较强的执行力和结果导向。具备坚韧不屈，迎难而上的心理素质\n5.需要有跨城管理大客户能力\n6.具有基本的运营数据分析能力和较强的销售演讲能力","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.负责制定并执行中医大客户销售业务发展计划，完成销售指标；\n2.负责开拓并维护中医领域的大客户关系，建立长期合作伙伴关系；\n3.跟进客户需求，协调内部资源，解决客户问题，确保客户满意度；\n4.定期汇报销售业绩及市场动态，提出改进建议。\n5.根据中医市场发展趋势，拉动头部机构在平台的货架供给，医生供给等，优化提升品牌在平台的运营效能。\n6.通过销运提升品牌线上化率，树立头部标杆和合作案例。扩大美团中医在市场的影响力。\n\n岗位基本要求\n1.大学本科以上学历，中医，医疗相关专业优先；\n2.三年以上大客户销售经验，有医疗类成功案例者优先考虑；\n3.具备优秀的沟通能力、谈判技巧和团队管理能力；\n4.具备较强的学习能力和谈判能力，有较强的执行力和结果导向。具备坚韧不屈，迎难而上的心理素质\n5.需要有跨城管理大客户能力\n6.具有基本的运营数据分析能力和较强的销售演讲能力\n\n岗位亮点\n1.有机会在中医领域深耕各个医疗环节，发展空间大；\n2.中医市场发展迅速，核心城市覆盖，极大提升跨城管理和片区管理能力；\n3.有竞争力的销售激励制度，培训机会和晋升空间广大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3588668752","sourceKey":"meituan_social","company":"美团","title":"冻牛羊集采专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3588668752&jobShareType=1","duty":"一、核心采购业务\n全流程采购执行\n制定年度/季度采购计划，基于历史数据（库存周转率、冻损率） 和市场预判（如澳洲干旱预警） 动态调整。\n执行从寻源、比价、合同谈判到订单跟踪的全链路操作，确保月度采购量达标率≥95% 。\n成本精细化管理\n通过期货套保、季节性价差采购 等手段，实现全年综合采购成本低于市场均价3%-5% 。\n优化物流方案（如海运整柜VS拼箱），控制冷链成本占比≤总采购额15% 。\n二、供应商全生命周期管理\n管理阶段\n具体职责\n考核指标\n准入审核\n实地审计屠宰厂资质（如BRC认证）、清真合规性（Halal证书）\t\n新增供应商合格率100%\n绩效评估\n按季度评估交付准时率、质量事故率（如冰衣超标次数）\t\n供应商淘汰率≥5%/年\n风险备份\n建立替代供应商名单（如南美草饲牛肉替代澳洲谷饲）\t\n核心品类备用渠道≥2家\n三、质量与合规风控\n质量管控\n制定冻品验收企业标准 （冰衣厚度≤净重15%、解冻失水率≤8%），主导到货质检。\n每季度送检第三方实验室（检测瘦肉精、微生物指标），确保质检不合格批次≤0.5% 。\n合规管理\n跟踪进口政策变化（如CIQ新增检疫要求），100%确保单证合规 （卫生证书、核酸检测报告）。\n建立溯源系统 ，实现从牧场到仓库的批次追踪（如区块链技术应用）。\n四、跨部门协同增效\n协作部门\n协同任务\n输出成果\n仓储物流\n制定-18℃冷链SOP，减少冻损\t\n冻损率从1.2%降至0.8%\n生产研发\n根据部位肉特性（如牛腱VS牛腩）优化分割方案\t\n原料利用率提升10%\n销售计划\n提供价格趋势预警，支持促销备货\t\n滞销库存占比≤5%\n五、数据驱动决策\n行情分析\n每周输出全球牛羊肉价格波动简报 （结合USDA报告、主要产区天气/疫情）。\n采购模型迭代\n基于历史数据建立采购成本敏感度模型 （如汇率波动±5%对成本影响）。","requirements":"供应链管理\n精通冷冻肉品供应链各环节（源头牧场/屠宰厂→冷链运输→仓储管理→分销）。\n能优化采购成本结构（如减少冻损率、控制库存周转周期\u003c30天）。\n品质把控\n熟练掌握牛羊肉分级标准 （如澳洲MSA、USDA Prime/Choice）、解冻损失率检测、微生物指标检验。\n能通过眼观/触感 快速判断冻品质量（色泽、冰晶量、复温后弹性）。\n成本控制\n擅长利用工具对冲价格波动风险 ，建立动态采购模型（如季节性价差策略）。\n具备大宗合同谈判能力（年采购量千吨级以上）。\n合规与风控\n熟悉进口冻品检疫流程 （CIQ证书、核酸检测要求）、清真认证（Halal）、溯源系统建设。\n供应商审计能力（如查验牧场动物福利标准、屠宰厂注册号）。\n6. 自驱力强，具有较好的学习能力，愿意主动思考AI如何进一步优化工作流程。\n掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n一、核心采购业务\n全流程采购执行\n制定年度/季度采购计划，基于历史数据（库存周转率、冻损率） 和市场预判（如澳洲干旱预警） 动态调整。\n执行从寻源、比价、合同谈判到订单跟踪的全链路操作，确保月度采购量达标率≥95% 。\n成本精细化管理\n通过期货套保、季节性价差采购 等手段，实现全年综合采购成本低于市场均价3%-5% 。\n优化物流方案（如海运整柜VS拼箱），控制冷链成本占比≤总采购额15% 。\n二、供应商全生命周期管理\n管理阶段\n具体职责\n考核指标\n准入审核\n实地审计屠宰厂资质（如BRC认证）、清真合规性（Halal证书）\t\n新增供应商合格率100%\n绩效评估\n按季度评估交付准时率、质量事故率（如冰衣超标次数）\t\n供应商淘汰率≥5%/年\n风险备份\n建立替代供应商名单（如南美草饲牛肉替代澳洲谷饲）\t\n核心品类备用渠道≥2家\n三、质量与合规风控\n质量管控\n制定冻品验收企业标准 （冰衣厚度≤净重15%、解冻失水率≤8%），主导到货质检。\n每季度送检第三方实验室（检测瘦肉精、微生物指标），确保质检不合格批次≤0.5% 。\n合规管理\n跟踪进口政策变化（如CIQ新增检疫要求），100%确保单证合规 （卫生证书、核酸检测报告）。\n建立溯源系统 ，实现从牧场到仓库的批次追踪（如区块链技术应用）。\n四、跨部门协同增效\n协作部门\n协同任务\n输出成果\n仓储物流\n制定-18℃冷链SOP，减少冻损\t\n冻损率从1.2%降至0.8%\n生产研发\n根据部位肉特性（如牛腱VS牛腩）优化分割方案\t\n原料利用率提升10%\n销售计划\n提供价格趋势预警，支持促销备货\t\n滞销库存占比≤5%\n五、数据驱动决策\n行情分析\n每周输出全球牛羊肉价格波动简报 （结合USDA报告、主要产区天气/疫情）。\n采购模型迭代\n基于历史数据建立采购成本敏感度模型 （如汇率波动±5%对成本影响）。\n\n岗位基本要求\n供应链管理\n精通冷冻肉品供应链各环节（源头牧场/屠宰厂→冷链运输→仓储管理→分销）。\n能优化采购成本结构（如减少冻损率、控制库存周转周期\u003c30天）。\n品质把控\n熟练掌握牛羊肉分级标准 （如澳洲MSA、USDA Prime/Choice）、解冻损失率检测、微生物指标检验。\n能通过眼观/触感 快速判断冻品质量（色泽、冰晶量、复温后弹性）。\n成本控制\n擅长利用工具对冲价格波动风险 ，建立动态采购模型（如季节性价差策略）。\n具备大宗合同谈判能力（年采购量千吨级以上）。\n合规与风控\n熟悉进口冻品检疫流程 （CIQ证书、核酸检测要求）、清真认证（Halal）、溯源系统建设。\n供应商审计能力（如查验牧场动物福利标准、屠宰厂注册号）。\n6. 自驱力强，具有较好的学习能力，愿意主动思考AI如何进一步优化工作流程。\n掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n知名贸易公司牛肉采买经验、资深工厂加工经验、Minerva、JBS等驻华公司销运业务负责人\n\n岗位亮点\n垂类细分市场，品类高阶采购专家，参与品类未来发展和规划","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4150274305","sourceKey":"meituan_social","company":"美团","title":"数据架构-数据湖与数据集成后端开发","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4150274305&jobShareType=1","duty":"1. 构建实时/离线数据采集与同步解决方案，支持跨数据库、数据仓库、数据湖的数据交互。优化数据传输性能，解决高并发、大数据量场景下的延迟与容错问题。设计数据一致性保障机制，处理数据冲突、断点续传、幂等性等核心问题，确保端到端数据质量。 \n2. 持续迭代数据集成解决方案的架构设计，支持容灾、出海等业务场景；优化架构设计，持续降低成本。\n3. 研究前沿技术（如CDC、流批一体架构），推动数据同步技术在业务场景中的创新应用。 \n4. 构建高性能、高可用性数据湖引擎，参与美团数据湖引擎从0到1的落地与业务推广工作，持续提升系统性能和稳定性，降低成本。 \n5. 驱动数据湖的周边生态建设，包括实时/离线计算引擎，查询引擎，产品开发平台等生态，助力业务基于数据湖的解决方案落地。 \n6. 探索AI驱动的智能数据映射能力，基于大模型理解源表schema自动生成目标表映射规则，将数据集成配置从人工逐字段编排简化为AI辅助一键生成。","requirements":"1. 计算机相关专业本科及以上学历，2年以上数据集成与同步/大数据计算、存储引擎开发或数据湖相关工作经验。 \n2. 熟悉Java/C++编程语言，能够独立进行系统和工具开发。 \n3. 熟悉主流的大数据数据集成引擎和数据湖引擎，如Canal、DataX、Spark、Flink、Paimon等。 \n4. 熟悉分布式系统和大规模数据处理的设计和实现，具备高并发、高性能系统开发经验。 \n5. 具备良好沟通能力和问题解决能力，能够高效与系统上下游、业务方沟通协作。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 构建实时/离线数据采集与同步解决方案，支持跨数据库、数据仓库、数据湖的数据交互。优化数据传输性能，解决高并发、大数据量场景下的延迟与容错问题。设计数据一致性保障机制，处理数据冲突、断点续传、幂等性等核心问题，确保端到端数据质量。 \n2. 持续迭代数据集成解决方案的架构设计，支持容灾、出海等业务场景；优化架构设计，持续降低成本。\n3. 研究前沿技术（如CDC、流批一体架构），推动数据同步技术在业务场景中的创新应用。 \n4. 构建高性能、高可用性数据湖引擎，参与美团数据湖引擎从0到1的落地与业务推广工作，持续提升系统性能和稳定性，降低成本。 \n5. 驱动数据湖的周边生态建设，包括实时/离线计算引擎，查询引擎，产品开发平台等生态，助力业务基于数据湖的解决方案落地。 \n6. 探索AI驱动的智能数据映射能力，基于大模型理解源表schema自动生成目标表映射规则，将数据集成配置从人工逐字段编排简化为AI辅助一键生成。\n\n岗位基本要求\n1. 计算机相关专业本科及以上学历，2年以上数据集成与同步/大数据计算、存储引擎开发或数据湖相关工作经验。 \n2. 熟悉Java/C++编程语言，能够独立进行系统和工具开发。 \n3. 熟悉主流的大数据数据集成引擎和数据湖引擎，如Canal、DataX、Spark、Flink、Paimon等。 \n4. 熟悉分布式系统和大规模数据处理的设计和实现，具备高并发、高性能系统开发经验。 \n5. 具备良好沟通能力和问题解决能力，能够高效与系统上下游、业务方沟通协作。\n\n具备以下条件优先\n1. 具备数据集成和同步引擎开发经验者优先，如SLS、Canal、DataX等 。\n2. 具备数据湖开发经验者优先，如Hudi、Iceberg、Paimon等 。\n3. 具备Flink、Spark、Presto等引擎开发经验者优先 。\n4. 具备分布式计算和存储优化经验者优先。\n\n岗位亮点\n1. 负责美团数据同步解决方案的建设，推进流批一体在数据同步领域的持续优化。 \n2. 参与美团数据湖引擎从0到1的落地。 \n3. 能够接触到丰富的业务场景，包括但不限于数据开发、机器学习等，助力业务数据集成与数据湖解决方案的落地。 \n4. 提供良好的职业发展空间，参与解决复杂的技术问题，不断学习和成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:1692133223","sourceKey":"meituan_social","company":"美团","title":"乐生活东部战区-产品销售","city":"上海市/杭州市/苏州市/潍坊市/无锡市/扬州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=1692133223&jobShareType=1","duty":"1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","requirements":"1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生。\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位基本要求\n1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生。\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n有机会学习并掌握互联网本地生活的工作方式","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3488667871","sourceKey":"meituan_social","company":"美团","title":"充电宝大客户销售——酒店/便利店连锁方向","city":"上海市/广州市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3488667871&jobShareType=1","duty":"1.负责推进区域KA品牌与美团充电宝的商务合作，包括客户触达、提案制定、数据测算、合同签约、项目运维等；\n2.负责KA项目运营，定期组织品牌方进行项目沟通，输出项目经营分析，提高项目产出；\n3.负责公司内部跨部门协同沟通，协同销运、直营、产品、硬件等部门，为品牌方提供整体全案解决方案；\n4.保持良好的客户关系，做好KA客户管理和维护工作。","requirements":"1.本科及以上学历优先，五年及以上的销售经验优先，有良好销售业绩优先，有KA销售经验者优先；\n2.有很强的学习能力和适应能力，适应互联网行业的快速发展节奏，具备出色完成任务的能力；\n3.具备较强的公关能力及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成商务合作；\n4.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.负责推进区域KA品牌与美团充电宝的商务合作，包括客户触达、提案制定、数据测算、合同签约、项目运维等；\n2.负责KA项目运营，定期组织品牌方进行项目沟通，输出项目经营分析，提高项目产出；\n3.负责公司内部跨部门协同沟通，协同销运、直营、产品、硬件等部门，为品牌方提供整体全案解决方案；\n4.保持良好的客户关系，做好KA客户管理和维护工作。\n\n岗位基本要求\n1.本科及以上学历优先，五年及以上的销售经验优先，有良好销售业绩优先，有KA销售经验者优先；\n2.有很强的学习能力和适应能力，适应互联网行业的快速发展节奏，具备出色完成任务的能力；\n3.具备较强的公关能力及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成商务合作；\n4.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心。\n\n具备以下条件优先\n1、有大客户销售的工作经历\n2、旅游相关经验\n\n岗位亮点\n1.大而稳定的平台发展，业务发展前景广阔；\n2.健全的培养体系，晋升通道完善；\n3.团队专业性强，产品竞争力强。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3977539617","sourceKey":"meituan_social","company":"美团","title":"收单业务_线上运营经理","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3977539617&jobShareType=1","duty":"1.负责承接新签合作商，为合作商赋能，指导协助合作商开展业务，充分激发合作商业务的持续增长。\n2.及时发现合作中的困难点并进行提炼，创造相应的解决方案，跟进问题的优化。\n3.准确传达公司政策及市场活动等信息，引导合作商市场的正向发展，保持顺畅的合作关系。\n4.带领指导合作商持扩大经营体量，引导合作商持续产生产品复购。与合作商相互配合共同完成公司下达的业绩指标。\n5.负责处理合作商作业过程日常业务常见问题解答，解决合作商日常问题。","requirements":"1.大专及以上学历，3年以上工作经验，2年以上渠道开发及管理经验，有互联网渠道销售经验者优先考虑。\n2.沟通能力强，擅长商务谈判，有基础的数据分析能力和总结能力。\n3.具备较强的合作商管理能力，有团队协作精神和较强的服务意识。\n4.能够承受压力和挑战。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1.负责承接新签合作商，为合作商赋能，指导协助合作商开展业务，充分激发合作商业务的持续增长。\n2.及时发现合作中的困难点并进行提炼，创造相应的解决方案，跟进问题的优化。\n3.准确传达公司政策及市场活动等信息，引导合作商市场的正向发展，保持顺畅的合作关系。\n4.带领指导合作商持扩大经营体量，引导合作商持续产生产品复购。与合作商相互配合共同完成公司下达的业绩指标。\n5.负责处理合作商作业过程日常业务常见问题解答，解决合作商日常问题。\n\n岗位基本要求\n1.大专及以上学历，3年以上工作经验，2年以上渠道开发及管理经验，有互联网渠道销售经验者优先考虑。\n2.沟通能力强，擅长商务谈判，有基础的数据分析能力和总结能力。\n3.具备较强的合作商管理能力，有团队协作精神和较强的服务意识。\n4.能够承受压力和挑战。\n\n具备以下条件优先\n支付行业优先，商管、商运营人才优先\n\n岗位亮点\n1.数据分析能力:可通过属地内竞争态势及合作商的关键数据指标快速分析出市场情况并落地适合的作战策略。\n2.具备经营能力：对合作商的团队管理、盈亏状况等方面能给出指导建议，并能在业务运营层面给出有效的落地解决方案。\n3·有团队管理经验，能协助合作商做团队搭建，人员架构建立","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4116170514","sourceKey":"meituan_social","company":"美团","title":"美团骑行-运营主管（济南）","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4116170514&jobShareType=1","duty":"1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2.通过实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4.配合政府部门对城市运营问题进行管理；\n5.协助运营经理管理运营团队，提升团队工作效率和结果；\n6.进行山东省骑行空白市场开拓。","requirements":"1.本科及以上学历，1-3以上团队管理经验，善于用开拓性思维解决问题；\n2.有快消品区域覆盖或互联网城市地推管理经验者优先；\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2.通过实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4.配合政府部门对城市运营问题进行管理；\n5.协助运营经理管理运营团队，提升团队工作效率和结果；\n6.进行山东省骑行空白市场开拓。\n\n岗位基本要求\n1.本科及以上学历，1-3以上团队管理经验，善于用开拓性思维解决问题；\n2.有快消品区域覆盖或互联网城市地推管理经验者优先；\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作。\n\n具备以下条件优先\n有出行行业、互联网行业相关工作经验的同学优先考虑；\n有拓展开城经验的同学优先考虑。\n\n岗位亮点\n美团单车是美团出行板块重要的组成部份，我们有清晰完善的晋升机制和通道，开放扁平的工作氛围。期待你的加入，与优秀的人共事，一起见证美团单车的重要时刻。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4016269129","sourceKey":"meituan_social","company":"美团","title":"药企商务BD","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4016269129&jobShareType=1","duty":"1.\t制定药企客户开发战略,搭建头部药企客户沟通机制，理解头部客户需求， 并提供解决方案，能够深度维护头部药企大客户，保持和药企客户不同参与KP的良好互动，\n2.\t统筹美团买药站内资源， 以及站外渠道，构建OTC/处方药企的营销解决方案，争取更多的合作可能性并能够落地\n3.\t负责团队销售漏斗管理，包括KP建立、看清、策略及竞标、中标等\n4.\t调研并掌握行业前沿趋势， 并识别机会，跟踪政策法规,整合生态资源\n5.\t负责整合跨部门资源、公司内外部资源，结合主营业务目标实现数字化营销团队目标达成","requirements":"1. 大学本科及以上学历，医药、生物、市场营销等相关专业优先。  \n2. 6年以上药企商务拓展或大客户销售经验，熟悉医药行业生态。  \n3. 具备优秀的谈判能力和客户管理能力，有成功项目案例。  \n4. 熟悉医药行业政策法规及市场动态。  \n5. 能适应高频出差，工作地点为北京或上海。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.\t制定药企客户开发战略,搭建头部药企客户沟通机制，理解头部客户需求， 并提供解决方案，能够深度维护头部药企大客户，保持和药企客户不同参与KP的良好互动，\n2.\t统筹美团买药站内资源， 以及站外渠道，构建OTC/处方药企的营销解决方案，争取更多的合作可能性并能够落地\n3.\t负责团队销售漏斗管理，包括KP建立、看清、策略及竞标、中标等\n4.\t调研并掌握行业前沿趋势， 并识别机会，跟踪政策法规,整合生态资源\n5.\t负责整合跨部门资源、公司内外部资源，结合主营业务目标实现数字化营销团队目标达成\n\n岗位基本要求\n1. 大学本科及以上学历，医药、生物、市场营销等相关专业优先。  \n2. 6年以上药企商务拓展或大客户销售经验，熟悉医药行业生态。  \n3. 具备优秀的谈判能力和客户管理能力，有成功项目案例。  \n4. 熟悉医药行业政策法规及市场动态。  \n5. 能适应高频出差，工作地点为北京或上海。\n\n岗位亮点\n1. 参与高价值药企合作项目，快速积累行业资源。  \n2. 与头部药企及创新药公司直接对接，提升专业能力。  \n3. 扁平化管理，灵活的工作氛围和成长空间。  \n4. 提供有竞争力的薪酬和绩效激励。  \n5. 团队注重结果导向，支持个人职业发展","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4016023523","sourceKey":"meituan_social","company":"美团","title":"美团骑行-运营主管（义乌市、温州市）","city":"金华市/温州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4016023523&jobShareType=1","duty":"1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2.通过实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4.配合治理者对城市运营问题进行管理；\n5.协助运营经理管理运营团队，提升团队工作效率和结果。","requirements":"1.本科及以上学历，善于用开拓性思维解决问题；\n2.有快消品区域覆盖或互联网城市地推管理经验者优先；\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作。\n4.接受区域调配者优先。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2.通过实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4.配合治理者对城市运营问题进行管理；\n5.协助运营经理管理运营团队，提升团队工作效率和结果。\n\n岗位基本要求\n1.本科及以上学历，善于用开拓性思维解决问题；\n2.有快消品区域覆盖或互联网城市地推管理经验者优先；\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作。\n4.接受区域调配者优先。\n\n岗位亮点\n综合管理人才培养平台；清晰的职业晋升路径；福利好，氛围佳","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3965921953","sourceKey":"meituan_social","company":"美团","title":"酒店PMS渠道销售经理","city":"北京市/上海市/广州市/深圳市/南京市/武汉市/西安市/成都市/长沙市/重庆市/杭州市/昆明市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3965921953&jobShareType=1","duty":"1. 负责酒店PMS系统在指定区的代理商渠道拓展工作。  \n2. 与代理商建立并维护长期合作关系，完成销售目标。  \n3. 分析市场动态和客户需求，制定并执行有效的销售策略。  \n4. 协调内部资源，推动项目落地及客户成功。  \n5. 定期汇报销售进展，优化销售流程。","requirements":"1. 大学专科及以上学历。  \n2. 具备至少3年以上酒店相关行业销售或渠道代理商开发经验。  \n3. 熟悉酒店PMS系统或相关行业知识。  \n4. 具备良好的沟通能力和拿结果能力。  \n5. 能适应高频出差，工作地点为长沙、北京、上海、广州、西安、杭州、成都等。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责酒店PMS系统在指定区的代理商渠道拓展工作。  \n2. 与代理商建立并维护长期合作关系，完成销售目标。  \n3. 分析市场动态和客户需求，制定并执行有效的销售策略。  \n4. 协调内部资源，推动项目落地及客户成功。  \n5. 定期汇报销售进展，优化销售流程。\n\n岗位基本要求\n1. 大学专科及以上学历。  \n2. 具备至少3年以上酒店相关行业销售或渠道代理商开发经验。  \n3. 熟悉酒店PMS系统或相关行业知识。  \n4. 具备良好的沟通能力和拿结果能力。  \n5. 能适应高频出差，工作地点为长沙、北京、上海、广州、西安、杭州、成都等。\n\n具备以下条件优先\n酒店PMS相关销售从业经验，酒店供应链渠道销售想相关从业经验，软件渠道销售相关从业经验\n\n岗位亮点\n1. 加入快速发展的酒店科技行业，接触前沿数字化解决方案。  \n2. 提供系统的销售培训和职业发展通道。  \n3. 弹性工作制，注重结果导向。  \n4. 团队氛围开放，鼓励创新和协作。  \n5. 薪资结构包含高比例绩效奖金，激励性强。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3369571502","sourceKey":"meituan_social","company":"美团","title":"众包站长","city":"北京市/广州市/深圳市/西安市/天津市/长春市/大连市/南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3369571502&jobShareType=1","duty":"1.对负责区域制定配送体验优化方案并有效地执行方案，同时对执行结果进行有效复盘；​2.重点围绕骑手的招聘，培训，提效，留存，淘汰等环节开展工作，保证负责区域的运力活力以及提升履约服务质量，提升用户体验；​3.处理由履约原因产生的相关商户问题，以及能够良好地协同其他部门进行问题解决；​4.对负责的骑手运营项目，能够做出短、中、长期的规划，制定高效的运营方案并达成业务结果。","requirements":"1.本科及以上学历，有物流、互联网、O2O等相关行业或运营经验者优先；​2.熟练运用互联网常见分析工具，掌握物流数据分析方法论；​3.业务灵敏度强，能从数据运营中发现问题，并提出解决路径；​4.有较强的自驱与学习能力，有长远职业发展的规划。","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n1.对负责区域制定配送体验优化方案并有效地执行方案，同时对执行结果进行有效复盘；​2.重点围绕骑手的招聘，培训，提效，留存，淘汰等环节开展工作，保证负责区域的运力活力以及提升履约服务质量，提升用户体验；​3.处理由履约原因产生的相关商户问题，以及能够良好地协同其他部门进行问题解决；​4.对负责的骑手运营项目，能够做出短、中、长期的规划，制定高效的运营方案并达成业务结果。\n\n岗位基本要求\n1.本科及以上学历，有物流、互联网、O2O等相关行业或运营经验者优先；​2.熟练运用互联网常见分析工具，掌握物流数据分析方法论；​3.业务灵敏度强，能从数据运营中发现问题，并提出解决路径；​4.有较强的自驱与学习能力，有长远职业发展的规划。\n\n具备以下条件优先\n1.具有2年及以上物流运营经验者优先；​2.具有运营项目管理经验者优先；​3.对物流行业有强烈兴趣，有韧性有规划。\n\n岗位亮点\n1.能够参与并推动履约运营体系完善与搭建；​2.可参与到跨部门重点项目协调推进；​3.可与优秀物流运营者共同成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3955189960","sourceKey":"meituan_social","company":"美团","title":"充电宝渠道经理-桂海区域","city":"海口市/三亚市/南宁市/柳州市/桂林市/钦州市/北海市/贵港市/防城港市/儋州市/陵水黎族自治县/万宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3955189960&jobShareType=1","duty":"1.负责制定充电宝渠道拓展计划，完成市场渠道开发目标；\n2.负责渠道资源整合和招商，建立并维护与合作伙伴的良好关系；\n3.负责渠道管理和维护，确保渠道销售目标的实现；\n4.负责监控渠道销售情况，及时调整策略，提高销售绩效。\n5.有充电宝合作商开发和运营维护的经验和资源；","requirements":"1.大学专科以上学历，具有3年以上业务开发/渠道管理经验；\n2.具备良好的沟通能力和团队合作精神；\n3.具备较强的市场洞察力和谈判能力，有成功的渠道管理案例者优先考虑；\n4.具备渠道资源和渠道管理经验者优先。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.负责制定充电宝渠道拓展计划，完成市场渠道开发目标；\n2.负责渠道资源整合和招商，建立并维护与合作伙伴的良好关系；\n3.负责渠道管理和维护，确保渠道销售目标的实现；\n4.负责监控渠道销售情况，及时调整策略，提高销售绩效。\n5.有充电宝合作商开发和运营维护的经验和资源；\n\n岗位基本要求\n1.大学专科以上学历，具有3年以上业务开发/渠道管理经验；\n2.具备良好的沟通能力和团队合作精神；\n3.具备较强的市场洞察力和谈判能力，有成功的渠道管理案例者优先考虑；\n4.具备渠道资源和渠道管理经验者优先。\n\n具备以下条件优先\n代理商渠道开拓资源丰富且有渠道管理经验者优先\n\n岗位亮点\n区域市场增长空间大，薪资福利优厚，发展空间大；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4147419257","sourceKey":"meituan_social","company":"美团","title":"数据AI应用方向技术专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4147419257&jobShareType=1","duty":"1、Data+AI方向整体的应用对接与架构设计：负责数据方向AI应用的架构设计与应用对接，主导取数、数据分析、经营分析或BI+AI结合等子方向，实现从需求对齐到工程落地的闭环。  \n2、Data+AI方向基建能力：于大语言模型（LLM）构建高性能智能体（Agent）架构，设计并实现意图识别、任务规划引擎、对话状态管理及多Agent协作网络等核心模块，优化动态工具调用、长短时记忆管理及异常自愈等高级功能。\n3、BI系统的AI能力升级：基于AI的技术能力和判断深度改造当前的BI系统，包括探索AI-Native的产品形态以及基于BI+AI的思路提升当前BI系统的智能化水平，为用户的取数&分析等能力全方位的提效。","requirements":"1、技术愿景：热爱与信仰AI技术，相信AI能够全方位的改变世界。\n2、技术背景：兼具AI的技术判断与Data的落地经验，深度研究过Claude、GPT、Gemini等主流模型及其生态产品，能够将前沿理论转化为适配数据AI场景的工程实践。\n3、领域要求：熟悉或者愿意学习数据研发、数据分析的基础工作，了解数据领域相关的角色性质与工作特点，在跨角色、跨团队合作过程中具备较强的协同能力。\n4、软性素质：具备良好的自我学习能力、自驱力，共享知识和经验促进团队的技术进步和个人成长，能够适应快节奏的工作环境","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、Data+AI方向整体的应用对接与架构设计：负责数据方向AI应用的架构设计与应用对接，主导取数、数据分析、经营分析或BI+AI结合等子方向，实现从需求对齐到工程落地的闭环。  \n2、Data+AI方向基建能力：于大语言模型（LLM）构建高性能智能体（Agent）架构，设计并实现意图识别、任务规划引擎、对话状态管理及多Agent协作网络等核心模块，优化动态工具调用、长短时记忆管理及异常自愈等高级功能。\n3、BI系统的AI能力升级：基于AI的技术能力和判断深度改造当前的BI系统，包括探索AI-Native的产品形态以及基于BI+AI的思路提升当前BI系统的智能化水平，为用户的取数&分析等能力全方位的提效。\n\n岗位基本要求\n1、技术愿景：热爱与信仰AI技术，相信AI能够全方位的改变世界。\n2、技术背景：兼具AI的技术判断与Data的落地经验，深度研究过Claude、GPT、Gemini等主流模型及其生态产品，能够将前沿理论转化为适配数据AI场景的工程实践。\n3、领域要求：熟悉或者愿意学习数据研发、数据分析的基础工作，了解数据领域相关的角色性质与工作特点，在跨角色、跨团队合作过程中具备较强的协同能力。\n4、软性素质：具备良好的自我学习能力、自驱力，共享知识和经验促进团队的技术进步和个人成长，能够适应快节奏的工作环境\n\n具备以下条件优先\n1、曾主导大模型应用开发的实际项目，具备构建和优化RAG系统的丰富经验，相关模型微调和训练的实战经验优先。\n2、有Data Agent实际落经验地加分。\n3、有AI项目经验的算法工程&数据工程方向优先。\n\n岗位亮点\n1. 深度参与前沿AI Agent技术落地，主导核心模块设计与业务场景创新。  \n2. 团队技术驱动，定期组织AI技术研讨与行业趋势分享。  \n3. 与基座模型算法团队协同，接触企业级复杂业务场景与海量数据。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4088100455","sourceKey":"meituan_social","company":"美团","title":"民营医疗CKA销售","city":"北京市/天津市/上海市/南京市/杭州市/武汉市/广州市/深圳市/重庆市/西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4088100455&jobShareType=1","duty":"【岗位职责】\n1、负责美团线上民营医疗机构品牌的商务合作拓展；\n2、全方位的进行服务品牌跟进与沟通；深挖客户需求，提供广告、在线交易等全案营销策略方案；\n3、分析客户需求，制定落地执行方案；\n4、跨部门协作，完成售前准备、提案、上线及总结回顾；\n5、深化客户关系，与公司各部门配合，及时处理客户的反馈、投诉和建议，提高客户满意度。","requirements":"【岗位基本要求】\n1、大学本科及以上学历；\n2、3年以上销售及大客户维护经验，具备一定的医疗行业资源积累，有头部客户资源者优先；\n3、对互联网产品、消费者心态、竞争对手在内的市场营销策略和广告策略、媒介策略有一定的了解；适应互联网行业的快速发展，具备出色完成任务的能力；\n4、具备较强的人际沟通能力及逻辑思维能力；\n5、为人正直，诚实可靠，以公司利益为重；\n6、热爱销售，善于挑战，积极乐观，有强烈的成功欲望。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n【岗位职责】\n1、负责美团线上民营医疗机构品牌的商务合作拓展；\n2、全方位的进行服务品牌跟进与沟通；深挖客户需求，提供广告、在线交易等全案营销策略方案；\n3、分析客户需求，制定落地执行方案；\n4、跨部门协作，完成售前准备、提案、上线及总结回顾；\n5、深化客户关系，与公司各部门配合，及时处理客户的反馈、投诉和建议，提高客户满意度。\n\n岗位基本要求\n【岗位基本要求】\n1、大学本科及以上学历；\n2、3年以上销售及大客户维护经验，具备一定的医疗行业资源积累，有头部客户资源者优先；\n3、对互联网产品、消费者心态、竞争对手在内的市场营销策略和广告策略、媒介策略有一定的了解；适应互联网行业的快速发展，具备出色完成任务的能力；\n4、具备较强的人际沟通能力及逻辑思维能力；\n5、为人正直，诚实可靠，以公司利益为重；\n6、热爱销售，善于挑战，积极乐观，有强烈的成功欲望。\n\n岗位亮点\n1，对接医疗城市头部品牌机构，有更大的医疗资源\n2，管理发展空间大","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4130924921","sourceKey":"meituan_social","company":"美团","title":"供给及权益运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4130924921&jobShareType=1","duty":"1、体系化设计权益供给库并持续迭代效率，为不同等级用户制定适配权益组，并持续优化权益对用户的成长牵引效率，提升权益转化率；\n2、整合部门内外的各类商户供给资源与平台激励资源，形成多样化权益，并制定高效率的补贴策略；\n3、与业务深度合作，建立业务线目标效果共享协同机制，深度洞察并综合提升商户、用户、平台、行业部门的共赢空间；\n4、策划定向人群加码场景、升级场景的特色权益，构建等级跃迁节点的权益激励机制，提升用户升级动力与体系粘性；\n5、引入AI用户画像等智能工具辅助决策，提升资源流转与价值分配的最优解，支撑用户侧从上游投承到端内成长的全周期价值感覆盖。","requirements":"1、本科及以上学历，3年及以上用户运营、商家运营、权益供给运营相关经历，有AI相关产品/运营经验优先；\n2、了解用户增长、权益运营的底层逻辑，具备使用数据工具分析权益效果、辅助策略制定的能力，熟悉大模型等AI工具者优先且加分；\n3、对本地生活产品有一定的了解，能懂用户、懂业务；同时能制定招商白皮书，面向销售和商户开展宣导，协同多渠道扩大权益合作商户规模；\n4、具有较强的用户洞察能力、思考能力、沟通能力、跨团队沟通协调与项目推进能力，以及资源拓展、整合能力和数据分析能力；\n5、有较强自驱力，乐于探索新的智能化工具激发权益运营新价值。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、体系化设计权益供给库并持续迭代效率，为不同等级用户制定适配权益组，并持续优化权益对用户的成长牵引效率，提升权益转化率；\n2、整合部门内外的各类商户供给资源与平台激励资源，形成多样化权益，并制定高效率的补贴策略；\n3、与业务深度合作，建立业务线目标效果共享协同机制，深度洞察并综合提升商户、用户、平台、行业部门的共赢空间；\n4、策划定向人群加码场景、升级场景的特色权益，构建等级跃迁节点的权益激励机制，提升用户升级动力与体系粘性；\n5、引入AI用户画像等智能工具辅助决策，提升资源流转与价值分配的最优解，支撑用户侧从上游投承到端内成长的全周期价值感覆盖。\n\n岗位基本要求\n1、本科及以上学历，3年及以上用户运营、商家运营、权益供给运营相关经历，有AI相关产品/运营经验优先；\n2、了解用户增长、权益运营的底层逻辑，具备使用数据工具分析权益效果、辅助策略制定的能力，熟悉大模型等AI工具者优先且加分；\n3、对本地生活产品有一定的了解，能懂用户、懂业务；同时能制定招商白皮书，面向销售和商户开展宣导，协同多渠道扩大权益合作商户规模；\n4、具有较强的用户洞察能力、思考能力、沟通能力、跨团队沟通协调与项目推进能力，以及资源拓展、整合能力和数据分析能力；\n5、有较强自驱力，乐于探索新的智能化工具激发权益运营新价值。\n\n具备以下条件优先\n1、具备会员权益运营经验者优先；\n2、有通过资源整合带动业务目标增长的成功案例；\n3、熟悉用户画像、推荐系统等相关算法在运营场景应用者优先。\n\n岗位亮点\n1、行业TOP级产品： 覆盖上亿规模用户策略，有机会主导用户成长体系权益驱动引擎的系统性创新，成长空间巨大；\n2、深度参与AI落地： 面向美团广泛目标用户，直接参与AI基础数据、标签体系与画像算法建设，将AI画像、推荐算法实际应用到权益运营中，验证其对用户增长的撬动，而非停留在课题研究阶段；\n3、多维业务的经营逻辑进阶： 与美团各类业务团队深度合作，高速学习多业务的经营逻辑，同时有机会接触复杂问题，推动权益运营与资源分配的智能化、自动化升级；\n4、从0到100的操盘成长： 深度参与权益体系从0到1搭建和1到100的开枝散叶，完整经历供给拓展、权益配置、效果验证、规模放量的业务全周期，沉淀稀缺的从零操盘经验；\n5、贴近一线、工作不设限： 团队氛围好，你将贴近行业一线深度参与AI技术应用，成长资源丰富。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3684553494","sourceKey":"meituan_social","company":"美团","title":"下沉市场-渠道经理（辽吉区域）","city":"沈阳市/长春市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3684553494&jobShareType=1","duty":"岗位职责\n1.负责区域内目标合作商的挖掘和洽谈合作工作，并带领合作商完成美团外卖的业务目标；\n2.协助合作商组建和管理团队，辅导和监督合作商做好团队的管理工作；\n3.给合作商团队成员有效的培训和辅导；\n4.总结梳理合作商团队工作中的关键动作，使之流程标准化并落地执行；\n5.从外卖业务数据和配送数据中发现问题，持续优化合作商的业务和管理；\n6.从合作商的角度出发思考问题，保证合作商与美团外卖在资源互补、目标一致的方向健康发展；\n7.对合作商团队进行公平公正且有效的工作考核，对不符合考核标准的合作商进行坚决清退。","requirements":"1.有强大的自驱力，渴望成功；\n2.出色的人际沟通能力、团队协作精神与团队建设能力；\n3.能接受区域内长期出差；\n4.精力充沛，能出色完成任务；\n5.认同并有意愿去学习打造超强执行力的团队；\n6.为人力行正道，强烈认同以客户为中心、团队合作、拥抱变化、诚信、勤俭、敬业、学习成长的美团价值观。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n岗位职责\n1.负责区域内目标合作商的挖掘和洽谈合作工作，并带领合作商完成美团外卖的业务目标；\n2.协助合作商组建和管理团队，辅导和监督合作商做好团队的管理工作；\n3.给合作商团队成员有效的培训和辅导；\n4.总结梳理合作商团队工作中的关键动作，使之流程标准化并落地执行；\n5.从外卖业务数据和配送数据中发现问题，持续优化合作商的业务和管理；\n6.从合作商的角度出发思考问题，保证合作商与美团外卖在资源互补、目标一致的方向健康发展；\n7.对合作商团队进行公平公正且有效的工作考核，对不符合考核标准的合作商进行坚决清退。\n\n岗位基本要求\n1.有强大的自驱力，渴望成功；\n2.出色的人际沟通能力、团队协作精神与团队建设能力；\n3.能接受区域内长期出差；\n4.精力充沛，能出色完成任务；\n5.认同并有意愿去学习打造超强执行力的团队；\n6.为人力行正道，强烈认同以客户为中心、团队合作、拥抱变化、诚信、勤俭、敬业、学习成长的美团价值观。\n\n具备以下条件优先\n有众包、履约、零售、团购、外卖相关工作经验者，优先录取\n\n岗位亮点\n完善的晋升&考核机制，负责管理区域内外卖渠道业务的全闭环，良好的公司文化以及团队氛围，成长空间大 。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4081911664","sourceKey":"meituan_social","company":"美团","title":"电单车资管经理","city":"包头市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4081911664&jobShareType=1","duty":"1.负责所辖城市运营资源供给保障及仓库管理。\n2.执行落地相关管理要求及流程标准。\n3.对仓库进行现场管理，持续提升作业效率。\n4.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险。","requirements":"1.本科及以上学历（硬性要求），具有3年以上团队管理经验，有相关物流仓储工作经验优先。\n2.具有较强的人际交往能力和应变能力。\n3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力。\n4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所辖城市运营资源供给保障及仓库管理。\n2.执行落地相关管理要求及流程标准。\n3.对仓库进行现场管理，持续提升作业效率。\n4.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险。\n\n岗位基本要求\n1.本科及以上学历（硬性要求），具有3年以上团队管理经验，有相关物流仓储工作经验优先。\n2.具有较强的人际交往能力和应变能力。\n3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力。\n4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。\n\n岗位亮点\n带薪年假、定期体检、五险一金、发展空间大、个人能力提升快等。\n具备以下优先:\n同行业、快递、物流、仓储、重资产业务管理等行业经验者优先。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4129642807","sourceKey":"meituan_social","company":"美团","title":"Keeta Brazil CE Finance BP","city":"圣保罗/迪拜","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4129642807&jobShareType=1","duty":"1.Assist customer service platform business team(multi-country) on the whole financial process, formulate and optimize financial processes and rules, provide professional financial advice and promote implementation.\n2.Support financial matters for customer service business in new countries/cities launching, ensure smooth business-related financial processes, and control financial risks.\n3.Cooperate with professional financial teams such as accounting, tax, reporting, treasury, internal control, etc., to ensure all businesses comply with financial rules.\n4.Participate in the customer service platform's business plan developing, be responsible for the annual financial budget and rolling forecast, and establish budget management framework inside country's CE business and  conduct effective budget management together with the business team.\n6.Gain in-depth understanding of the business, work closely with business partners, establish an effective financial analysis system,  conduct in-depth analysis of business operations, providing valuable advice and measure on cost optimization.\n7.Participate in the construction of financial digitalization and put forward demands and suggestions from the perspective of analysis and monitoring.","requirements":"1.Bachelor's degree or above, background in corporate finance, accounting, finance or related majors.\n2.More than 5 years of experience in finance BP or related positions, familiar with multi-countries business.\n3.Have a strong curiosity and entrepreneurial spirit, and eager to learn new things. Able to quickly adapt to new environments and job responsibilities.\n4.Have good communication skills and team spirit, and can effectively coordinate and cooperate with different departments.\n5.Proficient in using financial software, office software and statistical analysis methods, with good data processing and analysis capabilities.\n6.Have a strong sense of responsibility and business sensitivity, think deeply, and possess skills in identifying and resolving issues.\n7.Able to use English as the working language, and open to travel to the multi-countries .","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1.Assist customer service platform business team(multi-country) on the whole financial process, formulate and optimize financial processes and rules, provide professional financial advice and promote implementation.\n2.Support financial matters for customer service business in new countries/cities launching, ensure smooth business-related financial processes, and control financial risks.\n3.Cooperate with professional financial teams such as accounting, tax, reporting, treasury, internal control, etc., to ensure all businesses comply with financial rules.\n4.Participate in the customer service platform's business plan developing, be responsible for the annual financial budget and rolling forecast, and establish budget management framework inside country's CE business and  conduct effective budget management together with the business team.\n6.Gain in-depth understanding of the business, work closely with business partners, establish an effective financial analysis system,  conduct in-depth analysis of business operations, providing valuable advice and measure on cost optimization.\n7.Participate in the construction of financial digitalization and put forward demands and suggestions from the perspective of analysis and monitoring.\n\n岗位基本要求\n1.Bachelor's degree or above, background in corporate finance, accounting, finance or related majors.\n2.More than 5 years of experience in finance BP or related positions, familiar with multi-countries business.\n3.Have a strong curiosity and entrepreneurial spirit, and eager to learn new things. Able to quickly adapt to new environments and job responsibilities.\n4.Have good communication skills and team spirit, and can effectively coordinate and cooperate with different departments.\n5.Proficient in using financial software, office software and statistical analysis methods, with good data processing and analysis capabilities.\n6.Have a strong sense of responsibility and business sensitivity, think deeply, and possess skills in identifying and resolving issues.\n7.Able to use English as the working language, and open to travel to the multi-countries .\n\n具备以下条件优先\n1.Have overseas financial management experience in multinational companies.\n2.Can use English and Portuguese as the working language.\n3.Have work experience in global on-demand/logistics/e-commerce platforms companies.\n\n岗位亮点\n1.Overseas business is developing rapidly, chance to grow together with our business.\n2.Deeply participate in business operations, get exposed to various financial modules, enhance comprehensive financial capabilities.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3951540545","sourceKey":"meituan_social","company":"美团","title":"资深内容推荐产品","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3951540545&jobShareType=1","duty":"1. 负责美团视频推荐策略体系构建，主导短视频推荐全链路策略设计，覆盖内容理解、用户画像、召回排序、多样性调控等核心模块\n2. 建立科学高效的实验评估体系与流量货币化策略，通过时长/留存/收入/交易转化等核心指标驱动策略迭代，搭建动态流量调控系统，平衡商业价值与用户体验\n3. 探索AI生成内容（AIGC）在推荐场景的应用，设计多元内容模式（视频、小说、游戏等）的推荐链路及模式\n4. 协同算法团队、内容团队优化内容供需框架的建设，为用户消费及流量增长负责","requirements":"1. 8年以上互联网产品经验，其中5年+短视频/内容推荐领域经验，主导过DAU千万级产品的推荐系统重构，有电商/泛娱乐行业经验优先 \n2. 精通推荐系统全链路设计（召回/排序/多样性/AB实验），熟悉主流算法框架，能解读算法逻辑。掌握SQL/Python数据分析，具备复杂数据建模能力\n3. 深度理解内容生态运营逻辑，有创作者流量生态建设经验，熟悉广告投放系统与LTV预测模型，了解多模态内容发展趋势，对生成式推荐有相关经验优先\n4. 优秀的跨部门协调能力（算法/工程/运营/商业化）强商业敏感度，能平衡用户体验与商业目标","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1. 负责美团视频推荐策略体系构建，主导短视频推荐全链路策略设计，覆盖内容理解、用户画像、召回排序、多样性调控等核心模块\n2. 建立科学高效的实验评估体系与流量货币化策略，通过时长/留存/收入/交易转化等核心指标驱动策略迭代，搭建动态流量调控系统，平衡商业价值与用户体验\n3. 探索AI生成内容（AIGC）在推荐场景的应用，设计多元内容模式（视频、小说、游戏等）的推荐链路及模式\n4. 协同算法团队、内容团队优化内容供需框架的建设，为用户消费及流量增长负责\n\n岗位基本要求\n1. 8年以上互联网产品经验，其中5年+短视频/内容推荐领域经验，主导过DAU千万级产品的推荐系统重构，有电商/泛娱乐行业经验优先 \n2. 精通推荐系统全链路设计（召回/排序/多样性/AB实验），熟悉主流算法框架，能解读算法逻辑。掌握SQL/Python数据分析，具备复杂数据建模能力\n3. 深度理解内容生态运营逻辑，有创作者流量生态建设经验，熟悉广告投放系统与LTV预测模型，了解多模态内容发展趋势，对生成式推荐有相关经验优先\n4. 优秀的跨部门协调能力（算法/工程/运营/商业化）强商业敏感度，能平衡用户体验与商业目标\n\n岗位亮点\n业务单元丰富不受限，可发挥空间大，鼓励创新性方向，有团队梯度建设预期","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2407942805","sourceKey":"meituan_social","company":"美团","title":"分布式存储研发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2407942805&jobShareType=1","duty":"美团分布式存储方向，承载了全公司数据仓库和机器学习的全部离线数据，为业务提供了高可用、高可靠、超大规模的大数据存储底座、元数据存储、表格存储和消息存储服务，工作职责包括但不限于：\n1. 持续提升大数据存储底座的性能、稳定性、可靠性，解决AI时代爆发的数据访问的性能和成本压力，为AI训练海量数据提供更好的元数据扩展性和数据性能\n2. 持续优化成本，提升数据全生命周期管理能力，解决AI时代数据规模爆炸性增长的资源需求\n3. 持续提升数据底座和元数据底座的可观测性、审计能力、安全能力以及周边工具链，增强在大数据和AI场景下的数据易用性和安全性","requirements":"1.熟悉 Spark、Presto、Hive、HBase 等主流大数据系统中一种或者几种的原理；\n2.精通C/C++或Java，精通网络编程，多线程、高并发编程；\n3.理解大型分布式存储系统工作原理，掌握生产环境中各种架构的元数据、数据的可用性、性能的分析方法","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n美团分布式存储方向，承载了全公司数据仓库和机器学习的全部离线数据，为业务提供了高可用、高可靠、超大规模的大数据存储底座、元数据存储、表格存储和消息存储服务，工作职责包括但不限于：\n1. 持续提升大数据存储底座的性能、稳定性、可靠性，解决AI时代爆发的数据访问的性能和成本压力，为AI训练海量数据提供更好的元数据扩展性和数据性能\n2. 持续优化成本，提升数据全生命周期管理能力，解决AI时代数据规模爆炸性增长的资源需求\n3. 持续提升数据底座和元数据底座的可观测性、审计能力、安全能力以及周边工具链，增强在大数据和AI场景下的数据易用性和安全性\n\n岗位基本要求\n1.熟悉 Spark、Presto、Hive、HBase 等主流大数据系统中一种或者几种的原理；\n2.精通C/C++或Java，精通网络编程，多线程、高并发编程；\n3.理解大型分布式存储系统工作原理，掌握生产环境中各种架构的元数据、数据的可用性、性能的分析方法\n\n具备以下条件优先\n熟悉常见分布式存储产品及其在大数据场景应用，包括但不限于HDFS、HBase、Ceph、CubeFS、JuiceFS、Lustre、Swift等优先；\n熟悉开源数据湖产品，诸如Apache Hudi, Apache Iceberg等优先\n熟悉分布式数据库开发经验者，如FoundationDB，TiDB，CockroachDB等优先\n理解AI训练场景对存储系统需求（大规模Checkpoint IO、数据Shuffle），有AI Infra存储优化经验优先\n\n岗位亮点\n1.超大节点规模和EB级数据规模，服务覆盖美团等多种领域业务，从数据规模、集群体量、业务复杂度多个维度提供了技术挑战和锻炼发展的机会；\n2.在数仓和机器学习等多种场景下，挑战性能极限；\n3.参与改变数据管理方式，在超大容量规模基础上实施落地分层数据管理；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3893377167","sourceKey":"meituan_social","company":"美团","title":"景点游玩业务部-用户运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3893377167&jobShareType=1","duty":"1、基于大模型辅助用户洞察工具，对门票业务用户行为数据进行分群分析，自动输出高价值用户画像，驱动货架运营策略优化。\n2、跨团队协作，需联动业务、产品、技术等多团队，确保有效策略高效落地执行。\n3、设计并落地AB测试，通过数据验证策略有效性，推动产品功能迭代和运营标准升级。\n4、主导运营复盘，抽象业务痛点，输出可量化的改进建议并推动跨团队落地。\n5、通过市场调研、分析和用户研究，挖掘行业趋势与增长机会，输出前瞻性运营规划。","requirements":"1、5年以上互联网平台运营经验，对电商商品与货架有一定理解，有OTA、电商交易平台或本地生活业务背景优先。\n2、擅长拆解复杂业务问题，抽象通用方法论并推动体系化建设。\n3、熟悉AB测试，具备通过数据定位核心问题能力。\n4、有使用AI工具或大模型辅助用户运营的经验，并能借助AI自动化输出用户行为分析结论。\n5、精通从需求洞察到策略设计、执行监控、效果复盘的完整闭环。\n6、跨团队沟通协作能力良好，能主导多角色项目并协调资源达成目标。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、基于大模型辅助用户洞察工具，对门票业务用户行为数据进行分群分析，自动输出高价值用户画像，驱动货架运营策略优化。\n2、跨团队协作，需联动业务、产品、技术等多团队，确保有效策略高效落地执行。\n3、设计并落地AB测试，通过数据验证策略有效性，推动产品功能迭代和运营标准升级。\n4、主导运营复盘，抽象业务痛点，输出可量化的改进建议并推动跨团队落地。\n5、通过市场调研、分析和用户研究，挖掘行业趋势与增长机会，输出前瞻性运营规划。\n\n岗位基本要求\n1、5年以上互联网平台运营经验，对电商商品与货架有一定理解，有OTA、电商交易平台或本地生活业务背景优先。\n2、擅长拆解复杂业务问题，抽象通用方法论并推动体系化建设。\n3、熟悉AB测试，具备通过数据定位核心问题能力。\n4、有使用AI工具或大模型辅助用户运营的经验，并能借助AI自动化输出用户行为分析结论。\n5、精通从需求洞察到策略设计、执行监控、效果复盘的完整闭环。\n6、跨团队沟通协作能力良好，能主导多角色项目并协调资源达成目标。\n\n具备以下条件优先\n有电商货架运营的经验优先\n\n岗位亮点\n1、在行业头部规模团队参与业务重点战略方向，有机会把你的想法付之行动，为行业和用户创造价值。\n2、作为核心岗位人员，参与定义复杂业务场景的策略体系建设，获得驱动业务增长的成就感和从思考到执行的全方位提升，快速提升个人能力和经验视野。\n3、团队氛围开放，团队求真务实，目标导向强，和各业务职能团队的无缝紧密合作，更丰富的信息输入、更聚焦的工作领域、更高效的沟通协作。\n4、所在团队先后获得：北京信息通信行业适老化及无障碍服务优秀案例、文旅部首批适老化示范案例、公司首届增长比赛第1名、到店“以客户为中心奖”、总经理特别奖等诸多奖项。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4020739699","sourceKey":"meituan_social","company":"美团","title":"餐饮品类运营-客户方向","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4020739699&jobShareType=1","duty":"1、负责餐饮品类客户运营策略的制定与高效落地，借助大模型辅助数据洞察和 AI 智能客户分层工具，基于品类特性、商户规模、生命周期等多维度深度分析，结合行业趋势与竞争格局，自动识别高潜力客群与增长机会点，设计可量化、可执行的策略方案，持续优化关键业务指标（如广告渗透率、ARPU、留存率等）。\n2、搭建并持续迭代科学、动态的客户分层运营体系，针对头部KA客户提供定制化、高价值的广告运营服务，利用 AI 辅助复盘工具自动生成投放效果诊断报告与预算规划建议，提升复盘效率与标准化水平；打造可复制的标杆案例，显著提升客户广告投放效果、满意度与长期合作意愿，驱动公司效果广告收入目标达成。\n3、主导广告产品在餐饮行业的场景化案例沉淀与包装，**借助 AI 工具（如大模型辅助文档生成、知识库自动整理）**系统提炼产品价值与成功方法论，赋能销售与BD团队；同时深入一线，通过 AI 辅助用户访谈分析工具批量归类客户反馈，精准识别体验痛点与功能缺口，高效协同产品、技术、算法等中台团队推动产品优化与能力升级。","requirements":"1、具备扎实的数据分析能力，熟练使用数据分析工具及 AI 辅助分析手段（如大模型自然语言问数、AI 智能归因分析工具），能独立完成从数据提取到业务洞察的全链路分析，并以数据驱动策略迭代与决策。\n2、对餐饮行业有深刻理解，熟悉连锁品牌、区域龙头、中小商户等不同客群的经营逻辑、营销诉求与决策链路，能借助 AI 工具批量生成客户画像与行业洞察报告，具备前瞻性行业洞察力，能预判品类演进方向并提前布局运营抓手。\n3、具备极强的跨部门协同与推动力，善于在产品、运营、销售、技术等多方角色间建立共识、整合资源、对齐目标；熟练使用 AI 辅助会议纪要生成、任务拆解等工具提升协同效率，同时拥有优秀的沟通表达与影响力，能向上汇报、向下赋能、横向协同。\n4、有韧性，面对激烈竞争、业绩压力或突发变化时，能快速调整策略、稳定团队、聚焦核心，始终以结果为导向推进工作。对 AI 工具保持持续学习热情，能主动探索新工具并应用于实际业务场景。","description":"部门介绍\n商业增值部是服务于美团核心本地商业客户的增值服务平台，覆盖餐饮、即时零售、医药、休闲娱乐、丽人医美、生活服务、酒旅度假等业务领域。我们致力于构建健康的本地商业生态，通过为平台客户和消费者提供符合其需求的多元、便捷、高效的商业产品和服务，帮助生态伙伴提高效率、优化经营、实现持续健康发展，推动本地商业数字化营销的发展，促进商业生态繁荣。作为本地商业的头部平台，我们为产品、运营、商务、技术、商业分析等领域人才提供广阔的发展空间。诚邀你加入美团商业增值团队，共筑本地商业的健康繁荣生态！\n\n岗位职责\n1、负责餐饮品类客户运营策略的制定与高效落地，借助大模型辅助数据洞察和 AI 智能客户分层工具，基于品类特性、商户规模、生命周期等多维度深度分析，结合行业趋势与竞争格局，自动识别高潜力客群与增长机会点，设计可量化、可执行的策略方案，持续优化关键业务指标（如广告渗透率、ARPU、留存率等）。\n2、搭建并持续迭代科学、动态的客户分层运营体系，针对头部KA客户提供定制化、高价值的广告运营服务，利用 AI 辅助复盘工具自动生成投放效果诊断报告与预算规划建议，提升复盘效率与标准化水平；打造可复制的标杆案例，显著提升客户广告投放效果、满意度与长期合作意愿，驱动公司效果广告收入目标达成。\n3、主导广告产品在餐饮行业的场景化案例沉淀与包装，**借助 AI 工具（如大模型辅助文档生成、知识库自动整理）**系统提炼产品价值与成功方法论，赋能销售与BD团队；同时深入一线，通过 AI 辅助用户访谈分析工具批量归类客户反馈，精准识别体验痛点与功能缺口，高效协同产品、技术、算法等中台团队推动产品优化与能力升级。\n\n岗位基本要求\n1、具备扎实的数据分析能力，熟练使用数据分析工具及 AI 辅助分析手段（如大模型自然语言问数、AI 智能归因分析工具），能独立完成从数据提取到业务洞察的全链路分析，并以数据驱动策略迭代与决策。\n2、对餐饮行业有深刻理解，熟悉连锁品牌、区域龙头、中小商户等不同客群的经营逻辑、营销诉求与决策链路，能借助 AI 工具批量生成客户画像与行业洞察报告，具备前瞻性行业洞察力，能预判品类演进方向并提前布局运营抓手。\n3、具备极强的跨部门协同与推动力，善于在产品、运营、销售、技术等多方角色间建立共识、整合资源、对齐目标；熟练使用 AI 辅助会议纪要生成、任务拆解等工具提升协同效率，同时拥有优秀的沟通表达与影响力，能向上汇报、向下赋能、横向协同。\n4、有韧性，面对激烈竞争、业绩压力或突发变化时，能快速调整策略、稳定团队、聚焦核心，始终以结果为导向推进工作。对 AI 工具保持持续学习热情，能主动探索新工具并应用于实际业务场景。\n\n岗位亮点\n成长空间大，五险一金，双休，工作氛围好，扁平化管理","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3376492114","sourceKey":"meituan_social","company":"美团","title":"视觉Agent大模型算法专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3376492114&jobShareType=1","duty":"1. 负责视觉Agent系统的全链路设计与开发，构建融合多模态感知、动态决策与自动化执行的视觉智能系统，推动复杂场景下的图文多模态/视频理解、交互与生成能力。\n\n2. 负责视觉Agent核心算法的研发与优化，包括但不限于多模态大模型视觉感知、图像生成、多模态对齐（如文本-图像-视频）等方向，持续提升系统的鲁棒性与泛化能力。\n\n3. 研发视觉Agent的协作机制，支持多智能体协同任务（如跨模态推理、工具调用），优化模型在实时性、资源效率及长上下文处理中的表现。\n\n4. 研发大模型在业务场景下关键能力的应用研发，包括但不限于知识和指令遵循、分析诊断、深度推理、反思和评估等能力的优化和落地。\n\n5. 结合业务场景设计并落地视觉Agent应用，赋能业务智能化升级。\n\n6. 跟踪计算机视觉与大模型交叉领域的前沿技术，探索创新技术在实际场景中的落地路径。","requirements":"1. 计算机科学、人工智能、电子工程等相关专业硕士及以上学历，具有计算机视觉或视觉Agent相关研发经验。\n\n2. 扎实的算法基础，熟悉主流视觉模型及多模态大模型，具备模型调优与轻量化部署经验。\n\n3. 深入理解主流Agent框架原理，在任务规划、工具调用、策略优化等方向有实际项目经验；\n\n4. 优秀的分析和解决问题的能力，项目推动力和团队协作能力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责视觉Agent系统的全链路设计与开发，构建融合多模态感知、动态决策与自动化执行的视觉智能系统，推动复杂场景下的图文多模态/视频理解、交互与生成能力。\n\n2. 负责视觉Agent核心算法的研发与优化，包括但不限于多模态大模型视觉感知、图像生成、多模态对齐（如文本-图像-视频）等方向，持续提升系统的鲁棒性与泛化能力。\n\n3. 研发视觉Agent的协作机制，支持多智能体协同任务（如跨模态推理、工具调用），优化模型在实时性、资源效率及长上下文处理中的表现。\n\n4. 研发大模型在业务场景下关键能力的应用研发，包括但不限于知识和指令遵循、分析诊断、深度推理、反思和评估等能力的优化和落地。\n\n5. 结合业务场景设计并落地视觉Agent应用，赋能业务智能化升级。\n\n6. 跟踪计算机视觉与大模型交叉领域的前沿技术，探索创新技术在实际场景中的落地路径。\n\n岗位基本要求\n1. 计算机科学、人工智能、电子工程等相关专业硕士及以上学历，具有计算机视觉或视觉Agent相关研发经验。\n\n2. 扎实的算法基础，熟悉主流视觉模型及多模态大模型，具备模型调优与轻量化部署经验。\n\n3. 深入理解主流Agent框架原理，在任务规划、工具调用、策略优化等方向有实际项目经验；\n\n4. 优秀的分析和解决问题的能力，项目推动力和团队协作能力。\n\n具备以下条件优先\n1. 在视觉Agent相关领域发表顶会论文（CVPR/ICCV/ECCV/NeurIPS等）或主导过落地项目。\n\n2. 开源社区贡献者或重要竞赛获奖者。\n\n3. 具备大模型与视觉技术融合经验，具有突出的产品建设思维。\n\n岗位亮点\n1. 参与美团本地生活场景的视觉智能化革新，直接赋能数亿用户与千万商家。\n\n2. 探索视觉Agent在生成式AI时代的核心技术，打造行业标杆级应用。\n\n3. 在快速发展的领域中积累经验，成为大模型和智能体领域的专家。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4074668743","sourceKey":"meituan_social","company":"美团","title":"快驴-西安高新仓调度主管","city":"西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4074668743&jobShareType=1","duty":"1.负责司机与车辆日常管理工作，帮助解决司机困难；\n2.根据货量、时效、成本等关键因素，完成系统排线；\n3.管理发运劳务人员，提供作业培训指导并完成日常工作质量；\n4.管理发运现场，提升发运整体效率与装载率；\n5.调配车辆资源，追踪货物在途情况，保障在途时效履约；\n6.统计运输管理报表数据，输出城市运输日报","requirements":"1. 具有3年以上冷链支线运输、城配运输管理经验；\n2. 专科及以上学历，供应链管理、物流管理、企业管理等相关专业优先；\n3. 良好的沟通能力、较强的协同能力，大局观强、善于思考及总结，善于发现问题并优化；\n4. 具备司机与车辆管理专业知识，分拨现场管理经验优先；\n5.可以接受晚班工作时间。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责司机与车辆日常管理工作，帮助解决司机困难；\n2.根据货量、时效、成本等关键因素，完成系统排线；\n3.管理发运劳务人员，提供作业培训指导并完成日常工作质量；\n4.管理发运现场，提升发运整体效率与装载率；\n5.调配车辆资源，追踪货物在途情况，保障在途时效履约；\n6.统计运输管理报表数据，输出城市运输日报\n\n岗位基本要求\n1. 具有3年以上冷链支线运输、城配运输管理经验；\n2. 专科及以上学历，供应链管理、物流管理、企业管理等相关专业优先；\n3. 良好的沟通能力、较强的协同能力，大局观强、善于思考及总结，善于发现问题并优化；\n4. 具备司机与车辆管理专业知识，分拨现场管理经验优先；\n5.可以接受晚班工作时间。\n\n具备以下条件优先\n上升通道明确，具备团队管理赋能、项目经理、业务策略运营综合管理技能，发展前景广阔\n\n岗位亮点\n完善的培训体系，公平公正的晋升渠道，业务发展前景广阔。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3970603311","sourceKey":"meituan_social","company":"美团","title":"基座大模型算法研究员 (Mid-training)","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3970603311&jobShareType=1","duty":"1. 大规模高质量数据体系与合成数据建设\n\n数据体系构建： 建设 Trillion 级别的大规模跨模态数据处理与合成链路。负责从数据清洗、去重、质量评分到动态配比建模的全流程优化。\n\n合成方法演进： 深入探索大规模合成数据 (Synthetic Data) 与自蒸馏 (Self-distillation) 技术，针对复杂逻辑推理、代码生成及多模态场景，制定Pre-training与 Mid-training 阶段的合成数据应用策略。\n\n理论探索： 研究 Data Scaling Laws，解决数据扩展中的模型坍塌（Model Collapse）与多样性瓶颈问题，通过课程学习（Curriculum Learning）等多阶段训练策略，显著优化 Token/FLOPs 转化效率。\n\n2. 长上下文 (Long Context) 与高效架构演进\n\n长窗口突破：持续 Scaling Up 模型的 Context Length，优化超长上下文机制。重点提升 LongCat 等基座模型在长文理解、长程推理、创作等任务上的表现。\n\n架构优化： 探索并验证 MoE（混合专家）、稀疏注意力（Sparse Attention）、线性注意力等高效模型结构；结合模型剪枝与稀疏化技术，协同优化训练与推理效率，降低超长上下文场景下的资源开销。\n\n3. 多模态能力融合与 Agent 赋能\n\n模态融合：探索多模态预训练新范式（如 Early Fusion、统一建模），突破模态融合瓶颈。利用多模态扩展定律指导数据与训练方案，提升模型在多语言、多模态交互场景下的原生能力。\n\n复杂场景落地：面向 Agent、具身智能等前沿场景，提升模型的多模态指令遵循与复杂任务规划能力。\n\n4. 下一代训练范式与前沿技术探索\n\n自进化机制： 协同上下游团队，探索持续学习（Continuous Learning）与模型自进化（Self-evolution）机制，研究多模态奖励模型与大规模RL在 Mid-training 阶段的应用。\n\n能力扩展： 研究推理阶段扩展（Test-time Scaling）及全模态链式思维（Omni-modal CoT），推动模型从单纯的“知识记忆”向“深度推理与问题解决”演进。","requirements":"对大模型开发流程有深入认知，熟悉预训练、指令微调、RL等流程与框架；\n\n对Dense和MoE等模型架构有深入理解并拥有大规模训练经验\n\n具备扎实的算法和数学理论基础及良好的编程基础，熟悉自然语言处理、生成式AI和机器学习等技术，熟悉Python、Java等至少一种编程语言，熟悉PyTorch等深度学习框架，对技术开发及应用有热情；\n\n目标感强，善于分析和发现问题，拆解简化，有想法并乐于挑战自我，能够从日常工作中发现新的空间；\n\n条理性强且有推动力，能够梳理繁杂的工作并建立有效机制，推动上下游配合完成目标。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 大规模高质量数据体系与合成数据建设\n\n数据体系构建： 建设 Trillion 级别的大规模跨模态数据处理与合成链路。负责从数据清洗、去重、质量评分到动态配比建模的全流程优化。\n\n合成方法演进： 深入探索大规模合成数据 (Synthetic Data) 与自蒸馏 (Self-distillation) 技术，针对复杂逻辑推理、代码生成及多模态场景，制定Pre-training与 Mid-training 阶段的合成数据应用策略。\n\n理论探索： 研究 Data Scaling Laws，解决数据扩展中的模型坍塌（Model Collapse）与多样性瓶颈问题，通过课程学习（Curriculum Learning）等多阶段训练策略，显著优化 Token/FLOPs 转化效率。\n\n2. 长上下文 (Long Context) 与高效架构演进\n\n长窗口突破：持续 Scaling Up 模型的 Context Length，优化超长上下文机制。重点提升 LongCat 等基座模型在长文理解、长程推理、创作等任务上的表现。\n\n架构优化： 探索并验证 MoE（混合专家）、稀疏注意力（Sparse Attention）、线性注意力等高效模型结构；结合模型剪枝与稀疏化技术，协同优化训练与推理效率，降低超长上下文场景下的资源开销。\n\n3. 多模态能力融合与 Agent 赋能\n\n模态融合：探索多模态预训练新范式（如 Early Fusion、统一建模），突破模态融合瓶颈。利用多模态扩展定律指导数据与训练方案，提升模型在多语言、多模态交互场景下的原生能力。\n\n复杂场景落地：面向 Agent、具身智能等前沿场景，提升模型的多模态指令遵循与复杂任务规划能力。\n\n4. 下一代训练范式与前沿技术探索\n\n自进化机制： 协同上下游团队，探索持续学习（Continuous Learning）与模型自进化（Self-evolution）机制，研究多模态奖励模型与大规模RL在 Mid-training 阶段的应用。\n\n能力扩展： 研究推理阶段扩展（Test-time Scaling）及全模态链式思维（Omni-modal CoT），推动模型从单纯的“知识记忆”向“深度推理与问题解决”演进。\n\n岗位基本要求\n对大模型开发流程有深入认知，熟悉预训练、指令微调、RL等流程与框架；\n\n对Dense和MoE等模型架构有深入理解并拥有大规模训练经验\n\n具备扎实的算法和数学理论基础及良好的编程基础，熟悉自然语言处理、生成式AI和机器学习等技术，熟悉Python、Java等至少一种编程语言，熟悉PyTorch等深度学习框架，对技术开发及应用有热情；\n\n目标感强，善于分析和发现问题，拆解简化，有想法并乐于挑战自我，能够从日常工作中发现新的空间；\n\n条理性强且有推动力，能够梳理繁杂的工作并建立有效机制，推动上下游配合完成目标。\n\n岗位亮点\n团队扁平，人才密度高，美团“北斗计划”和博士员工比例高，近年团队在ICLR、NeurIPS、ICML、ACL等顶会累计发表论文50余篇，团队员工获EMNLP 2024 Outstanding Paper、ACL 2025 Outstanding Paper，吴文俊人工智能奖科技进步奖、CCF科技成果奖等荣誉激励。\n\n参与大语言模型、多模态大模型核心技术研发，接触全模态融合、超长上下文等前沿技术。\n\n参与探索高效模型架构创新，参与大模型全链路核心技术研发，接触模型设计、分布式训练和推理优化等前沿技术。\n\n充足算力保障，拥有大规模分布式训练环境和丰富数据资源。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3934765291","sourceKey":"meituan_social","company":"美团","title":"干调PB集采专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3934765291&jobShareType=1","duty":"1. 负责集采PB商品的采购策略制定与执行，确保商品供应的稳定性与成本优化。  \n2. 主导供应商开发、商品开发、运营、评估与关系维护，建立长期稳定的合作机制。  \n3. 分析市场需求与客户需求，制定采购计划并调整以匹配业务需求。  \n4. 协同跨部门团队优化采购流程，提升供应链效率与响应速度。  \n5. 监控采购风险，制定应急预案并推动落地执行。","requirements":"1. 大学本科及以上学历，供应链管理、物流管理或相关专业优先。  \n2. 5年以上采购或供应链相关工作经验，有统采或PB商品经验优先。  \n3. 熟悉采购全流程，具备供应商管理、成本分析和谈判能力。  \n4. 熟练使用数据分析工具，具备较强的逻辑思维与问题解决能力。  \n5. 具备良好的沟通协调能力，能高效推动跨部门协作。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责集采PB商品的采购策略制定与执行，确保商品供应的稳定性与成本优化。  \n2. 主导供应商开发、商品开发、运营、评估与关系维护，建立长期稳定的合作机制。  \n3. 分析市场需求与客户需求，制定采购计划并调整以匹配业务需求。  \n4. 协同跨部门团队优化采购流程，提升供应链效率与响应速度。  \n5. 监控采购风险，制定应急预案并推动落地执行。\n\n岗位基本要求\n1. 大学本科及以上学历，供应链管理、物流管理或相关专业优先。  \n2. 5年以上采购或供应链相关工作经验，有统采或PB商品经验优先。  \n3. 熟悉采购全流程，具备供应商管理、成本分析和谈判能力。  \n4. 熟练使用数据分析工具，具备较强的逻辑思维与问题解决能力。  \n5. 具备良好的沟通协调能力，能高效推动跨部门协作。\n\n具备以下条件优先\n1、线上零售+线下商超经验优先；\n2、品牌方经验优先；\n\n岗位亮点\n1. 参与公司核心自有品牌项目，直接支持业务增长。  \n2. 接触多元化商品品类，积累行业前沿的采购与供应链经验。  \n3. 扁平化管理，提供快速成长与能力拓展的机会。  \n4. 团队氛围开放，鼓励创新与数据驱动决策。  \n5. 大平台提供有竞争力的薪酬与职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:804538188","sourceKey":"meituan_social","company":"美团","title":"中小发-城市主管","city":"邯郸市/保定市/大同市/南京市/盐城市/南通市/镇江市/杭州市/宁波市/湖州市/台州市/合肥市/淮南市/六安市/亳州市/泉州市/漳州市/景德镇市/赣州市/抚州市/济南市/威海市/济宁市/日照市/临沂市/荆州市/岳阳市/江门市/阳江市/肇庆市/揭阳市/云浮市/文昌市/南充市/保山市/安康市/兰州市/张掖市/酒泉市/银川市/吴忠市/中卫市/克拉玛依市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=804538188&jobShareType=1","duty":"1.招募销售人员，组建地面团队； \n2.快速培养新人，快速掌握业务流程及培养签约能力； \n3.负责城市市场的业务开拓（可签约所属区域内到综的综合品类）； \n4.制定城市或区域开拓策略与打法，结合现有市场覆盖率，以及市场覆盖目标； \n5.具备良好的沟通能力，与中后台部门协同作战，提升业务核心指标。","requirements":"1.大专以上学历，3年以上主动销售工作经验，销售业绩优秀；至少1年以上销售团队管理经验，有良好的销售团队管理成绩；\n2.个性开朗，有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛； \n3.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心； \n4.富有激情和创新理念，具备较强的人际沟通能力及逻辑思维能力，思维敏捷，擅长打造有执行力的团队； \n5.为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1.招募销售人员，组建地面团队； \n2.快速培养新人，快速掌握业务流程及培养签约能力； \n3.负责城市市场的业务开拓（可签约所属区域内到综的综合品类）； \n4.制定城市或区域开拓策略与打法，结合现有市场覆盖率，以及市场覆盖目标； \n5.具备良好的沟通能力，与中后台部门协同作战，提升业务核心指标。\n\n岗位基本要求\n1.大专以上学历，3年以上主动销售工作经验，销售业绩优秀；至少1年以上销售团队管理经验，有良好的销售团队管理成绩；\n2.个性开朗，有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛； \n3.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心； \n4.富有激情和创新理念，具备较强的人际沟通能力及逻辑思维能力，思维敏捷，擅长打造有执行力的团队； \n5.为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n年轻团队、富有活力；发展空间大，向上可晋升至区域经理","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4041144470","sourceKey":"meituan_social","company":"美团","title":"供给策略产品","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4041144470&jobShareType=1","duty":"1. 面向AI搜的商品信息进行数据结构设计与优化，为大模型所应用的数据质量服务，提升供给信息在AI搜的应用效率并拿到应用效果。  \n2. 深入理解AI搜时代对数据格式要求的趋势并理解用户需求，挖掘供给信息在AI搜的增长机会。  \n3. 协同各业务团队运营及算法团队，推动供给策略落地并持续迭代。","requirements":"1. 大学本科及以上学历，3年以上AI信息处理相关经验。  \n2. 熟练使用prompt解决数据处理工作，能独立完成策略验证与迭代。  \n3. 逻辑清晰，沟通能力强，能高效协同跨部门团队。 \n4.有一定的商品信息及实体认知，有平台型产品经验者优先。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1. 面向AI搜的商品信息进行数据结构设计与优化，为大模型所应用的数据质量服务，提升供给信息在AI搜的应用效率并拿到应用效果。  \n2. 深入理解AI搜时代对数据格式要求的趋势并理解用户需求，挖掘供给信息在AI搜的增长机会。  \n3. 协同各业务团队运营及算法团队，推动供给策略落地并持续迭代。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上AI信息处理相关经验。  \n2. 熟练使用prompt解决数据处理工作，能独立完成策略验证与迭代。  \n3. 逻辑清晰，沟通能力强，能高效协同跨部门团队。 \n4.有一定的商品信息及实体认知，有平台型产品经验者优先。\n\n岗位亮点\n1. 参与核心业务，直接影响美团AI搜用户体验。  \n2. 与核心团队合作，快速提升策略与产品能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3994431036","sourceKey":"meituan_social","company":"美团","title":"大客户销售负责人（口眼）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3994431036&jobShareType=1","duty":"1.能够基于对消费医疗相关行业（口腔、眼科、眼镜）、客户需求的深刻理解及洞察及市场动态的关注，制定出符合客户发展需求销售策略。\n2.积极参与业务部策略的制定，能够结合自己的专业和理解，输出建设性建议，能基于对交易和广告变现商业模式的理解，探索出一套符合业务目标达成的路径。\n3.能够根据业务方向制定出大客户团队主要核心考核指标及过程观测指标，并能够根据实施现状进行优化迭代。\n4.能够结合大客户团队实际工作场景和工作流程，推动销运团队进行大客户团队系统工具升级迭代。\n5.能够协同整合跨部门的资源来满足客户不同发展阶段的经营需求，推动中后台部门的日常沟通机制，保障信息沟通的及时性和有效性。\n6.参与大客户团队长短期激励政策及荣誉体系的设计搭建，能够打造出一支具备行业竞争力和战斗力的大客户销售团队。","requirements":"1.本科及以上学历，8年以上互联网市场、有行业负责人，商业产品经理，大客户销售团队管理工作经历经验者优先；\n2.有敏锐的行业洞察力，能基于现有知识及行业信息，预测行业趋势并发现产品潜在机会；\n3.有良好的带团队经验及能力，逻辑清晰，成就动机强；\n4.有强大的自驱力，擅于协调多方资源取得业务结果。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.能够基于对消费医疗相关行业（口腔、眼科、眼镜）、客户需求的深刻理解及洞察及市场动态的关注，制定出符合客户发展需求销售策略。\n2.积极参与业务部策略的制定，能够结合自己的专业和理解，输出建设性建议，能基于对交易和广告变现商业模式的理解，探索出一套符合业务目标达成的路径。\n3.能够根据业务方向制定出大客户团队主要核心考核指标及过程观测指标，并能够根据实施现状进行优化迭代。\n4.能够结合大客户团队实际工作场景和工作流程，推动销运团队进行大客户团队系统工具升级迭代。\n5.能够协同整合跨部门的资源来满足客户不同发展阶段的经营需求，推动中后台部门的日常沟通机制，保障信息沟通的及时性和有效性。\n6.参与大客户团队长短期激励政策及荣誉体系的设计搭建，能够打造出一支具备行业竞争力和战斗力的大客户销售团队。\n\n岗位基本要求\n1.本科及以上学历，8年以上互联网市场、有行业负责人，商业产品经理，大客户销售团队管理工作经历经验者优先；\n2.有敏锐的行业洞察力，能基于现有知识及行业信息，预测行业趋势并发现产品潜在机会；\n3.有良好的带团队经验及能力，逻辑清晰，成就动机强；\n4.有强大的自驱力，擅于协调多方资源取得业务结果。\n\n岗位亮点\n高潜力发展行业，具备整体操盘的空间，销售管理+行业运营复合型培养体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4029738149","sourceKey":"meituan_social","company":"美团","title":"小象-上海仓储主管","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4029738149&jobShareType=1","duty":"1.依据生产任务的预估，负责生产员工的前置排班\n2.负责组织员工有节奏的生产，保障准时清场 \n3.负责员工的作业效率和作业质量，如人效指标和差异指标的考核 \n4.负责生产上下游的联动协同，保障链路衔接 \n5.负责场地6S的管理 \n6.负现生产场地动线的合理排布和优化\n7.负责员工规范化操作的培训和跟进 \n8.负责员工绩效的评定","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 3年以上仓储或物流相关经验，熟悉WMS系统及拣播流程。  \n3. 具备基础团队管理能力，能独立解决作业异常问题。  \n4. 熟练使用办公软件，具备基础数据分析能力。  \n5. 工作细致，能力强，能适应快节奏作业环境。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.依据生产任务的预估，负责生产员工的前置排班\n2.负责组织员工有节奏的生产，保障准时清场 \n3.负责员工的作业效率和作业质量，如人效指标和差异指标的考核 \n4.负责生产上下游的联动协同，保障链路衔接 \n5.负责场地6S的管理 \n6.负现生产场地动线的合理排布和优化\n7.负责员工规范化操作的培训和跟进 \n8.负责员工绩效的评定\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 3年以上仓储或物流相关经验，熟悉WMS系统及拣播流程。  \n3. 具备基础团队管理能力，能独立解决作业异常问题。  \n4. 熟练使用办公软件，具备基础数据分析能力。  \n5. 工作细致，能力强，能适应快节奏作业环境。\n\n岗位亮点\n生产岗是RDC的主要模块，发展空间很大，责任也相应匹配，最能锻炼和体现管理能力和水平，对自身的管理成长最有帮助","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3629309975","sourceKey":"meituan_social","company":"美团","title":"OLAP引擎内核研发","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3629309975&jobShareType=1","duty":"美团OLAP引擎团队，专注于研发和维护满足美团外卖、配送、酒旅等所有业务团队OLAP分析需求的引擎内核及服务，支撑公司近万台服务器规模的OLAP集群，每天亿级查询请求量，tp99查询秒级响应，提升全公司开发和使用数据报表的效率。工作职责包括但不限于：\n1.关注业内OLAP技术发展趋势，基于公司的业务特点和需求，进行合理的技术选型以及前沿探索；\n2.建设美团统一OLAP引擎，基于主流开源引擎改造优化，实现一套系统支持多种数据模型和存储格式，满足公司内部不同OLAP分析场景需求；\n3.负责维护OLAP引擎服务的稳定性，通过SQL优化器、向量化执行、自动物化视图及索引构建等工程优化，持续提升OLAP引擎性能；\n4.协同工具链产品和研发，建设OLAP开发和管理平台，支持数据导入导出、元数据管理、任务构建、SQL查询等功能，提升业务开发效率。\n5.探索AI驱动的智能查询优化，集成Text-to-SQL等能力，建设AI友好的查询引擎，提升业务人员数据使用效率","requirements":"1.本科及以上，计算机相关专业； \n2.具有扎实的计算机工程和算法基础，熟练掌握Java和C++编程，对进程间通信，内存管理，网络编程等相关知识有深入了解；\n3.有复杂问题解决能力，快速分析系统代码bug与性能等问题，并能够通过分析，归纳，抽象成解决一类问题的方案；\n4.有良好的沟通和团队协作能力，能够熟练编写各类技术文档。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n美团OLAP引擎团队，专注于研发和维护满足美团外卖、配送、酒旅等所有业务团队OLAP分析需求的引擎内核及服务，支撑公司近万台服务器规模的OLAP集群，每天亿级查询请求量，tp99查询秒级响应，提升全公司开发和使用数据报表的效率。工作职责包括但不限于：\n1.关注业内OLAP技术发展趋势，基于公司的业务特点和需求，进行合理的技术选型以及前沿探索；\n2.建设美团统一OLAP引擎，基于主流开源引擎改造优化，实现一套系统支持多种数据模型和存储格式，满足公司内部不同OLAP分析场景需求；\n3.负责维护OLAP引擎服务的稳定性，通过SQL优化器、向量化执行、自动物化视图及索引构建等工程优化，持续提升OLAP引擎性能；\n4.协同工具链产品和研发，建设OLAP开发和管理平台，支持数据导入导出、元数据管理、任务构建、SQL查询等功能，提升业务开发效率。\n5.探索AI驱动的智能查询优化，集成Text-to-SQL等能力，建设AI友好的查询引擎，提升业务人员数据使用效率\n\n岗位基本要求\n1.本科及以上，计算机相关专业； \n2.具有扎实的计算机工程和算法基础，熟练掌握Java和C++编程，对进程间通信，内存管理，网络编程等相关知识有深入了解；\n3.有复杂问题解决能力，快速分析系统代码bug与性能等问题，并能够通过分析，归纳，抽象成解决一类问题的方案；\n4.有良好的沟通和团队协作能力，能够熟练编写各类技术文档。\n\n具备以下条件优先\n1.有开源及自研查询引擎（包括不限于Druid/Doris/Clickhouse/Presto等）的实际改造经验优先，对开源项目有贡献者加分\n2. 有AI数据开发实践经验者优先\n3.具备很良好的owner意识，能以结果和价值为导向，利用科学的方法进行指标收集、统计、分析，从而进行成果的衡量\n\n岗位亮点\n美团有万台服务器规模的OLAP集群，支撑外卖、酒旅、配送等多种领域业务的OLAP分析场景，数据规模、集群体量以及业务复杂度都在快速增长，对OLAP引擎团队提出了巨大的技术挑战也带来了锻炼和成长空间。\n另外，我们是一支学习型团队，内部培养了多名开源社区的PMC、Commiter成员，对新入职同学有经验丰富的导师一对一指导，通过实际项目提升业务理解、项目管理、团队合作能力，加入我们都有独挡一面，成为行业领域专家的机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3938769595","sourceKey":"meituan_social","company":"美团","title":"冻牛羊采购专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3938769595&jobShareType=1","duty":"一、核心采购业务\n全流程采购执行\n制定年度/季度采购计划，基于历史数据（库存周转率、冻损率） 和市场预判，动态调整。\n执行从寻源、比价、合同谈判到订单跟踪的全链路操作，确保月度采购量达标率≥95% 。\n成本精细化管理\n通过期货套保、季节性价差采购 等手段，实现全年综合采购成本低于市场均价3%-5% 。\n优化物流方案（如海运整柜VS拼箱），控制冷链成本占比≤总采购额15% 。\n二、供应商全生命周期管理\n管理阶段\n具体职责\n考核指标\n准入审核\n实地审计屠宰厂资质（如BRC认证）、清真合规性（Halal证书）\t\n新增供应商合格率100%\n绩效评估\n按季度评估交付准时率、质量事故率（如冰衣超标次数）\t\n供应商淘汰率≥5%/年\n风险备份\n建立替代供应商名单（如南美草饲牛肉替代澳洲谷饲）\t\n核心品类备用渠道≥2家\n三、质量与合规风控\n质量管控\n制定冻品验收企业标准 （冰衣厚度≤净重15%、解冻失水率≤8%），主导到货质检。\n每季度送检第三方实验室（检测瘦肉精、微生物指标），确保质检不合格批次≤0.5% 。\n合规管理\n跟踪进口政策变化（如CIQ新增检疫要求），100%确保单证合规 （卫生证书、核酸检测报告）。\n建立溯源系统 ，实现从牧场到仓库的批次追踪（如区块链技术应用）。\n四、跨部门协同增效\n协作部门\n协同任务\n输出成果\n仓储物流\n制定-18℃冷链SOP，减少冻损\t\n冻损率从1.2%降至0.8%\n生产研发\n根据部位肉特性（如牛腱VS牛腩）优化分割方案\t\n原料利用率提升10%\n销售计划\n提供价格趋势预警，支持促销备货\t\n滞销库存占比≤5%\n五、数据驱动决策\n行情分析\n每周输出全球牛羊肉价格波动简报 \n采购模型迭代\n基于历史数据建立采购成本敏感度模型 \n供应链管理\n精通冷冻肉品供应链各环节（源头牧场/屠宰厂→冷链运输→仓储管理→分销）。\n能优化采购成本结构（如减少冻损率、控制库存周转周期\u003c30天）。\n品质把控\n熟练掌握牛羊肉分级标准 （如澳洲MSA、USDA Prime/Choice）、解冻损失率检测、微生物指标检验。\n能通过眼观/触感 快速判断冻品质量（色泽、冰晶量、复温后弹性）。\n成本控制\n擅长利用工具对冲价格波动风险 ，建立动态采购模型（如季节性价差策略）。\n具备大宗合同谈判能力（年采购量千吨级以上）。\n合规与风控\n熟悉进口冻品检疫流程 （CIQ证书、核酸检测要求）、清真认证（Halal）、溯源系统建设。\n供应商审计能力（如查验牧场动物福利标准、屠宰厂注册号）","requirements":"1 5年以上牛羊肉采购/贸易/加工/生产/销售经验\n2 本科及以上学历\n6. 自驱力强，具有较好的学习能力，愿意主动思考AI如何进一步优化工作流程。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n一、核心采购业务\n全流程采购执行\n制定年度/季度采购计划，基于历史数据（库存周转率、冻损率） 和市场预判，动态调整。\n执行从寻源、比价、合同谈判到订单跟踪的全链路操作，确保月度采购量达标率≥95% 。\n成本精细化管理\n通过期货套保、季节性价差采购 等手段，实现全年综合采购成本低于市场均价3%-5% 。\n优化物流方案（如海运整柜VS拼箱），控制冷链成本占比≤总采购额15% 。\n二、供应商全生命周期管理\n管理阶段\n具体职责\n考核指标\n准入审核\n实地审计屠宰厂资质（如BRC认证）、清真合规性（Halal证书）\t\n新增供应商合格率100%\n绩效评估\n按季度评估交付准时率、质量事故率（如冰衣超标次数）\t\n供应商淘汰率≥5%/年\n风险备份\n建立替代供应商名单（如南美草饲牛肉替代澳洲谷饲）\t\n核心品类备用渠道≥2家\n三、质量与合规风控\n质量管控\n制定冻品验收企业标准 （冰衣厚度≤净重15%、解冻失水率≤8%），主导到货质检。\n每季度送检第三方实验室（检测瘦肉精、微生物指标），确保质检不合格批次≤0.5% 。\n合规管理\n跟踪进口政策变化（如CIQ新增检疫要求），100%确保单证合规 （卫生证书、核酸检测报告）。\n建立溯源系统 ，实现从牧场到仓库的批次追踪（如区块链技术应用）。\n四、跨部门协同增效\n协作部门\n协同任务\n输出成果\n仓储物流\n制定-18℃冷链SOP，减少冻损\t\n冻损率从1.2%降至0.8%\n生产研发\n根据部位肉特性（如牛腱VS牛腩）优化分割方案\t\n原料利用率提升10%\n销售计划\n提供价格趋势预警，支持促销备货\t\n滞销库存占比≤5%\n五、数据驱动决策\n行情分析\n每周输出全球牛羊肉价格波动简报 \n采购模型迭代\n基于历史数据建立采购成本敏感度模型 \n供应链管理\n精通冷冻肉品供应链各环节（源头牧场/屠宰厂→冷链运输→仓储管理→分销）。\n能优化采购成本结构（如减少冻损率、控制库存周转周期\u003c30天）。\n品质把控\n熟练掌握牛羊肉分级标准 （如澳洲MSA、USDA Prime/Choice）、解冻损失率检测、微生物指标检验。\n能通过眼观/触感 快速判断冻品质量（色泽、冰晶量、复温后弹性）。\n成本控制\n擅长利用工具对冲价格波动风险 ，建立动态采购模型（如季节性价差策略）。\n具备大宗合同谈判能力（年采购量千吨级以上）。\n合规与风控\n熟悉进口冻品检疫流程 （CIQ证书、核酸检测要求）、清真认证（Halal）、溯源系统建设。\n供应商审计能力（如查验牧场动物福利标准、屠宰厂注册号）\n\n岗位基本要求\n1 5年以上牛羊肉采购/贸易/加工/生产/销售经验\n2 本科及以上学历\n6. 自驱力强，具有较好的学习能力，愿意主动思考AI如何进一步优化工作流程。\n\n具备以下条件优先\n大型牛肉贸易商工作经历，海外采购经历，国产加工生产实操经验\n\n岗位亮点\n核心发展业务，高成长型，参与品类规划与发展策略的制定","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3987661638","sourceKey":"meituan_social","company":"美团","title":"酒店业务经理KA","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3987661638&jobShareType=1","duty":"1.负责开拓酒店业务领域内的大客户，建立并维护良好的客户关系。\n2.负责制定并执行销售策略，完成销售目标，并确保业绩的持续增长。\n3.负责与客户进行商务谈判，达成合作协议，并跟进协议的履行情况。\n4.跟踪行业动态，了解市场需求，为公司产品和服务的优化提供参考意见。","requirements":"1.大学本科及以上学历，具备相关专业知识。\n2.至少2年以上酒店业务开发或大客户管理经验，熟悉酒店行业市场。\n3.具备较强的业务拓展能力和销售技巧，能够独立完成销售目标。\n4.具备良好的沟通能力和谈判技巧，能够与客户进行有效的商务洽谈。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.负责开拓酒店业务领域内的大客户，建立并维护良好的客户关系。\n2.负责制定并执行销售策略，完成销售目标，并确保业绩的持续增长。\n3.负责与客户进行商务谈判，达成合作协议，并跟进协议的履行情况。\n4.跟踪行业动态，了解市场需求，为公司产品和服务的优化提供参考意见。\n\n岗位基本要求\n1.大学本科及以上学历，具备相关专业知识。\n2.至少2年以上酒店业务开发或大客户管理经验，熟悉酒店行业市场。\n3.具备较强的业务拓展能力和销售技巧，能够独立完成销售目标。\n4.具备良好的沟通能力和谈判技巧，能够与客户进行有效的商务洽谈。\n\n岗位亮点\n1.公司提供良好的发展平台和晋升机会，为员工提供广阔的职业发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3954309447","sourceKey":"meituan_social","company":"美团","title":"成都-冻库仓储主管","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3954309447&jobShareType=1","duty":"1、负责冻库的全面管理及日常运营，确保仓库作业流程的高效执行，提升仓库整体运营效率\n2、负责仓库人员的：选，用，育，留，对人效提升和员工满意度负责；\n3、负责冻库的：收，管，存，发，盘等现场作业，做好商品进出库及库存管理工作，确保库存数据准确\n4、负责冻库商品订单履约分拣出库现场管理，包含：人员需求及排班、作业场地规划、物料准备、生产备货及分拣等。\n5、负责确保仓库内物资的安全、有序、高效运转；","requirements":"1.有生鲜行业或冷链行业背景\n2.熟悉库存管理，对冷链现场作业、质量管控及改善有一定经验。\n3.具备良好的沟通协调能力和团队领导能力，能够有效管理团队；\n4.具备较强的问题解决能力和应变能力，能够应对各种突发情况；\n5、有较好的数据整理、分析能力","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、负责冻库的全面管理及日常运营，确保仓库作业流程的高效执行，提升仓库整体运营效率\n2、负责仓库人员的：选，用，育，留，对人效提升和员工满意度负责；\n3、负责冻库的：收，管，存，发，盘等现场作业，做好商品进出库及库存管理工作，确保库存数据准确\n4、负责冻库商品订单履约分拣出库现场管理，包含：人员需求及排班、作业场地规划、物料准备、生产备货及分拣等。\n5、负责确保仓库内物资的安全、有序、高效运转；\n\n岗位基本要求\n1.有生鲜行业或冷链行业背景\n2.熟悉库存管理，对冷链现场作业、质量管控及改善有一定经验。\n3.具备良好的沟通协调能力和团队领导能力，能够有效管理团队；\n4.具备较强的问题解决能力和应变能力，能够应对各种突发情况；\n5、有较好的数据整理、分析能力\n\n具备以下条件优先\n1、供应链管理、物流管理相关专业优先；\n2、能熟练使用数据库工具，具有很强的数据处理和业务分析能力，有数据分析经验基础\n3、适应弹性工作，有互联网电商及生鲜平台经验更佳\n\n岗位亮点\n1.提供丰富的物流/仓储管理经验积累机会；\n2.发展空间大，团队氛围好；\n3.公司发展迅速，具有良好的职业晋升机制，能够为员工提供广阔的发展空间","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3529829462","sourceKey":"meituan_social","company":"美团","title":"闪购-高级Java开发工程师（增长营销方向）","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3529829462&jobShareType=1","duty":"1.参与私域用增系统和营销系统的研发建设，保证系统符合质量性能要求；\n2.进行需求分析以及主要业务功能的开发，对现有业务模块进行优化；\n3.将业务逻辑拆解清晰，攻克技术难点，支撑业务快速发展；\n4.系统技术优化，提升系统的稳定性、性能和可维护性；\n5.借助AI Coding工具提升用增与营销系统研发效率，探索AI技术在用户增长策略智能化、营销活动自动配置等场景中的工程落地。","requirements":"1.大学本科以上学历，计算机或相关专业，4年以上Java实际项目开发经验；\n2.有扎实的Java基础，Java多线程、并发以及网络通信有深厚的经验；\n3.熟悉设计模式、OOA/OOD。熟悉主流开源应用框架，如Spring、MyBatis、XML、JSON、Maven等开发技术；\n4.熟悉关系型数据库MySQL等，SQL优化。熟悉Memcached、MongoDB、Redis、HBase等；\n5.熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息、负载均衡等机制和实现；\n6.热爱技术，对技术有不懈的追求，喜欢研究开源代码；\n7.良好的学习能力、团队协作能力和沟通能力；能主动承担压力，态度端正积极，善于思考，能独立分析和解决问题；\n8.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；有电商用增系统、促销系统或优惠券系统经验者优先。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.参与私域用增系统和营销系统的研发建设，保证系统符合质量性能要求；\n2.进行需求分析以及主要业务功能的开发，对现有业务模块进行优化；\n3.将业务逻辑拆解清晰，攻克技术难点，支撑业务快速发展；\n4.系统技术优化，提升系统的稳定性、性能和可维护性；\n5.借助AI Coding工具提升用增与营销系统研发效率，探索AI技术在用户增长策略智能化、营销活动自动配置等场景中的工程落地。\n\n岗位基本要求\n1.大学本科以上学历，计算机或相关专业，4年以上Java实际项目开发经验；\n2.有扎实的Java基础，Java多线程、并发以及网络通信有深厚的经验；\n3.熟悉设计模式、OOA/OOD。熟悉主流开源应用框架，如Spring、MyBatis、XML、JSON、Maven等开发技术；\n4.熟悉关系型数据库MySQL等，SQL优化。熟悉Memcached、MongoDB、Redis、HBase等；\n5.熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息、负载均衡等机制和实现；\n6.热爱技术，对技术有不懈的追求，喜欢研究开源代码；\n7.良好的学习能力、团队协作能力和沟通能力；能主动承担压力，态度端正积极，善于思考，能独立分析和解决问题；\n8.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；有电商用增系统、促销系统或优惠券系统经验者优先。\n\n具备以下条件优先\n1.有大型互联网或电商企业工作经验优先考虑\n2.参与过电商用增系统、促销系统、优惠券系统经验者优先考虑\n\n岗位亮点\n1.将参与到用增、营销核心系统开发工作，有机会接触到大规模系统的设计和开发；\n2.将获得丰富的互联网行业经验和系统开发经验，对个人职业发展具有积极的推动作用；\n3.团队技术氛围良好，能帮助自我快速提升；\n4.团队深度拥抱AI工作方式，日常研发全面接入AI Coding工具，持续探索AI驱动的用增与营销系统智能化实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2227465898","sourceKey":"meituan_social","company":"美团","title":"交易系统平台部-订单履约售后-高级Java开发工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2227465898&jobShareType=1","duty":"1. 支撑到家外卖、闪购、医药等到家所有交易业务，负责订单履约及售后业务领域迭代和创新，支持千万级订单、百万级QPS的交易平台；\n2. 负责订单系统的稳定性建设，通过稳定性基础设施建设，中间件优化等手段追求极致的稳定性保障目标，保障线上交易业务的高可用；\n3. 通过建设即时零售和直播爆品交易体系，支撑到家餐饮、零售业务快速发展，建设业界先进的即时零售交易平台。\n4.借助 AI Coding 工具提升日常研发与代码评审效率。","requirements":"1. 扎实的计算机专业基本功，强大的写码能力；\n2. 熟悉掌握常用的Java类库及开源框架，如多线程、并发处理、I/O与网络通讯、Spring等，掌握Java虚拟机原理，有JVM分析及调优的经验； \n3. 熟练掌握Spring、MyBatis等JAVA研发框架 ；\n4. 熟悉互联网常见中间件，如RPC、MYSQL、NOSQL等； \n5. 有较强的逻辑思维能力，善于分析、归纳、描述、沟通、和解决问题。\n6.熟练使用 AI 辅助编码工具，能将 AI 工具有效融入日常开发流程","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 支撑到家外卖、闪购、医药等到家所有交易业务，负责订单履约及售后业务领域迭代和创新，支持千万级订单、百万级QPS的交易平台；\n2. 负责订单系统的稳定性建设，通过稳定性基础设施建设，中间件优化等手段追求极致的稳定性保障目标，保障线上交易业务的高可用；\n3. 通过建设即时零售和直播爆品交易体系，支撑到家餐饮、零售业务快速发展，建设业界先进的即时零售交易平台。\n4.借助 AI Coding 工具提升日常研发与代码评审效率。\n\n岗位基本要求\n1. 扎实的计算机专业基本功，强大的写码能力；\n2. 熟悉掌握常用的Java类库及开源框架，如多线程、并发处理、I/O与网络通讯、Spring等，掌握Java虚拟机原理，有JVM分析及调优的经验； \n3. 熟练掌握Spring、MyBatis等JAVA研发框架 ；\n4. 熟悉互联网常见中间件，如RPC、MYSQL、NOSQL等； \n5. 有较强的逻辑思维能力，善于分析、归纳、描述、沟通、和解决问题。\n6.熟练使用 AI 辅助编码工具，能将 AI 工具有效融入日常开发流程\n\n具备以下条件优先\n1. 熟练掌握linux常用命令，有线上运维经验者优先；\n2. 参与过复杂电商交易的设计、优化者优先 ；\n3. 参与过复杂电商平台化建设者优先。\n\n岗位亮点\n1. 可以深度参与到即时零售能力、直播爆品体系建设，跟随业务一直成长；\n2. 学习到业界先进的SET化、平台化的交易系统建设经验；\n3. 团队氛围好，开放互助、技术氛围浓厚。\n4.团队全面接入 AI Coding 工具，同时积极探索大模型/Agent技术在商品标准化智能化场景中的工程应用，兼具高并发技术挑战与 AI 创新探索空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3466728633","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-后台工程师（调度系统方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3466728633&jobShareType=1","duty":"参与到境外配送核心调度系统的研发工作，包括需求分析、系统设计、开发落地，主要包含以下方向：\n\n与业务团队、算法团队紧密合作，改善配送供需平衡水平，提升骑手派单质量，帮助美团送得更快，送得更好。\n结合单量规模、业务发展策略，进行合理的系统架构设计，持续提升系统的性能及业务扩展性。\n负责指导和培养团队初阶工程师，提升团队整体业务能力和技术能力。\n探索AI技术在配送调度场景中的工程落地，结合AI Coding工具提升系统研发效率，推动调度系统的智能化演进。","requirements":"1.计算机或相关专业本科及以上学历，2年以上互联网开发经验；\n2.有扎实的编程基本功、熟悉Kafka、MySql、Redis等相关技术栈，掌握大规模分布式系统的基础原理；\n3.良好的学习能力、热爱技术，对技术有不懈的追求；\n4.具备良好的沟通能力，善于协同多个团队完成复杂任务；\n5.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；与算法团队有协作经验，对机器学习模型等算法相关知识有基础认识者优先。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n参与到境外配送核心调度系统的研发工作，包括需求分析、系统设计、开发落地，主要包含以下方向：\n\n与业务团队、算法团队紧密合作，改善配送供需平衡水平，提升骑手派单质量，帮助美团送得更快，送得更好。\n结合单量规模、业务发展策略，进行合理的系统架构设计，持续提升系统的性能及业务扩展性。\n负责指导和培养团队初阶工程师，提升团队整体业务能力和技术能力。\n探索AI技术在配送调度场景中的工程落地，结合AI Coding工具提升系统研发效率，推动调度系统的智能化演进。\n\n岗位基本要求\n1.计算机或相关专业本科及以上学历，2年以上互联网开发经验；\n2.有扎实的编程基本功、熟悉Kafka、MySql、Redis等相关技术栈，掌握大规模分布式系统的基础原理；\n3.良好的学习能力、热爱技术，对技术有不懈的追求；\n4.具备良好的沟通能力，善于协同多个团队完成复杂任务；\n5.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；与算法团队有协作经验，对机器学习模型等算法相关知识有基础认识者优先。\n\n具备以下条件优先\n1、与算法团队有协作经验，对机器学习模型等算法相关知识有基础认识\n2、主导过大型复杂分布式互联网业务系统的设计，有高并发场景下的架构设计和稳定性保障经验； \n3、有过国际化相关研发从业经验；\n\n岗位亮点\n如果你对世界充满好奇心，在这里，你会接触到不同的国家、语言和文化，开拓国际视野，探索异域市场。\n如果你富有冒险精神，在这里，一个个陌生的国家等待你的开发，一个个全新的关卡等待你的挑战。\n如果你渴望快速成长，在这里，你可以经历海外新业务不断发展的过程，不断解锁新技能，持续获得成就感。\n团队积极拥抱AI工作方式，日常研发已全面接入AI Coding工具，并持续探索AI驱动的调度系统智能化实践。\n我们的目标是星辰大海，期待有想法、敢于冒险、渴望快速成长的你加入！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3686975595","sourceKey":"meituan_social","company":"美团","title":"Merchant Operations Expert","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3686975595&jobShareType=1","duty":"Role Summary\n\nAs the Merchant Management for Brazil, you will be the commercial owner of Keeta's strategic partner ecosystem. You will architect and manage high-impact partnerships that drive market expansion and revenue growth. In this entrepreneurial role, you will serve as the primary business interface between Keeta and our key partners, building mutually beneficial relationships that create sustainable competitive advantage.\n\nKey Responsibilities\n\n1. Strategic Partner Development\n\nIdentify, evaluate, and onboard strategic business partners that align with Keeta's growth objectives.\n\nDesign and structure partnership frameworks that maximize value creation for all stakeholders.\n\n2. Portfolio Performance Ownership\n\nOwn the commercial outcomes and market development targets for your partner portfolio.\n\nConduct strategic business reviews to track performance metrics and identify optimization opportunities.\n\n3. Market Intelligence & Growth Strategy\n\nAnalyze market dynamics, competitive landscapes, and partner capabilities to inform strategic decisions.\n\nDevelop data-driven recommendations for market penetration and partnership optimization.\n\n4. Relationship Management & Business Enablement\n\nBuild executive-level relationships with key partner stakeholders.\n\nProvide strategic guidance and operational support to help partners achieve their business objectives.","requirements":"Basic Qualifications\n\nBachelor's degree in Business, Economics, or related field.\n\n3+ years of B2B partnership management, business development, or strategic account management experience.\n\nProven negotiation skills with experience managing complex commercial relationships.\n\nFluent English (written and verbal) for cross-border collaboration.\n\nStrong business acumen with the ability to analyze financial metrics and drive profitability.\n\nPreferred Qualifications\n\nExperience in channel management or building partner ecosystems from ground up.\n\nBackground in on-demand delivery, e-commerce, or logistics where partnership networks are critical for scaling.\n\nMBA or advanced degree with a focus on international business or emerging markets.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\nRole Summary\n\nAs the Merchant Management for Brazil, you will be the commercial owner of Keeta's strategic partner ecosystem. You will architect and manage high-impact partnerships that drive market expansion and revenue growth. In this entrepreneurial role, you will serve as the primary business interface between Keeta and our key partners, building mutually beneficial relationships that create sustainable competitive advantage.\n\nKey Responsibilities\n\n1. Strategic Partner Development\n\nIdentify, evaluate, and onboard strategic business partners that align with Keeta's growth objectives.\n\nDesign and structure partnership frameworks that maximize value creation for all stakeholders.\n\n2. Portfolio Performance Ownership\n\nOwn the commercial outcomes and market development targets for your partner portfolio.\n\nConduct strategic business reviews to track performance metrics and identify optimization opportunities.\n\n3. Market Intelligence & Growth Strategy\n\nAnalyze market dynamics, competitive landscapes, and partner capabilities to inform strategic decisions.\n\nDevelop data-driven recommendations for market penetration and partnership optimization.\n\n4. Relationship Management & Business Enablement\n\nBuild executive-level relationships with key partner stakeholders.\n\nProvide strategic guidance and operational support to help partners achieve their business objectives.\n\n岗位基本要求\nBasic Qualifications\n\nBachelor's degree in Business, Economics, or related field.\n\n3+ years of B2B partnership management, business development, or strategic account management experience.\n\nProven negotiation skills with experience managing complex commercial relationships.\n\nFluent English (written and verbal) for cross-border collaboration.\n\nStrong business acumen with the ability to analyze financial metrics and drive profitability.\n\nPreferred Qualifications\n\nExperience in channel management or building partner ecosystems from ground up.\n\nBackground in on-demand delivery, e-commerce, or logistics where partnership networks are critical for scaling.\n\nMBA or advanced degree with a focus on international business or emerging markets.\n\n岗位亮点\nWhy Join Keeta?\n\nShape the Future of Food Delivery: Be part of a passionate startup team that's building something extraordinary in Brazil. Your work will directly impact how millions of users experience food delivery.\n\nGlobal Insights, Local Impact: Leverage proven market know-how and cross-border best practices from our operations in China, the Middle East, and beyond. You'll have the autonomy of a startup with the strategic depth of an international team.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3925279271","sourceKey":"meituan_social","company":"美团","title":"充电宝渠道经理-东北区域","city":"沈阳市/长春市/吉林市/哈尔滨市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3925279271&jobShareType=1","duty":"1.负责区域内合作商的挖掘和洽谈合作，基于招商政策制定招商规划，跟进招商进展；\n2.通过评估所辖属地实际下沉市场的实际市场情况，结合公司政策和策略，完成属地内的合作商的招募和汰换；\n3.对合作商的团队管理、盈亏状况等方面能给出指导建议，并能在业务运营层面给出有效的落地解决方案；\n4.负责管辖区内市场及行业信息收集反馈。","requirements":"1.专科及以上学历，3年以上到店业务经验或者渠道商管经验；\n2.良好的商务谈判能力，沟通协调能力，能够制定招商规划，对业务结果负责；\n3.具备良好的渠道维护意识，在合作商选、育、用、励、汰环节，具备有效的方法和技巧；\n4.积极乐观，敢于挑战，为人正直，诚实可靠；\n5.能接受区域内长期出差。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.负责区域内合作商的挖掘和洽谈合作，基于招商政策制定招商规划，跟进招商进展；\n2.通过评估所辖属地实际下沉市场的实际市场情况，结合公司政策和策略，完成属地内的合作商的招募和汰换；\n3.对合作商的团队管理、盈亏状况等方面能给出指导建议，并能在业务运营层面给出有效的落地解决方案；\n4.负责管辖区内市场及行业信息收集反馈。\n\n岗位基本要求\n1.专科及以上学历，3年以上到店业务经验或者渠道商管经验；\n2.良好的商务谈判能力，沟通协调能力，能够制定招商规划，对业务结果负责；\n3.具备良好的渠道维护意识，在合作商选、育、用、励、汰环节，具备有效的方法和技巧；\n4.积极乐观，敢于挑战，为人正直，诚实可靠；\n5.能接受区域内长期出差。\n\n具备以下条件优先\n具备同行业渠道管理经验者或互联网渠道管理经验者优先\n\n岗位亮点\n1.销售+管理的工作属性，同序列更高的岗位称重；\n2.成熟且上升的行业，有无限可能。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3482124890","sourceKey":"meituan_social","company":"美团","title":"Keemart Area Manager","city":"利雅得/吉达","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3482124890&jobShareType=1","duty":"1. Responsible for the day-to-day operational management of multiple stores within the Riyadh region, including goods receipt and dispatch, and warehouse management.\n2. Ensures timely delivery of merchandise to multiple regional stores, coordinates interdepartmental collaboration to enhance fulfilment efficiency.\n3. Oversees recruitment, training, and management of personnel across multiple regional stores; guides team members, develops work plans and procedures to improve team performance.\n4. Oversee warehouse management across multiple regional outlets, encompassing goods inbound/outbound processing, inventory control, and stock loss mitigation.\n5. Analyse and resolve operational issues arising within regional logistics to guarantee seamless supply chain execution.","requirements":"1. Bachelor's degree or higher, preferably in Logistics Management or Retail Operations Management.\n2. Minimum 3 years' experience in logistics operations and retail store management; candidates with team management experience preferred.\n3. Thorough understanding of logistics operational procedures and relevant regulations, with strong problem-solving capabilities.\n4. Excellent communication skills and teamwork ethos, with the ability to effectively coordinate interdepartmental collaboration.\n5. Strong resilience and adaptability, maintaining a positive work attitude in high-pressure environments.\n6. English as the primary working language.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. Responsible for the day-to-day operational management of multiple stores within the Riyadh region, including goods receipt and dispatch, and warehouse management.\n2. Ensures timely delivery of merchandise to multiple regional stores, coordinates interdepartmental collaboration to enhance fulfilment efficiency.\n3. Oversees recruitment, training, and management of personnel across multiple regional stores; guides team members, develops work plans and procedures to improve team performance.\n4. Oversee warehouse management across multiple regional outlets, encompassing goods inbound/outbound processing, inventory control, and stock loss mitigation.\n5. Analyse and resolve operational issues arising within regional logistics to guarantee seamless supply chain execution.\n\n岗位基本要求\n1. Bachelor's degree or higher, preferably in Logistics Management or Retail Operations Management.\n2. Minimum 3 years' experience in logistics operations and retail store management; candidates with team management experience preferred.\n3. Thorough understanding of logistics operational procedures and relevant regulations, with strong problem-solving capabilities.\n4. Excellent communication skills and teamwork ethos, with the ability to effectively coordinate interdepartmental collaboration.\n5. Strong resilience and adaptability, maintaining a positive work attitude in high-pressure environments.\n6. English as the primary working language.\n\n岗位亮点\n1. Offer extensive experience in regional multi-store logistics, warehousing and shop operations management, providing an excellent platform for personal career development.\n2. Be able to participate in and drive the stable development of logistics operations in the Riyadh region, contributing to the company's business growth.\n3. Have the opportunity to lead team members in achieving personal and team objectives, fostering mutual growth and development.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3751279174","sourceKey":"meituan_social","company":"美团","title":"客户组-大客户销售","city":"北京市/上海市/深圳市/南京市/武汉市/成都市/郑州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3751279174&jobShareType=1","duty":"1、对主题乐园景区等合作资源进行整合，合作项目的具体实施和协调；\n2、针对公司销售任务目标，制定所负责景区的策略，进行拆解分类，过程管理，复盘优化；\n3、通过公司内部的营销工具，整合站内外资源，带领团队确保所负责区域的景区产品的竞争优势，包括但不限于预订条款、价格、库存、货架展示等；\n4、与公司各部门协同配合，及时处理工作中出现的各类问题，并持续优化和改善；","requirements":"1、本科及以上学历；\n2、2年以上销售管理工作经验，有旅游行业2-3年从业经验，对景区线下市场的拓展有一定经验者优先，有景区营销管理经验者优先，有主题乐园景区运营与合作经验优先，有互联网销售从业经验者优先；\n3、具备较强数据分析能力，可熟练运用各类主流办公软件；                 \n4、具备极强的商务谈判、策略制定、过程把控、结果达成及复盘能力；\n5、能够适应出差或异地调动工作；\n6、具备极强的攻坚能力与韧劲；\n7、对线下市场的拓展有一定经验和能力；","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、对主题乐园景区等合作资源进行整合，合作项目的具体实施和协调；\n2、针对公司销售任务目标，制定所负责景区的策略，进行拆解分类，过程管理，复盘优化；\n3、通过公司内部的营销工具，整合站内外资源，带领团队确保所负责区域的景区产品的竞争优势，包括但不限于预订条款、价格、库存、货架展示等；\n4、与公司各部门协同配合，及时处理工作中出现的各类问题，并持续优化和改善；\n\n岗位基本要求\n1、本科及以上学历；\n2、2年以上销售管理工作经验，有旅游行业2-3年从业经验，对景区线下市场的拓展有一定经验者优先，有景区营销管理经验者优先，有主题乐园景区运营与合作经验优先，有互联网销售从业经验者优先；\n3、具备较强数据分析能力，可熟练运用各类主流办公软件；                 \n4、具备极强的商务谈判、策略制定、过程把控、结果达成及复盘能力；\n5、能够适应出差或异地调动工作；\n6、具备极强的攻坚能力与韧劲；\n7、对线下市场的拓展有一定经验和能力；\n\n岗位亮点\n大客户销售序列发展，未来发展路径有专业线与管理线","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3043132559","sourceKey":"meituan_social","company":"美团","title":"华南战区充电宝BD","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3043132559&jobShareType=1","duty":"1、面向本地商户，负责美团充电宝产品的销售和运营工作，并且免费为商家提供营销活动的策略支持服务；\n2、收集商户及用户对于充电宝产品的使用情况反馈，并及时协助解决使用过程中遇到的问题；\n3、与公司各部门配合，及时处理反馈市场信息，协助提升运营效率，提高用户满意度；\n4、与客户建立高价值合作关系，维护客情。","requirements":"1、2年及以上的销售经验，并有良好销售业绩，有互联网销售经验者优先；\n2、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n3、富有激情和创新理念，追求个人职业发展和公司利益的双赢，注重职业升华机遇和优质工作氛围；\n4、具备较强的人际沟通能力，及逻辑思维能力；为人正直，诚实可靠；\n5、适应互联网行业的快速发展，精力充沛，具备在压力下出色完成任务的能力。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1、面向本地商户，负责美团充电宝产品的销售和运营工作，并且免费为商家提供营销活动的策略支持服务；\n2、收集商户及用户对于充电宝产品的使用情况反馈，并及时协助解决使用过程中遇到的问题；\n3、与公司各部门配合，及时处理反馈市场信息，协助提升运营效率，提高用户满意度；\n4、与客户建立高价值合作关系，维护客情。\n\n岗位基本要求\n1、2年及以上的销售经验，并有良好销售业绩，有互联网销售经验者优先；\n2、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n3、富有激情和创新理念，追求个人职业发展和公司利益的双赢，注重职业升华机遇和优质工作氛围；\n4、具备较强的人际沟通能力，及逻辑思维能力；为人正直，诚实可靠；\n5、适应互联网行业的快速发展，精力充沛，具备在压力下出色完成任务的能力。\n\n岗位亮点\n1、清晰的岗位培训和职业发展路径；\n2、透明公平的晋升机制和发展机会；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3899994632","sourceKey":"meituan_social","company":"美团","title":"生产运营总监","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3899994632&jobShareType=1","duty":"1.加工运营体系搭建与优化\n1）主导生鲜品类的库内加工全流程设计（分拣、清洗、切割、包装、贴标等），确保符合平台品控标准与履约时效要求。\n2）建立标准化加工SOP，管理损耗、效率、成本、良品率等核心指标，推动持续改进。\n3）通过调整现场布局、动线规划及设备选型，提升人效与坪效。\n2.新模式创新与落地\n1）探索新品类或新型加工模式，主导试点验证与规模化复制。\n2）结合需求，对新模式的加工工艺和加工品质持续优化。\n3.供应链协同与资源整合\n1）协同采购团队制定原料验收标准，优化加工原料供给稳定性与成本结构。\n2）联动一线兄弟团队，确保加工-仓储-配送环节无缝衔接，保障商品鲜度。","requirements":"1.本科及以上学历，供应链管理、物流管理、精益、食品工程、农业相关专业优先。\n2.8年以上生鲜加工管理经验，其中3年以上头部生鲜电商/大型商超/中央厨房加工中心负责人经历。\n3.精通果蔬加工工艺、保鲜技术及损耗控制方法论，熟悉冷链加工环境管理。\n4.具备从0-1规划并落地新加工能力的案例，能结合业务场景设计高品质、低损耗的加工解决方案。\n5.具备指标驱动的意识，有指标设计和运营的能力。\n6.熟练使用WMS/ERP系统，具备数据分析能力（SQL/Python加分）。\n7.对生鲜品质有更高追求，适应快节奏的工作环境。\n8. 掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.加工运营体系搭建与优化\n1）主导生鲜品类的库内加工全流程设计（分拣、清洗、切割、包装、贴标等），确保符合平台品控标准与履约时效要求。\n2）建立标准化加工SOP，管理损耗、效率、成本、良品率等核心指标，推动持续改进。\n3）通过调整现场布局、动线规划及设备选型，提升人效与坪效。\n2.新模式创新与落地\n1）探索新品类或新型加工模式，主导试点验证与规模化复制。\n2）结合需求，对新模式的加工工艺和加工品质持续优化。\n3.供应链协同与资源整合\n1）协同采购团队制定原料验收标准，优化加工原料供给稳定性与成本结构。\n2）联动一线兄弟团队，确保加工-仓储-配送环节无缝衔接，保障商品鲜度。\n\n岗位基本要求\n1.本科及以上学历，供应链管理、物流管理、精益、食品工程、农业相关专业优先。\n2.8年以上生鲜加工管理经验，其中3年以上头部生鲜电商/大型商超/中央厨房加工中心负责人经历。\n3.精通果蔬加工工艺、保鲜技术及损耗控制方法论，熟悉冷链加工环境管理。\n4.具备从0-1规划并落地新加工能力的案例，能结合业务场景设计高品质、低损耗的加工解决方案。\n5.具备指标驱动的意识，有指标设计和运营的能力。\n6.熟练使用WMS/ERP系统，具备数据分析能力（SQL/Python加分）。\n7.对生鲜品质有更高追求，适应快节奏的工作环境。\n8. 掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n小象业务有较好的发展前景，加工团队在在不断建设新能力拓展新领域，对员工的发展非常利好。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3235913691","sourceKey":"meituan_social","company":"美团","title":"口腔SKA大客户经理（北京、上海）","city":"北京市/上海市/重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3235913691&jobShareType=1","duty":"1、 对重点客户的深度合作和相关业绩负责，能够和客户建立全方位战略性的合作关系；\n2、 对客户需求负责，能够深刻理解客户的经营逻辑，针对性给到解决方案。\n3、 整合内外部资源，挖掘端内场景机会，深化客户服务和营销能力的建设，并能够整合、输出、复制经验，沉淀标准工作流程和数据化的方法论；\n4、 通过客户的深度合作，提升客户在平台的资源投入，并提升客户平台成交在整体行业中的占比；\n5、 联合商户打造营销大事件，制定落地方案和传播策略，为平台和客户沉淀更多能力，配合市场团队推动双方品牌形象的打造，提升平台影响力和品牌美誉度。","requirements":"1、 本科以上学历，3-5年以上互联网大客商业化工作经验；具备广告等行业经验优先，有咨询公司背景优先；\n2、 具备良好的业务开发、拓展、谈判能力，有敏锐的洞察和分析能力，突出的沟通表达能力；\n3、 有大流量及预算具体操盘经验和成熟的运营方法论，有丰富的媒介策划和营销策划经验者优先；\n4、 对于互联网平台有深度的理解，对于消费者心态、客户关系管理、品牌主需求、行业竞争现状和广告策略等有深度的理解。\n5、 敬业度高，自我驱动性强，目标感强，结果导向。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1、 对重点客户的深度合作和相关业绩负责，能够和客户建立全方位战略性的合作关系；\n2、 对客户需求负责，能够深刻理解客户的经营逻辑，针对性给到解决方案。\n3、 整合内外部资源，挖掘端内场景机会，深化客户服务和营销能力的建设，并能够整合、输出、复制经验，沉淀标准工作流程和数据化的方法论；\n4、 通过客户的深度合作，提升客户在平台的资源投入，并提升客户平台成交在整体行业中的占比；\n5、 联合商户打造营销大事件，制定落地方案和传播策略，为平台和客户沉淀更多能力，配合市场团队推动双方品牌形象的打造，提升平台影响力和品牌美誉度。\n\n岗位基本要求\n1、 本科以上学历，3-5年以上互联网大客商业化工作经验；具备广告等行业经验优先，有咨询公司背景优先；\n2、 具备良好的业务开发、拓展、谈判能力，有敏锐的洞察和分析能力，突出的沟通表达能力；\n3、 有大流量及预算具体操盘经验和成熟的运营方法论，有丰富的媒介策划和营销策划经验者优先；\n4、 对于互联网平台有深度的理解，对于消费者心态、客户关系管理、品牌主需求、行业竞争现状和广告策略等有深度的理解。\n5、 敬业度高，自我驱动性强，目标感强，结果导向。\n\n岗位亮点\n超级大客维护、大客户体系搭建、帮助客户成功","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3111549479","sourceKey":"meituan_social","company":"美团","title":"口腔KA大客户销售经理（深圳）","city":"广州市/深圳市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3111549479&jobShareType=1","duty":"1.负责医疗行业大客户的合作和管理，通过市场调研和客户沟通，建立并维护与目标客户高层的良好合作关系。\n2.根据业务目标，制定有效的策略方案，达成深度业务合作，提升客户产值。\n3.负责开展市场信息收集、分析和整理，为公司决策提供参考依据。\n4.负责协调内部资源，与产品、运营、市场等部门紧密合作，推动项目的顺利进行。","requirements":"1.大学本科以上学历，医学、市场营销、商务管理等相关专业优先。\n2.具备5年以上医疗行业大客户销售经验，熟悉互联网行业、医疗行业市场和产品，熟悉各类销售渠道和销售技巧。\n3.具备良好的沟通和谈判能力，能够与高层管理人员进行有效沟通和合作。\n4.具备良好的逻辑思维和问题解决能力，能够独立思考和解决工作中的各种问题。\n5.具备较强的抗压能力和应变能力，能够在高强度的工作环境下保持良好的工作状态。\n6.知名互联网平台企业工作经验者，有互联网广告销售运营的相关经验优先。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.负责医疗行业大客户的合作和管理，通过市场调研和客户沟通，建立并维护与目标客户高层的良好合作关系。\n2.根据业务目标，制定有效的策略方案，达成深度业务合作，提升客户产值。\n3.负责开展市场信息收集、分析和整理，为公司决策提供参考依据。\n4.负责协调内部资源，与产品、运营、市场等部门紧密合作，推动项目的顺利进行。\n\n岗位基本要求\n1.大学本科以上学历，医学、市场营销、商务管理等相关专业优先。\n2.具备5年以上医疗行业大客户销售经验，熟悉互联网行业、医疗行业市场和产品，熟悉各类销售渠道和销售技巧。\n3.具备良好的沟通和谈判能力，能够与高层管理人员进行有效沟通和合作。\n4.具备良好的逻辑思维和问题解决能力，能够独立思考和解决工作中的各种问题。\n5.具备较强的抗压能力和应变能力，能够在高强度的工作环境下保持良好的工作状态。\n6.知名互联网平台企业工作经验者，有互联网广告销售运营的相关经验优先。\n\n具备以下条件优先\n医疗行业经验，医美、医疗口腔上游厂家优先\n\n岗位亮点\n1.有机会在口腔行业大客户销售领域展示个人能力和实现职业发展；\n2.薪资福利优厚，提供良好的晋升空间和职业发展通道；\n3.公司氛围轻松和谐，提供专业的培训和发展机会，打造专业销售团队。\n4.与口腔行业头部客户关键KP对话合作，积累优质行业人脉。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3881018027","sourceKey":"meituan_social","company":"美团","title":"小象超市-鲜花绿植采购","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3881018027&jobShareType=1","duty":"1.采购策略：立足品类&区域销售场景，拆解销售目标、毛利、品质客诉和商品好评率等指标，结合商品结构、品级、市场价格波动趋势，搭建品类、商品、价格运营体系；\n2.供应商管理：以商品品质为核心，搭建类目供应商与经营范围体系，搭建供应商拿货渠道、价格、品质、配合度为评估模型，统筹基地和加工商招商及全链路维护。\n3.商品管理：洞察用户购买意识，结合商品销售周期，按照品类、品种、价格带、季节性、销量分层等多维度，制定商品选品计划和成本优化策略；发展核心品类及爆品挖掘，制定健康的商品管理sop,在采购成本、品质、出清损耗、好评率&客诉率等方面做商品全生命周期管理。\n4.活动运营：贴合平台大促节奏和品类特征，整合各协同部门资源，统筹销售行动计划-方案落地-营销协同-数据监控-突发情况处理-活动复盘的执行。\n5.数据分析：搭建全链路运营指标监控体系，拆解如销售、毛利、动销、转化、客诉等多维度关键指标的达成链路及识别异动并优化。","requirements":"1.有5年以上鲜花或任何生鲜品类采购或运营经验，有实体超市采购、互联网平台运营、农业院校优秀毕业生优先；\n2.关注市场动向，对消费者购买趋势具备敏锐力。具备优秀的品商管理能力和商务谈判能力；\n3.有较强的逻辑思维，有数据sense，通过数据分析发现问题，输出落地解决方案，为负责业务板块拿结果；\n4.学习能力强，执行力强，有较强的沟通协调、资源整合及项目管理能力。\n5.掌握基本的AI工具，使用工具提升工作流程效率","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.采购策略：立足品类&区域销售场景，拆解销售目标、毛利、品质客诉和商品好评率等指标，结合商品结构、品级、市场价格波动趋势，搭建品类、商品、价格运营体系；\n2.供应商管理：以商品品质为核心，搭建类目供应商与经营范围体系，搭建供应商拿货渠道、价格、品质、配合度为评估模型，统筹基地和加工商招商及全链路维护。\n3.商品管理：洞察用户购买意识，结合商品销售周期，按照品类、品种、价格带、季节性、销量分层等多维度，制定商品选品计划和成本优化策略；发展核心品类及爆品挖掘，制定健康的商品管理sop,在采购成本、品质、出清损耗、好评率&客诉率等方面做商品全生命周期管理。\n4.活动运营：贴合平台大促节奏和品类特征，整合各协同部门资源，统筹销售行动计划-方案落地-营销协同-数据监控-突发情况处理-活动复盘的执行。\n5.数据分析：搭建全链路运营指标监控体系，拆解如销售、毛利、动销、转化、客诉等多维度关键指标的达成链路及识别异动并优化。\n\n岗位基本要求\n1.有5年以上鲜花或任何生鲜品类采购或运营经验，有实体超市采购、互联网平台运营、农业院校优秀毕业生优先；\n2.关注市场动向，对消费者购买趋势具备敏锐力。具备优秀的品商管理能力和商务谈判能力；\n3.有较强的逻辑思维，有数据sense，通过数据分析发现问题，输出落地解决方案，为负责业务板块拿结果；\n4.学习能力强，执行力强，有较强的沟通协调、资源整合及项目管理能力。\n5.掌握基本的AI工具，使用工具提升工作流程效率\n\n具备以下条件优先\n生鲜行业内头部企业相关岗位从业经验\n\n岗位亮点\n1.能锻炼在前置仓场景下零售+科技业务模式、全链路商品管理及覆盖国内一线城市的业务操盘与实践。\n2.牵头全年各关键营销节点活动项目，足够的个人专业度和团队协作能力的展示机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3464484946","sourceKey":"meituan_social","company":"美团","title":"美团骑行-运营主管-南昌","city":"南昌市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3464484946&jobShareType=1","duty":"岗位职责：\n1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2.通过实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4.配合政府部门对城市运营问题进行管理；\n5.协助运营经理管理运营团队，提升团队工作效率和结果。\n6.具备主导项目推进和闭环的能力，协调沟通能力，资源整合能力。","requirements":"1.本科及以上学历，2年以上团队管理经验，善于用开拓性思维解决问题；\n2.有互联网线下运营、快消行业、物流行业、维修经验者优先；\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作；","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n岗位职责：\n1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2.通过实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4.配合政府部门对城市运营问题进行管理；\n5.协助运营经理管理运营团队，提升团队工作效率和结果。\n6.具备主导项目推进和闭环的能力，协调沟通能力，资源整合能力。\n\n岗位基本要求\n1.本科及以上学历，2年以上团队管理经验，善于用开拓性思维解决问题；\n2.有互联网线下运营、快消行业、物流行业、维修经验者优先；\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作；\n\n岗位亮点\n部门介绍：\n美团骑行事业部隶属于美团平台，是美团出行板块重要的组成部分。骑行业务在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，也为城市提供了可持续发展的智能解决方案。\n美团单车在为城市居民提供通勤接驳服务，满足用户3公里以内的出行需求，美团电单车满足广大用户8公里以上的绿色出行需求，单车和电单车为城市居民地中短途出行提供了高效、低碳、便捷的出行方案。通过美团单车、电单车业务，美团为用户提供全场景消费体验，继续围绕公司使命“帮大家吃得更好，生活更好”。\n\n岗位亮点：\n加入我们，你将成为骑行业务的推动者和建设者，这里有证明自己的平台、向上奋斗的团队、追求卓越的伙伴和丰厚的激励回报。欢迎加入！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3167054220","sourceKey":"meituan_social","company":"美团","title":"商业分析专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3167054220&jobShareType=1","duty":"1. 监控外卖业务经营情况，以专题形式针对某一问题、机会点进行深入分析，输出有业务价值的洞察发现，形成研究报告。\n2. 聚焦业务增长或策略创新，可以清晰定义和拆解问题、搭建研究思路，输出有洞察力的分析报告，助力业务在增长机会挖掘及核心问题解决方向取得突破。\n3. 参与外卖指标框架搭建，能完成供给/用户等模块的指标洞察及建设，灵敏有效的反映业务发展变化。","requirements":"1. 本科学历或以上，数学、统计学、经济类或商科相关专业背景；\n2. 7年或以上互联网商业分析或咨询公司工作经验，有商品/品类研究、用户/流量分析经验者优先；\n3. 具有良好的商业洞察及严谨的逻辑思维，能结构化拆解问题并完成分析，推动问题解决；\n4. 熟练掌握常用的数据分析工具，具有扎实的梳理统计基本功者优先；\n5. 具有较强的主观能动性、执行能力、沟通协同能力，主人翁意识强。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1. 监控外卖业务经营情况，以专题形式针对某一问题、机会点进行深入分析，输出有业务价值的洞察发现，形成研究报告。\n2. 聚焦业务增长或策略创新，可以清晰定义和拆解问题、搭建研究思路，输出有洞察力的分析报告，助力业务在增长机会挖掘及核心问题解决方向取得突破。\n3. 参与外卖指标框架搭建，能完成供给/用户等模块的指标洞察及建设，灵敏有效的反映业务发展变化。\n\n岗位基本要求\n1. 本科学历或以上，数学、统计学、经济类或商科相关专业背景；\n2. 7年或以上互联网商业分析或咨询公司工作经验，有商品/品类研究、用户/流量分析经验者优先；\n3. 具有良好的商业洞察及严谨的逻辑思维，能结构化拆解问题并完成分析，推动问题解决；\n4. 熟练掌握常用的数据分析工具，具有扎实的梳理统计基本功者优先；\n5. 具有较强的主观能动性、执行能力、沟通协同能力，主人翁意识强。\n\n岗位亮点\n1. 支持美团核心业务，参与外卖整体的经营分析和策略BP，培养良好的全局观、思维高度和完善的分析框架。\n2. 团队专业性强，氛围良好开放，能够帮助同学快速成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2603623366","sourceKey":"meituan_social","company":"美团","title":"AI工程高阶岗位","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2603623366&jobShareType=1","duty":"岗位职责：\n1.参与美团机器学习平台的机器学习基础架构；\n2.负责异构计算的高性能训练引擎，推理引擎、图学习引擎等核心引擎的研发；\n3.负责从特征生产、数据分发、模型训练、模型推理上线等机器学习全链条优化。","requirements":"1.对技术有着永无止境的追求，自认为是技术Geek，具备很强的编写代码和解决问题能力；\n2.有C++/Python中大型项目开发经验（至少熟练应用一种）， 并对高并发/分布式系统有开发经验。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n岗位职责：\n1.参与美团机器学习平台的机器学习基础架构；\n2.负责异构计算的高性能训练引擎，推理引擎、图学习引擎等核心引擎的研发；\n3.负责从特征生产、数据分发、模型训练、模型推理上线等机器学习全链条优化。\n\n岗位基本要求\n1.对技术有着永无止境的追求，自认为是技术Geek，具备很强的编写代码和解决问题能力；\n2.有C++/Python中大型项目开发经验（至少熟练应用一种）， 并对高并发/分布式系统有开发经验。\n\n岗位亮点\n1.有机会全身心地参与美团机器学习平台的建设，和团队一起对机器学习场景工作流进行全新的升级、再造；\n2.能在急速发展的业务当中，建立对深度学习的认知，构建完整的宏观图景；\n3.能和多元化背景的团队技术大牛一起，综合学习，共同进步。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3758011281","sourceKey":"meituan_social","company":"美团","title":"城市BD","city":"成都市/重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3758011281&jobShareType=1","duty":"岗位职责：\n1、维护存量客户的客情关系，通过对门店问题的诊断，及时进行沟通反馈，帮助商家在关键数据上进行增长，保证CTR与CVR，对商户ROI负责。\n2、对已合作美团的商户但并未合作广告产品的客户进行新签，通过管理商家预算分阶段的计划投放，撬动商家自然流量，保证广告收入。\n3、对行业有深刻理解，能够通过数据得出有效结论，在行业的新玩法上有自己的理解，并不断尝试。\n4、能够站在城市的视角上通过数据分析和大家进行经验共享和方法论输出，对于商圈、行业健康度提出自己的意见，并按照策略进行业务流程优化，并执行。","requirements":"1、本科学历及以上学历为佳，大专学历，需一年及以上的销售经验，销冠为佳，或拥有良好销售业绩，有互联网销售经验者优先，高潜应届生同学亦可。\n2、聪明伶俐，应变能力强，有明显的晋升想法，有过硬的业务能力。\n3、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和正确的企图心；\n4、具备较强的市场分析能力，商务谈判能力，人际沟通能力，及逻辑思维能力；\n5、适应互联网行业的快速发展，精力充沛，具备出色完成任务的能力。\n6、心态乐观、为人正直、自主目标感强；","description":"部门介绍\n商业增值部是服务于美团核心本地商业客户的增值服务平台，覆盖餐饮、即时零售、医药、休闲娱乐、丽人医美、生活服务、酒旅度假等业务领域。我们致力于构建健康的本地商业生态，通过为平台客户和消费者提供符合其需求的多元、便捷、高效的商业产品和服务，帮助生态伙伴提高效率、优化经营、实现持续健康发展，推动本地商业数字化营销的发展，促进商业生态繁荣。作为本地商业的头部平台，我们为产品、运营、商务、技术、商业分析等领域人才提供广阔的发展空间。诚邀你加入美团商业增值团队，共筑本地商业的健康繁荣生态！\n\n岗位职责\n岗位职责：\n1、维护存量客户的客情关系，通过对门店问题的诊断，及时进行沟通反馈，帮助商家在关键数据上进行增长，保证CTR与CVR，对商户ROI负责。\n2、对已合作美团的商户但并未合作广告产品的客户进行新签，通过管理商家预算分阶段的计划投放，撬动商家自然流量，保证广告收入。\n3、对行业有深刻理解，能够通过数据得出有效结论，在行业的新玩法上有自己的理解，并不断尝试。\n4、能够站在城市的视角上通过数据分析和大家进行经验共享和方法论输出，对于商圈、行业健康度提出自己的意见，并按照策略进行业务流程优化，并执行。\n\n岗位基本要求\n1、本科学历及以上学历为佳，大专学历，需一年及以上的销售经验，销冠为佳，或拥有良好销售业绩，有互联网销售经验者优先，高潜应届生同学亦可。\n2、聪明伶俐，应变能力强，有明显的晋升想法，有过硬的业务能力。\n3、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和正确的企图心；\n4、具备较强的市场分析能力，商务谈判能力，人际沟通能力，及逻辑思维能力；\n5、适应互联网行业的快速发展，精力充沛，具备出色完成任务的能力。\n6、心态乐观、为人正直、自主目标感强；\n\n岗位亮点\n1、了解市场优先动向熟悉餐饮行业，与餐饮行业老板做朋友广阔人脉资源；\n2、一群有理想的同事、业余时间活动丰富。\n3、互联网公司节奏快！是这能让你快速发展，快速提升自己的平台；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3550372443","sourceKey":"meituan_social","company":"美团","title":"多模态工程开发专家","city":"上海市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3550372443&jobShareType=1","duty":"1）负责构建智能交互、语音视觉、多模态方向大模型的全链路工程优化，包括模型部署和性能优化、模型蒸馏加速、异构计算推理优化等；2）协同跨职能团队（如产品、算法等）共建好用的产品工具，围绕公司各个业务在视觉、语音、多模、智能交互各个场景的应用，打通内外生态，提供创新解决方案。\n\n3）负责面向内容生成和多模态人机交互的前瞻技术储备，确保团队在新技术应用和创新上处于行业前沿。\n\n4）提升公司各部门对AI应用的使用效率和易用性，持续降低使用门槛和成本，支持内部角色的AI工具使用。\n\n5）推动平台化服务的构建，优化现有智能应用的性能与稳定性，确保产品工具的高效落地。","requirements":"1）具备一线大厂大规模算法模型工程经验和多端侧开发管理经验。\n\n2）深刻理解语音识别、计算机视觉、自然语言处理、多模态各技术路线，具有相关平台的开发与应用经验。\n\n3）熟悉多模态数据流处理、跨模态特征融合和信息整合的架构设计，能够设计高效的数据管道和支持跨模态的AI训练与推理框架。\n\n4）熟悉一流技术公司的开发流程和工作方法，具备良好的编码风格和技术能力，具备培养团队技术氛围的使命感。\n\n5）具备优秀的团队管理和领导能力，能够激励团队成员，推动跨部门协作。\n\n6）强烈的责任心与业务协作精神，能够高效推进项目落地，具备良好的沟通能力和同理心。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1）负责构建智能交互、语音视觉、多模态方向大模型的全链路工程优化，包括模型部署和性能优化、模型蒸馏加速、异构计算推理优化等；2）协同跨职能团队（如产品、算法等）共建好用的产品工具，围绕公司各个业务在视觉、语音、多模、智能交互各个场景的应用，打通内外生态，提供创新解决方案。\n\n3）负责面向内容生成和多模态人机交互的前瞻技术储备，确保团队在新技术应用和创新上处于行业前沿。\n\n4）提升公司各部门对AI应用的使用效率和易用性，持续降低使用门槛和成本，支持内部角色的AI工具使用。\n\n5）推动平台化服务的构建，优化现有智能应用的性能与稳定性，确保产品工具的高效落地。\n\n岗位基本要求\n1）具备一线大厂大规模算法模型工程经验和多端侧开发管理经验。\n\n2）深刻理解语音识别、计算机视觉、自然语言处理、多模态各技术路线，具有相关平台的开发与应用经验。\n\n3）熟悉多模态数据流处理、跨模态特征融合和信息整合的架构设计，能够设计高效的数据管道和支持跨模态的AI训练与推理框架。\n\n4）熟悉一流技术公司的开发流程和工作方法，具备良好的编码风格和技术能力，具备培养团队技术氛围的使命感。\n\n5）具备优秀的团队管理和领导能力，能够激励团队成员，推动跨部门协作。\n\n6）强烈的责任心与业务协作精神，能够高效推进项目落地，具备良好的沟通能力和同理心。\n\n岗位亮点\n引领前沿技术在智能应用领域的落地，致力于构建易用且高效的多模态智能平台。\n\n推动公司内部智能平台的普及，降低AI应用成本，提升团队协作效率。\n\n与跨部门团队紧密合作，推动创新方案的实施，支持公司在AI应用领域的长远发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3721177184","sourceKey":"meituan_social","company":"美团","title":"视频创作算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3721177184&jobShareType=1","duty":"1. 负责视频创作相关的算法研发，包括：图像/视频生成、多模态理解、智能化剪辑、交互式Agent等；\n\n2. 结合实际业务需求，负责视频创作算法在各个场景的落地。","requirements":"1. 计算机、数学、统计学、人工智能等相关专业，硕士及以上学历，3年以上工作经验；\n\n2. 在视觉、语言模型、多模态模型一个或多个领域有研究，有实际微调和应用经验；\n\n3. 动手能力强, 具有熟练的算法和编程能力，熟悉深度学习框架；\n\n4. 善于利用各类技术解决复杂的实际问题，有良好的沟通表达能力、团队协作能力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责视频创作相关的算法研发，包括：图像/视频生成、多模态理解、智能化剪辑、交互式Agent等；\n\n2. 结合实际业务需求，负责视频创作算法在各个场景的落地。\n\n岗位基本要求\n1. 计算机、数学、统计学、人工智能等相关专业，硕士及以上学历，3年以上工作经验；\n\n2. 在视觉、语言模型、多模态模型一个或多个领域有研究，有实际微调和应用经验；\n\n3. 动手能力强, 具有熟练的算法和编程能力，熟悉深度学习框架；\n\n4. 善于利用各类技术解决复杂的实际问题，有良好的沟通表达能力、团队协作能力。\n\n具备以下条件优先\n1. 具有行业影响力的开源项目、高质量论文、竞赛经历；\n\n2. 在AIGC方向有大规模商业落地经验。\n\n岗位亮点\n1. 以公司实际业务为依托，场景覆盖广，有完善的技术转化和落地机制；\n\n2. 深度参与视频创作全链路，多技术方向交叉领域，具有较高的技术挑战性和创新空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3617556731","sourceKey":"meituan_social","company":"美团","title":"广深城市经理-餐饮SaaS","city":"深圳市/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3617556731&jobShareType=1","duty":"1.负责南部战区业务开发工作，制定并实施业务拓展计划。\n2.管理团队成员，指导他们完成销售任务，提升业绩。\n3.负责与客户沟通，了解客户需求，推动业务发展。\n4.协调内部资源，确保项目顺利进行。","requirements":"1.大学专科及以上学历，具备相关专业背景。\n2.具备3年以上业务开发或销售经验，有团队管理经验者优先。\n3.具备较强的沟通能力、团队合作能力。\n4.熟悉南部战区市场，有良好的客户资源者优先。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1.负责南部战区业务开发工作，制定并实施业务拓展计划。\n2.管理团队成员，指导他们完成销售任务，提升业绩。\n3.负责与客户沟通，了解客户需求，推动业务发展。\n4.协调内部资源，确保项目顺利进行。\n\n岗位基本要求\n1.大学专科及以上学历，具备相关专业背景。\n2.具备3年以上业务开发或销售经验，有团队管理经验者优先。\n3.具备较强的沟通能力、团队合作能力。\n4.熟悉南部战区市场，有良好的客户资源者优先。\n\n岗位亮点\n1.可以在南部战区这个高发展地区展示自己的能力，获得更多的发展机会。\n2.有机会带领团队完成挑战性的业务目标，实现个人和团队的成长。\n3.公司提供良好的晋升机制和薪酬福利，帮助员工实现职业发展目标。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3524445451","sourceKey":"meituan_social","company":"美团","title":"Keeta技术 - 高级Java开发工程师(智能客服方向)","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3524445451&jobShareType=1","duty":"1.负责智能客服工程技术建设，建设大模型工程在客服领域的相关平台；\n2.负责智能客服服务端技术方案设计、需求把控及核心功能开发；\n3.持续提升核心系统在大模型应用层面的性能和质量，保证系统的安全、稳定、快速运行；\n4.借助AI Coding工具提升智能客服系统研发效率，深度参与Agent、RAG等大模型技术在客服场景中的工程落地与持续优化。","requirements":"1.本科以上学历，具备扎实的编程基础和数据结构算法基础，优秀的编程能力和问题解决能力；\n2.3年以上后端开发经验，至少精通一门后台语言如Java/Go，并深入理解面向服务的架构，精通Web后台开发、微服务开发，掌握Linux/MySQL/NoSQL等；\n3.了解LLM相关工程研发知识，包括但不限于Agent、RAG、任务调度、推理加速、评测、PE等；\n4.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；有智能客服、工作流引擎相关从业经验或大模型应用经验者优先。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.负责智能客服工程技术建设，建设大模型工程在客服领域的相关平台；\n2.负责智能客服服务端技术方案设计、需求把控及核心功能开发；\n3.持续提升核心系统在大模型应用层面的性能和质量，保证系统的安全、稳定、快速运行；\n4.借助AI Coding工具提升智能客服系统研发效率，深度参与Agent、RAG等大模型技术在客服场景中的工程落地与持续优化。\n\n岗位基本要求\n1.本科以上学历，具备扎实的编程基础和数据结构算法基础，优秀的编程能力和问题解决能力；\n2.3年以上后端开发经验，至少精通一门后台语言如Java/Go，并深入理解面向服务的架构，精通Web后台开发、微服务开发，掌握Linux/MySQL/NoSQL等；\n3.了解LLM相关工程研发知识，包括但不限于Agent、RAG、任务调度、推理加速、评测、PE等；\n4.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；有智能客服、工作流引擎相关从业经验或大模型应用经验者优先。\n\n具备以下条件优先\n1. 具备智能客服、工作流引擎相关从业经验背景者优先。\n\n2. 有大模型应用相关经验者优先。\n\n3. 有出海应用相关研发经验优先。\n\n岗位亮点\n1.能全面参与国际化业务从0到1的建设过程，可了解国际化业务全貌及系统架构演进；\n2.如果你对世界充满好奇心，在这里，你会接触到不同的国家、语言和文化，开拓国际视野，探索异域市场；\n3.如果你富有冒险精神，在这里，一个个陌生的国家等待你的开发，一个个全新的关卡等待你的挑战；\n4.如果你渴望快速成长，在这里，你可以经历新业务从0到1的过程，不断解锁新技能，持续获得成就感；\n5.团队积极拥抱AI工作方式，日常研发已全面接入AI Coding工具，深度探索大模型驱动的智能客服系统工程化实践；\n6.我们的目标是星辰大海，期待有想法、敢于冒险、渴望快速成长的你加入！让我们一同见证美团国际化的征程！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3602249206","sourceKey":"meituan_social","company":"美团","title":"大模型中台服务后台工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3602249206&jobShareType=1","duty":"1. 大模型接入平台建设\n\n负责构建和维护企业级大模型接入平台，支持内部业务系统快速接入\n集成主流外部大模型服务（OpenAI、Claude、deepseek等）和自部署开源模型服务，提供统一的接入标准\n建立完善的模型版本管理、配置管理和发布流程\n\n2. 中台服务架构设计\n\n基于统一接口标准，构建高可用、高并发的大模型中台服务\n设计实现用户权限分层管理、智能流量调度和服务降级机制\n建立完善的监控告警体系，确保服务稳定性和可观测性\n\n3. Agent生态能力建设\n\n跟踪业界Agent技术发展趋势，持续优化平台能力\n设计面向未来的API架构和能力体系，支持多模态Agent应用的落地\n构建Agent工具链和开发框架，提升开发效率\n\n4. 数据驱动的平台优化\n\n建立大模型使用数据的采集、分析和可视化体系\n基于用户行为和性能数据，持续优化平台架构和服务质量\n制定数据驱动的产品迭代策略，提升用户体验","requirements":"1. 本科及以上学历，3年以上工作经验，3年以上后端系统的开发经验；\n2. 精通Java和数据结构，具有强烈的好奇心，能够发现业务中的痛点，并通过架构改进解决问题；","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 大模型接入平台建设\n\n负责构建和维护企业级大模型接入平台，支持内部业务系统快速接入\n集成主流外部大模型服务（OpenAI、Claude、deepseek等）和自部署开源模型服务，提供统一的接入标准\n建立完善的模型版本管理、配置管理和发布流程\n\n2. 中台服务架构设计\n\n基于统一接口标准，构建高可用、高并发的大模型中台服务\n设计实现用户权限分层管理、智能流量调度和服务降级机制\n建立完善的监控告警体系，确保服务稳定性和可观测性\n\n3. Agent生态能力建设\n\n跟踪业界Agent技术发展趋势，持续优化平台能力\n设计面向未来的API架构和能力体系，支持多模态Agent应用的落地\n构建Agent工具链和开发框架，提升开发效率\n\n4. 数据驱动的平台优化\n\n建立大模型使用数据的采集、分析和可视化体系\n基于用户行为和性能数据，持续优化平台架构和服务质量\n制定数据驱动的产品迭代策略，提升用户体验\n\n岗位基本要求\n1. 本科及以上学历，3年以上工作经验，3年以上后端系统的开发经验；\n2. 精通Java和数据结构，具有强烈的好奇心，能够发现业务中的痛点，并通过架构改进解决问题；\n\n具备以下条件优先\n1.分布式高并发系统的开发经验。\n2.有平台类系统，后端开发相关的研发经验。\n3.有大模型相关项目的研发经验。\n4. 有数据开发相关经验。\n\n岗位亮点\n1. 大模型平台服务入口，技术深度和挑战足够；\n2. 涵盖业务类型广，技术链条深度足够，技术范围广；\n3. 跟踪大模型领域前沿知识，获得实际的业务实施经验；\n4. 团队成员经验丰富，技术卓越，成长环境好；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3536535694","sourceKey":"meituan_social","company":"美团","title":"闪购-高级Java开发工程师（商品方向）","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3536535694&jobShareType=1","duty":"1.完成零售SaaS系统核心的商品模块建设，保证系统符合质量性能要求；\n2.进行需求分析以及主要业务功能的开发，对现有业务模块进行优化；\n3.将业务逻辑拆解清晰，攻克技术难点，支撑业务快速发展；\n4.系统技术优化，提升系统的稳定性、性能和可维护性；\n5.借助AI Coding工具提升商品系统研发效率，探索AI技术在商品管理智能化、业务规则自动配置等场景中的工程落地。","requirements":"1.大学本科以上学历，计算机或相关专业，4年以上Java实际项目开发经验；\n2.有扎实的Java基础，Java多线程、并发以及网络通信有深厚的经验；\n3.熟悉设计模式、OOA/OOD。熟悉主流开源应用框架，如Spring、MyBatis、XML、JSON、Maven等开发技术；\n4.熟悉关系型数据库MySQL等，SQL优化。熟悉Memcached、MongoDB、Redis、HBase等；\n5.熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息、负载均衡等机制和实现；\n6.热爱技术，对技术有不懈的追求，喜欢研究开源代码；\n7.良好的学习能力、团队协作能力和沟通能力；能主动承担压力，态度端正积极，善于思考，能独立分析和解决问题；\n8.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；有电商商品系统或供应链商品系统开发经验者优先。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.完成零售SaaS系统核心的商品模块建设，保证系统符合质量性能要求；\n2.进行需求分析以及主要业务功能的开发，对现有业务模块进行优化；\n3.将业务逻辑拆解清晰，攻克技术难点，支撑业务快速发展；\n4.系统技术优化，提升系统的稳定性、性能和可维护性；\n5.借助AI Coding工具提升商品系统研发效率，探索AI技术在商品管理智能化、业务规则自动配置等场景中的工程落地。\n\n岗位基本要求\n1.大学本科以上学历，计算机或相关专业，4年以上Java实际项目开发经验；\n2.有扎实的Java基础，Java多线程、并发以及网络通信有深厚的经验；\n3.熟悉设计模式、OOA/OOD。熟悉主流开源应用框架，如Spring、MyBatis、XML、JSON、Maven等开发技术；\n4.熟悉关系型数据库MySQL等，SQL优化。熟悉Memcached、MongoDB、Redis、HBase等；\n5.熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息、负载均衡等机制和实现；\n6.热爱技术，对技术有不懈的追求，喜欢研究开源代码；\n7.良好的学习能力、团队协作能力和沟通能力；能主动承担压力，态度端正积极，善于思考，能独立分析和解决问题；\n8.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；有电商商品系统或供应链商品系统开发经验者优先。\n\n具备以下条件优先\n1.有大型互联网或电商企业工作经验优先考虑\n2.参与过电商商品系统、供应链商品系统开发经历者优先\n3.具有toB类复杂业务系统实践开发经验\n\n岗位亮点\n1.从0到1参与新零售业务的系统建设，建设比见证更重要；\n2.全方位深入业务，在全闭环的组织里感受不同职能彼此的输入/输出，你也可以参与业务模式的定义；\n3.大厂的业务规模、业务复杂度以及快速发展所带来的技术挑战，彻底告别在一个小模块修修补补的时代；\n4.深入参与自营零售业务的经营，说不定你后续也知道怎么开店；\n5.团队技术氛围良好，能帮助自我快速提升；\n6.团队深度拥抱AI工作方式，日常研发全面接入AI Coding工具，持续探索AI驱动的SaaS商品系统智能化实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3451275664","sourceKey":"meituan_social","company":"美团","title":"充电宝渠道经理","city":"广州市/深圳市/东莞市/佛山市/珠海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3451275664&jobShareType=1","duty":"1.负责开发并管理美团共享充电宝在安徽、湖南和江西地区的渠道合作伙伴，推动共享充电宝产品在当地市场的拓展和销售业绩的提升。\n2.策划并执行渠道招商活动，寻找合适的合作伙伴，建立和维护与其的良好合作关系，推动合作伙伴的业绩增长。\n3.负责制定并实施渠道管理策略，包括渠道政策、活动等，确保渠道合作伙伴的利益最大化。\n4.跟进渠道合作伙伴的业绩和销售数据，分析市场动态和竞争对手情况，及时调整策略，确保达成销售目标。\n5.协调各部门资源，解决渠道合作伙伴的问题和需求，确保合作伙伴的满意度和忠诚度。\n6.持续关注行业发展趋势，分析市场需求，提出产品改进和推广建议，推动共享充电宝在当地市场的创新和发展。","requirements":"1.专科及以上学历，市场营销、商务管理或相关专业优先考虑。\n2.至少2年以上渠道开发、业务拓展或销售经验，有充电宝、移动电源、共享经济等相关行业经验者优先。\n3.具备较强的市场洞察力和渠道开发能力，熟悉当地市场情况，了解渠道合作伙伴管理和招商的流程。\n4.具备团队合作和协调能力，能够有效管理和激励团队成员，推动团队共同完成销售目标。\n5.具备较强的沟通和谈判能力，能够与合作伙伴建立信任关系，协商合作事宜，解决问题和冲突。\n6.具备良好的数据分析和问题解决能力，能够通过数据分析和市场调研，提出有效的渠道管理和销售策略。\n7.工作积极主动，有较强的责任心和执行力，能够承受一定的工作压力。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.负责开发并管理美团共享充电宝在安徽、湖南和江西地区的渠道合作伙伴，推动共享充电宝产品在当地市场的拓展和销售业绩的提升。\n2.策划并执行渠道招商活动，寻找合适的合作伙伴，建立和维护与其的良好合作关系，推动合作伙伴的业绩增长。\n3.负责制定并实施渠道管理策略，包括渠道政策、活动等，确保渠道合作伙伴的利益最大化。\n4.跟进渠道合作伙伴的业绩和销售数据，分析市场动态和竞争对手情况，及时调整策略，确保达成销售目标。\n5.协调各部门资源，解决渠道合作伙伴的问题和需求，确保合作伙伴的满意度和忠诚度。\n6.持续关注行业发展趋势，分析市场需求，提出产品改进和推广建议，推动共享充电宝在当地市场的创新和发展。\n\n岗位基本要求\n1.专科及以上学历，市场营销、商务管理或相关专业优先考虑。\n2.至少2年以上渠道开发、业务拓展或销售经验，有充电宝、移动电源、共享经济等相关行业经验者优先。\n3.具备较强的市场洞察力和渠道开发能力，熟悉当地市场情况，了解渠道合作伙伴管理和招商的流程。\n4.具备团队合作和协调能力，能够有效管理和激励团队成员，推动团队共同完成销售目标。\n5.具备较强的沟通和谈判能力，能够与合作伙伴建立信任关系，协商合作事宜，解决问题和冲突。\n6.具备良好的数据分析和问题解决能力，能够通过数据分析和市场调研，提出有效的渠道管理和销售策略。\n7.工作积极主动，有较强的责任心和执行力，能够承受一定的工作压力。\n\n岗位亮点\n1.作为美团共享充电宝渠道经理，将有机会参与共享经济行业的发展，推动共享充电宝在安徽、湖南和江西地区的市场拓展和品牌建设。\n2.可以与各类渠道合作伙伴展开合作，提升渠道销售业绩，实现个人和团队的成长和发展。\n3.扁平化管理，团队氛围NICE。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3545041592","sourceKey":"meituan_social","company":"美团","title":"AI高阶工程-大模型推理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3545041592&jobShareType=1","duty":"1. 负责大规模预训练模型（如GPT、BERT、LLM等）的推理系统设计、优化与落地，实现模型在多平台（GPU、CPU、NPU等）上的高效推理。\n2. 针对模型推理场景，深入分析性能瓶颈，主导模型量化、剪枝、蒸馏、结构重参数化等前沿推理加速技术的研究与应用。\n3. 参与大模型推理框架（如TensorRT、ONNX Runtime、OpenVINO、MindSpore等）的开发与优化，提升推理效率与系统稳定性。\n4. 跟踪业界和学术界大模型推理相关前沿技术，推动创新方案在业务中的应用落地。\n5. 与算法、系统、硬件等团队紧密协作，制定端到端的推理优化方案，支撑业务高并发、低延迟的需求。\n6. 负责推理平台的技术难点攻关，解决模型部署、兼容性、资源调度等实际问题。","requirements":"1. 计算机、人工智能、电子工程等相关专业硕士及以上学历，5年以上AI推理/系统优化相关工作经验。\n2. 深入理解主流大模型结构及推理原理，熟悉Transformer、LLM等模型的高效推理优化技术。\n3. 精通至少一种主流深度学习框架（如PyTorch、TensorFlow、MindSpore等）及其推理引擎（如TensorRT、ONNX Runtime等）。\n4. 熟悉模型压缩、量化、剪枝、蒸馏等加速技术，并有实际落地经验。\n5. 扎实的编程能力，精通C++/Python，具备良好的系统调优与性能分析能力。\n6. 有大规模分布式推理、异构计算（GPU/CPU/NPU）或端侧推理部署经验者优先。\n7. 具备良好的团队协作、沟通能力和创新精神，能承担复杂项目的技术攻关任务。\n8. 有相关开源项目贡献、顶会论文发表或大模型推理产品化经验者优先。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责大规模预训练模型（如GPT、BERT、LLM等）的推理系统设计、优化与落地，实现模型在多平台（GPU、CPU、NPU等）上的高效推理。\n2. 针对模型推理场景，深入分析性能瓶颈，主导模型量化、剪枝、蒸馏、结构重参数化等前沿推理加速技术的研究与应用。\n3. 参与大模型推理框架（如TensorRT、ONNX Runtime、OpenVINO、MindSpore等）的开发与优化，提升推理效率与系统稳定性。\n4. 跟踪业界和学术界大模型推理相关前沿技术，推动创新方案在业务中的应用落地。\n5. 与算法、系统、硬件等团队紧密协作，制定端到端的推理优化方案，支撑业务高并发、低延迟的需求。\n6. 负责推理平台的技术难点攻关，解决模型部署、兼容性、资源调度等实际问题。\n\n岗位基本要求\n1. 计算机、人工智能、电子工程等相关专业硕士及以上学历，5年以上AI推理/系统优化相关工作经验。\n2. 深入理解主流大模型结构及推理原理，熟悉Transformer、LLM等模型的高效推理优化技术。\n3. 精通至少一种主流深度学习框架（如PyTorch、TensorFlow、MindSpore等）及其推理引擎（如TensorRT、ONNX Runtime等）。\n4. 熟悉模型压缩、量化、剪枝、蒸馏等加速技术，并有实际落地经验。\n5. 扎实的编程能力，精通C++/Python，具备良好的系统调优与性能分析能力。\n6. 有大规模分布式推理、异构计算（GPU/CPU/NPU）或端侧推理部署经验者优先。\n7. 具备良好的团队协作、沟通能力和创新精神，能承担复杂项目的技术攻关任务。\n8. 有相关开源项目贡献、顶会论文发表或大模型推理产品化经验者优先。\n\n岗位亮点\n围绕公司内主流应用模型进行模型压缩和加速方面的算法和工程探索，面向高效推理场景进行模型结构设计和改造；\n构建高性能、多硬件的统一NTP推理框架，支持自研模型和优秀开源模型的推理，支撑公司内大模型应用的低成本探索。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2353171913","sourceKey":"meituan_social","company":"美团","title":"连锁酒店KA大客户经理","city":"兰州市/乌鲁木齐市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2353171913&jobShareType=1","duty":"为解决未来1-2年的核心问题，这个岗位上的人需要做以下三件事?\n1）提升核心市场酒店竞争规模比，达到大优态势。\n2）同时该岗位在团队、客户之间进行协作，管理好不同的客户关系，提升客情生产力。\n3）同时团队人员末位淘汰，对于该岗位进行查漏补缺。","requirements":"1）定期出差拜访所负责城市酒店的KP（单店店长、多店店长和区域经理），根据其运营策略、客户政策及需求，通过商务洽谈，建立良好的客情，以采购优势的库存和价格，为平台消费者提供性价比更高的产品。\n2）在复杂多变的市场环境中及武器不断迭代的情况下，进行业务下探和落地执行，达到既定目标。\n3）运用互联网知识（流量、营销等），捕捉客户需求，将需求转化为运营产品来实现业务落地。\n4）结合市场、竞争情况，对业务数据进行分析和问题定位，找到有效策略，拿到预期结果。\n5）结合业务现状，对武器使用、日常运营过程中的不足提出准确需求及优化建议。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n为解决未来1-2年的核心问题，这个岗位上的人需要做以下三件事?\n1）提升核心市场酒店竞争规模比，达到大优态势。\n2）同时该岗位在团队、客户之间进行协作，管理好不同的客户关系，提升客情生产力。\n3）同时团队人员末位淘汰，对于该岗位进行查漏补缺。\n\n岗位基本要求\n1）定期出差拜访所负责城市酒店的KP（单店店长、多店店长和区域经理），根据其运营策略、客户政策及需求，通过商务洽谈，建立良好的客情，以采购优势的库存和价格，为平台消费者提供性价比更高的产品。\n2）在复杂多变的市场环境中及武器不断迭代的情况下，进行业务下探和落地执行，达到既定目标。\n3）运用互联网知识（流量、营销等），捕捉客户需求，将需求转化为运营产品来实现业务落地。\n4）结合市场、竞争情况，对业务数据进行分析和问题定位，找到有效策略，拿到预期结果。\n5）结合业务现状，对武器使用、日常运营过程中的不足提出准确需求及优化建议。\n\n岗位亮点\n1）有更大的市场空间，更多的挑战，表现优秀的同学可以获得快速晋升；\n2）我们有开放、直接的工作氛围，以逻辑和事实说话，而不是岗位级别和层级；\n3）在这里，可以和行业内优秀的团队一起工作，获得高频的培训，助力职业发展。\n具备条件有限\n1）大客户连锁维护经验。\n2）过往工作中能取得优异就结果，有成功经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3496647624","sourceKey":"meituan_social","company":"美团","title":"AI体验设计师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3496647624&jobShareType=1","duty":"1.负责医药健康AI类产品设计工作，包括选购交易、问诊导诊、商家工具等，为产品体验负责；\n2.参与产品讨论，与产品经理、工程师协作，从设计和用户体验的角度提出建议与解决方案；\n3.配合工程师共同创建用户界面，跟踪产品效果，保证最终设计质量；\n4.持续关注设计趋势，分享设计经验，推动提高团队的设计能力。","requirements":"1.大学本科及以上学历，3年以上设计工作经验，设计相关专业优先。\n2.具备出色的学习能力和丰富的AI知识储备，能有效地将想法转化为设计方案；\n3.具备较强的沟通能力和团队合作精神，能够与产品经理和开发人员有效配合；\n4.对用户体验有深入的理解和追求，关注行业设计趋势和技术动态；\n5.对工作负责，有一定抗压能力，面对挑战能内核稳定，积极克服困难解决问题。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责医药健康AI类产品设计工作，包括选购交易、问诊导诊、商家工具等，为产品体验负责；\n2.参与产品讨论，与产品经理、工程师协作，从设计和用户体验的角度提出建议与解决方案；\n3.配合工程师共同创建用户界面，跟踪产品效果，保证最终设计质量；\n4.持续关注设计趋势，分享设计经验，推动提高团队的设计能力。\n\n岗位基本要求\n1.大学本科及以上学历，3年以上设计工作经验，设计相关专业优先。\n2.具备出色的学习能力和丰富的AI知识储备，能有效地将想法转化为设计方案；\n3.具备较强的沟通能力和团队合作精神，能够与产品经理和开发人员有效配合；\n4.对用户体验有深入的理解和追求，关注行业设计趋势和技术动态；\n5.对工作负责，有一定抗压能力，面对挑战能内核稳定，积极克服困难解决问题。\n\n具备以下条件优先\n1.有成熟的AI类产品项目经验，沉淀过工作流、方法论或具备行业影响力；\n2.有丰富电商及大厂工作经验，有医药健康属性业务经验可加分。\n\n岗位亮点\n1.参与医药健康产品的设计工作，有足够多的机会接触快速发展的互联网企业所面对的新挑战；\n2.有机会接触到大量用户和复杂的业务场景，挑战性高；3.团队扁平化管理，大家一起学习、交流，一起进步和成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3381072437","sourceKey":"meituan_social","company":"美团","title":"AI高阶工程-Agent","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3381072437&jobShareType=1","duty":"1. 全面负责智能Agent相关技术方向的架构设计与工程实现，主导核心系统的技术选型和研发工作；\n2. 组建并带领高效的工程团队，推动Agent平台/产品的技术落地及持续优化；\n3. 深入理解业务需求，推动智能Agent与业务场景的深度融合，打造业内前沿的产品解决方案；\n4. 关注前沿AI技术发展，持续进行技术创新，提升产品核心竞争力；\n5. 负责与产品、算法、运营等多团队协作，确保项目高质量交付。","requirements":"1. 计算机、人工智能、软件工程等相关专业本科及以上学历，硕士/博士优先；\n2. 5年以上大型分布式系统、AI平台、智能Agent等相关领域研发经验，有业内知名智能Agent、AI产品或平台的主导研发经验；\n3. 精通Python、Go、Java等主流开发语言，熟悉微服务、云原生、容器化等现代工程架构；\n4. 深刻理解Agent框架（如LangChain、AutoGen、OpenAI Agent等）及其生态，具备大模型、知识库、插件、工具链集成等实战经验；\n5. 熟悉主流AI模型的应用与部署，对Prompt Engineering、上下文管理、多Agent协作等有深入理解和落地经验；\n6. 具备卓越的系统设计能力和工程落地能力，能从0到1打造大规模、高可用的Agent类核心产品；\n7. 有较强的团队管理能力、项目推进能力和跨部门协作能力；\n8. 拥有业内知名智能Agent产品或平台的主导研发/架构经验者优先","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 全面负责智能Agent相关技术方向的架构设计与工程实现，主导核心系统的技术选型和研发工作；\n2. 组建并带领高效的工程团队，推动Agent平台/产品的技术落地及持续优化；\n3. 深入理解业务需求，推动智能Agent与业务场景的深度融合，打造业内前沿的产品解决方案；\n4. 关注前沿AI技术发展，持续进行技术创新，提升产品核心竞争力；\n5. 负责与产品、算法、运营等多团队协作，确保项目高质量交付。\n\n岗位基本要求\n1. 计算机、人工智能、软件工程等相关专业本科及以上学历，硕士/博士优先；\n2. 5年以上大型分布式系统、AI平台、智能Agent等相关领域研发经验，有业内知名智能Agent、AI产品或平台的主导研发经验；\n3. 精通Python、Go、Java等主流开发语言，熟悉微服务、云原生、容器化等现代工程架构；\n4. 深刻理解Agent框架（如LangChain、AutoGen、OpenAI Agent等）及其生态，具备大模型、知识库、插件、工具链集成等实战经验；\n5. 熟悉主流AI模型的应用与部署，对Prompt Engineering、上下文管理、多Agent协作等有深入理解和落地经验；\n6. 具备卓越的系统设计能力和工程落地能力，能从0到1打造大规模、高可用的Agent类核心产品；\n7. 有较强的团队管理能力、项目推进能力和跨部门协作能力；\n8. 拥有业内知名智能Agent产品或平台的主导研发/架构经验者优先\n\n岗位亮点\n0-1广阔成长空间、大模型前沿技术探索、稳定业务场景对技术突破刚需","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3046093166","sourceKey":"meituan_social","company":"美团","title":"医药健康-轻医美和植发大区-CKA区域","city":"北京市/上海市/广州市/深圳市/武汉市/西安市/成都市/长沙市/重庆市/福州市/贵阳市/杭州市/昆明市/南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3046093166&jobShareType=1","duty":"1.通过已合作客户拜访沟通，了解商户的业务现状与实际需求井结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成下阶段平台合作目标\n2.执行公司的销售策略及政策，达成业绩目标\n3.与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度\n4.归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得正确的维护","requirements":"1、本科及以上学历，有销售工作经验优先；\n2、有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛，具备出色完成任务的能力；\n3、具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4、富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6、为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.通过已合作客户拜访沟通，了解商户的业务现状与实际需求井结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成下阶段平台合作目标\n2.执行公司的销售策略及政策，达成业绩目标\n3.与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度\n4.归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得正确的维护\n\n岗位基本要求\n1、本科及以上学历，有销售工作经验优先；\n2、有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛，具备出色完成任务的能力；\n3、具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4、富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6、为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n发展路径广阔，沟通机制畅通，行业潜力大，期待一起成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3300336612","sourceKey":"meituan_social","company":"美团","title":"商家客户平台-java工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3300336612&jobShareType=1","duty":"1.主导并参与美团商家客户平台后端服务架构、设计、核心功能开发、业务流程优化等工作； \n2.对商家客户核心服务的架构升级、稳定性建设、业务流程优化等方面进行规划并推动落地；\n3.探索大模型在商家智能化服务中的应用，参与AI赋能商家平台建设； \n4.负责技术难点调研和攻关，解决系统中关键的设计、技术、流程优化等问题。","requirements":"1.有技术热情，有技术视野，追求卓越； \n2.有3年及以上相关工作经验，拥有深度的计算机基础，具有良好的编码能力和编码风格，精通常用的数据结构及算法； \n3.精通java语言、jvm、多线程并发、网络IO，精通分布式、缓存、消息、搜索等技术原理及细节； \n4.关注新技术方向，有GitHub Copilot/Cursor等AI工具使用经验，了解大模型在商家平台的应用，习惯阅读英文资料，研究原理和细节，对各种工具和轮子有自己的见解； \n5.具备良好的学习能力、沟通能力，优秀的团队协作精神；乐于分享传播，善于培养团队成员。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.主导并参与美团商家客户平台后端服务架构、设计、核心功能开发、业务流程优化等工作； \n2.对商家客户核心服务的架构升级、稳定性建设、业务流程优化等方面进行规划并推动落地；\n3.探索大模型在商家智能化服务中的应用，参与AI赋能商家平台建设； \n4.负责技术难点调研和攻关，解决系统中关键的设计、技术、流程优化等问题。\n\n岗位基本要求\n1.有技术热情，有技术视野，追求卓越； \n2.有3年及以上相关工作经验，拥有深度的计算机基础，具有良好的编码能力和编码风格，精通常用的数据结构及算法； \n3.精通java语言、jvm、多线程并发、网络IO，精通分布式、缓存、消息、搜索等技术原理及细节； \n4.关注新技术方向，有GitHub Copilot/Cursor等AI工具使用经验，了解大模型在商家平台的应用，习惯阅读英文资料，研究原理和细节，对各种工具和轮子有自己的见解； \n5.具备良好的学习能力、沟通能力，优秀的团队协作精神；乐于分享传播，善于培养团队成员。\n\n具备以下条件优先\n1.参与并主导过业务中台建设优先； \n2.参与并主导商家基础能力，如网关、触达、账号、权限相关领域优先； \n3.参与并主导过三高（高并发、高可用、高性能）系统建设优先。\n\n岗位亮点\n1.参与公司层面业务系统平台化建设，探索AI在商家运营决策中的应用，掌握各环节核心技术要素，从终局出发，逐次迭代，让每行代码都有纪念意义； \n2.能熟悉核心业务的发展过程，迭代认知，沉淀方法，可以耐心的做一件有意义的事情，而不是被产品追着跑； \n3.能和多个业务团队技术大牛一起讨论、学习，共同进步； \n4.可以与业务架构团队进行极具挑战的思辨和脑暴，系统化的思考问题的简单解，让研发工作不再困惑。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2576701534","sourceKey":"meituan_social","company":"美团","title":"广告销售-易生活-商增大区","city":"北京市/上海市/广州市/深圳市/南京市/武汉市/西安市/成都市/天津市/重庆市/杭州市/苏州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2576701534&jobShareType=1","duty":"1、通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2、执行公司的销售策略及政策，达成业绩目标；\n3、与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4、归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","requirements":"1、大专及以上学历，有销售工作经验优先；\n2、有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛，具备出色完成任务的能力；\n3、具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4、富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6、为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1、通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2、执行公司的销售策略及政策，达成业绩目标；\n3、与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4、归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位基本要求\n1、大专及以上学历，有销售工作经验优先；\n2、有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛，具备出色完成任务的能力；\n3、具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4、富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5、热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6、为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n发展路径广阔，沟通机制畅通，行业潜力大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2486495544","sourceKey":"meituan_social","company":"美团","title":"多模态大模型算法专家","city":"北京市/上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2486495544&jobShareType=1","duty":"1.参与视觉大模型、语音大模型研发，探索表征学习和模型架构设计等关键技术；\n2.参与跨模态大模型研发，提升模型多模态感知、理解、生成和执行能力；\n3.深入调研视觉、语音、文本等模态前沿技术，等提升模型通用智能水平；","requirements":"1.熟练掌握Pytorch等深度学习框架，Python编程语言；\n2.熟悉大模型相关算法，并具备相应的项目实践经验；\n3.对前沿技术有强烈的探索欲，有出色的团队协作精神；\n4.发表过领域顶级会议文章(NeurIPS、ICML、ICLR、ACL、Interspeech、ICASSP等)、ACM竞赛获奖者优先。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.参与视觉大模型、语音大模型研发，探索表征学习和模型架构设计等关键技术；\n2.参与跨模态大模型研发，提升模型多模态感知、理解、生成和执行能力；\n3.深入调研视觉、语音、文本等模态前沿技术，等提升模型通用智能水平；\n\n岗位基本要求\n1.熟练掌握Pytorch等深度学习框架，Python编程语言；\n2.熟悉大模型相关算法，并具备相应的项目实践经验；\n3.对前沿技术有强烈的探索欲，有出色的团队协作精神；\n4.发表过领域顶级会议文章(NeurIPS、ICML、ICLR、ACL、Interspeech、ICASSP等)、ACM竞赛获奖者优先。\n\n具备以下条件优先\n1. 曾主导多模态相关项目的研发；\n2. 具备深度学习训练平台或推理引擎研发经验；\n3. 在国际顶会或期刊发表相关论文。\n\n岗位亮点\n1. 在技术爆发的时代，你将拥有大模型的技术经验：热门智能技术发展方向，未来拥有广阔的应用前景；\n2. 你将拥有快速成长的空间，一起见证技术落地的喜悦：大模型技术处于快速发展阶段，应用场景广泛，业务落地场景丰富，复杂度高，挑战性大；\n3. 明确的职责定位和长短期规划，持续追加的资源投入，能够专注于前沿技术领域。\n4. 你将加入优秀的团队，一起成长：团队高阶研发密度大，汇聚行业大牛，分享交流活动多；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3131927474","sourceKey":"meituan_social","company":"美团","title":"商业数据产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3131927474&jobShareType=1","duty":"1.负责商业增值部广告数据建设，从业务目标出发搭建数据指标体系并管理数据口径，为数据的准确性、及时性、安全性、稳定性负责\n2.能够沉淀广告业务分析思路与框架，设计体系化数据产品方案，与相关团队协作并推动产品落地；\n3. 负责广告业务核心数据产品建设，能通过合理应用数据工具，提升业务数据获取效率；制定数据资产建设与维护标准，保证数据资产的复用性和长期稳定\n4.大模型能力的提效场景探索\n5.负责部分数据内容、应用治理等相关工作","requirements":"1.3年以上数据产品经理工作经验，熟悉业内数据产品方案的使用场景，有较强的数据分析能力；\n2.了解商业化广告的数据指标体系，能深刻理解业务，具备良好的业务视野和洞察力，能够敏锐捕获数据价值和产品机会；\n3.有较强的责任心，优秀的沟通能力和解决问题的能力，具备良好的团队协作、沟通和项目推进能力\n4.有广告或商业化领域工作经验、数据工具、数据治理、大模型等相关经验者优先；","description":"部门介绍\n商业增值部是服务于美团核心本地商业客户的增值服务平台，覆盖餐饮、即时零售、医药、休闲娱乐、丽人医美、生活服务、酒旅度假等业务领域。我们致力于构建健康的本地商业生态，通过为平台客户和消费者提供符合其需求的多元、便捷、高效的商业产品和服务，帮助生态伙伴提高效率、优化经营、实现持续健康发展，推动本地商业数字化营销的发展，促进商业生态繁荣。作为本地商业的头部平台，我们为产品、运营、商务、技术、商业分析等领域人才提供广阔的发展空间。诚邀你加入美团商业增值团队，共筑本地商业的健康繁荣生态！\n\n岗位职责\n1.负责商业增值部广告数据建设，从业务目标出发搭建数据指标体系并管理数据口径，为数据的准确性、及时性、安全性、稳定性负责\n2.能够沉淀广告业务分析思路与框架，设计体系化数据产品方案，与相关团队协作并推动产品落地；\n3. 负责广告业务核心数据产品建设，能通过合理应用数据工具，提升业务数据获取效率；制定数据资产建设与维护标准，保证数据资产的复用性和长期稳定\n4.大模型能力的提效场景探索\n5.负责部分数据内容、应用治理等相关工作\n\n岗位基本要求\n1.3年以上数据产品经理工作经验，熟悉业内数据产品方案的使用场景，有较强的数据分析能力；\n2.了解商业化广告的数据指标体系，能深刻理解业务，具备良好的业务视野和洞察力，能够敏锐捕获数据价值和产品机会；\n3.有较强的责任心，优秀的沟通能力和解决问题的能力，具备良好的团队协作、沟通和项目推进能力\n4.有广告或商业化领域工作经验、数据工具、数据治理、大模型等相关经验者优先；\n\n具备以下条件优先\n有广告或商业化领域工作经验、数据工具、数据治理、大模型等相关经验者优先；\n\n岗位亮点\n1.可深入学习广告业务运作模式，工作内容重要且具有挑战性\n2.参与和推动数据驱动业务发展的全过程，充分发挥数据专业技能\n3.团队氛围好","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3052846209","sourceKey":"meituan_social","company":"美团","title":"创新项目渠道经理","city":"北京市/上海市/广州市/深圳市/南京市/武汉市/杭州市/昆明市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3052846209&jobShareType=1","duty":"1.业务创新与模式探索\n基于充电宝行业趋势及渠道业务痛点，设计创新性点位增长策略（25年以点位售卖模式为主），推动试点验证与规模化复制。定期分析业务数据，识别低效环节并提出优化方案，提升业务效率。\n2.项目全周期管理\n点位售卖项目全流程管理（需求对接-方案设计-资源匹配-交付验收），制定标准化SOP并监控执行进度，确保项目按时保质完成。搭建项目风险预警机制，预判各方方履约风险，通过机制设计或动态调整策略保障各战区订单交付成果。\n3.资源整合与协同落地\n联动渠道各战区渠道经理，推动内外部资源高效匹配，突破关键合作卡点。主导铺设方与承接方的需求对齐谈判，平衡双方利益诉求，建立长期共赢合作模型。\n4.合作商管理与风险防控\n有效介入合作商的全流程管理，协助合作商提升管理能效，确保可以有效承接公司项目。完善合作商管理体系，辅助制定履约评估标准与激励机制，动态优化合作商资源池。针对合作纠纷或突发问题，快速介入并协调解决方案，维护美团品牌声誉与业务连续性。\n5.商机拓展与谈判\n基于创新业务的目标和特点，锚定和细分目标客户，持续维护和经营老客户，进一步挖掘潜在铺设商和承接商。充分展现美团品牌和产品、服务及差异化优势，把握铺设方和接收方的需求，展现双方需求的契合点，在关键环节运用有效的谈判和影响策略，达成合作。","requirements":"1.本科及以上学历，5年以上互联网/零售行业项目管理或创新业务拓展经验，具备0-1创新项目落地案例。熟悉共享充电宝行业生态及渠道合作模式、有快速地推和直销管理经验者优先。\n2.核心能力项\n创新探索力：擅长从行业趋势与用户需求中抽象业务逻辑，设计可落地的创新增长方案。\n资源整合力：具备跨部门、跨区域协同经验，能快速调动资源解决复杂问题。\n项目管控力：精通项目管理，熟练使用项目管理工具，确保项目有效落地交付。\n风险预判力：对合作方履约风险敏感，擅长通过机制设计降低业务不确定性。\n3.关键素质\n强结果导向：以“结果交付”为导向，能承受高强度工作并推动目标闭环。\n系统性思维：善于从全局视角规划业务路径，平衡短期收益与长期价值。\n敏捷迭代意识：快速试错、快速验证，持续优化业务模型","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.业务创新与模式探索\n基于充电宝行业趋势及渠道业务痛点，设计创新性点位增长策略（25年以点位售卖模式为主），推动试点验证与规模化复制。定期分析业务数据，识别低效环节并提出优化方案，提升业务效率。\n2.项目全周期管理\n点位售卖项目全流程管理（需求对接-方案设计-资源匹配-交付验收），制定标准化SOP并监控执行进度，确保项目按时保质完成。搭建项目风险预警机制，预判各方方履约风险，通过机制设计或动态调整策略保障各战区订单交付成果。\n3.资源整合与协同落地\n联动渠道各战区渠道经理，推动内外部资源高效匹配，突破关键合作卡点。主导铺设方与承接方的需求对齐谈判，平衡双方利益诉求，建立长期共赢合作模型。\n4.合作商管理与风险防控\n有效介入合作商的全流程管理，协助合作商提升管理能效，确保可以有效承接公司项目。完善合作商管理体系，辅助制定履约评估标准与激励机制，动态优化合作商资源池。针对合作纠纷或突发问题，快速介入并协调解决方案，维护美团品牌声誉与业务连续性。\n5.商机拓展与谈判\n基于创新业务的目标和特点，锚定和细分目标客户，持续维护和经营老客户，进一步挖掘潜在铺设商和承接商。充分展现美团品牌和产品、服务及差异化优势，把握铺设方和接收方的需求，展现双方需求的契合点，在关键环节运用有效的谈判和影响策略，达成合作。\n\n岗位基本要求\n1.本科及以上学历，5年以上互联网/零售行业项目管理或创新业务拓展经验，具备0-1创新项目落地案例。熟悉共享充电宝行业生态及渠道合作模式、有快速地推和直销管理经验者优先。\n2.核心能力项\n创新探索力：擅长从行业趋势与用户需求中抽象业务逻辑，设计可落地的创新增长方案。\n资源整合力：具备跨部门、跨区域协同经验，能快速调动资源解决复杂问题。\n项目管控力：精通项目管理，熟练使用项目管理工具，确保项目有效落地交付。\n风险预判力：对合作方履约风险敏感，擅长通过机制设计降低业务不确定性。\n3.关键素质\n强结果导向：以“结果交付”为导向，能承受高强度工作并推动目标闭环。\n系统性思维：善于从全局视角规划业务路径，平衡短期收益与长期价值。\n敏捷迭代意识：快速试错、快速验证，持续优化业务模型\n\n岗位亮点\n1.定义行业创新标准\n参与共享充电宝行业前沿模式探索，主导从0到1的创新项目，积累行业标杆经验。\n2.高成长性舞台、资源杠杆优势\n依托部门优势，日常工作可对接渠道前线各战区、中台等部门，提供高成长性舞台，获得战略级项目曝光；能力模型覆盖“创新-执行-风控-成交”全链路，加速复合型成长。\n3.岗位晋升机制完善\n双晋升通道（管理晋升&专业晋升），成熟且上升的行业&创新业务部门、拥有无限可能。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2061381527","sourceKey":"meituan_social","company":"美团","title":"商业增值-境外广告算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2061381527&jobShareType=1","duty":"作为境外广告算法核心骨干，您将参与主导系统从0到1的核心算法策略建设，推动我们的广告产品在全球市场的成功。您将在多个关键领域发挥作用，包括但不限于推荐广告的C端模型冷启动优化、浮动广告位机制策略，以及多国场景下的通用化投放能力模式探索；搜索广告的全链路能力建设，包括多语言下的Query理解、召回和相关性等能力构建；以及B端商家智能化投放和诊断能力的开发，包括智能出价、预算分配和投放建议/诊断等。\n岗位职责：\n1、设计和实现高效的广告推荐算法，优化C端模型的冷启动问题，并提升用户体验。\n2、开发和优化浮动广告位机制，确保在多种国际场景下的广告投放效率和效果。\n3、构建和维护搜索广告的全链路能力，包括但不限于多语言环境下的理解、召回和相关性算法。\n4、为B端商家开发智能化投放工具，包括智能出价、预算优化、投放建议和诊断系统。\n5、理解不同市场的广告需求，探索和实现通用化的广告投放模式。","requirements":"1. 2年以上互联网公司大流量广告、搜索、推荐业务实践经验；\n2. 熟悉工业界广告推荐/搜索系统整体架构，熟练掌握常用算法基础理论，对各类算法应用场景和优缺点有深入认识。\n3. 在广告算法领域的广度和深度有一定技术积累，针对具体业务问题能够选择适合的算法，形成合理的落地方案并实施。\n4. 熟练掌握Python、Java或其他编程语言，以及常用的数据结构和算法，有深度学习线上模型深度调优经验；\n5. 有处理大规模数据集的经验，熟悉Hadoop、Spark等大数据技术。\n6. 具备跨文化沟通能力，能够适应多语言和多文化的工作环境。\n7. 有良好的团队合作精神，强烈的责任心和解决问题的能力。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n作为境外广告算法核心骨干，您将参与主导系统从0到1的核心算法策略建设，推动我们的广告产品在全球市场的成功。您将在多个关键领域发挥作用，包括但不限于推荐广告的C端模型冷启动优化、浮动广告位机制策略，以及多国场景下的通用化投放能力模式探索；搜索广告的全链路能力建设，包括多语言下的Query理解、召回和相关性等能力构建；以及B端商家智能化投放和诊断能力的开发，包括智能出价、预算分配和投放建议/诊断等。\n岗位职责：\n1、设计和实现高效的广告推荐算法，优化C端模型的冷启动问题，并提升用户体验。\n2、开发和优化浮动广告位机制，确保在多种国际场景下的广告投放效率和效果。\n3、构建和维护搜索广告的全链路能力，包括但不限于多语言环境下的理解、召回和相关性算法。\n4、为B端商家开发智能化投放工具，包括智能出价、预算优化、投放建议和诊断系统。\n5、理解不同市场的广告需求，探索和实现通用化的广告投放模式。\n\n岗位基本要求\n1. 2年以上互联网公司大流量广告、搜索、推荐业务实践经验；\n2. 熟悉工业界广告推荐/搜索系统整体架构，熟练掌握常用算法基础理论，对各类算法应用场景和优缺点有深入认识。\n3. 在广告算法领域的广度和深度有一定技术积累，针对具体业务问题能够选择适合的算法，形成合理的落地方案并实施。\n4. 熟练掌握Python、Java或其他编程语言，以及常用的数据结构和算法，有深度学习线上模型深度调优经验；\n5. 有处理大规模数据集的经验，熟悉Hadoop、Spark等大数据技术。\n6. 具备跨文化沟通能力，能够适应多语言和多文化的工作环境。\n7. 有良好的团队合作精神，强烈的责任心和解决问题的能力。\n\n具备以下条件优先\n1. 有相关论文发表、有个人算法开源项目或者在优秀开源算法框架项目中贡献过代码；\n2. 有一定产品思维和优秀的数据敏感性和分析能力。\n\n岗位亮点\n能全面参与境外广告业务从0到1的建设，学习到业务的全貌及系统/产品演进，跟随业务高速成长。\n如果你对世界充满好奇心，在这里，你会接触到不同的国家、语言和文化，开拓国际视野，探索异域市场。\n如果你富有冒险精神，在这里，一个个陌生的国家等待你的开发，一个个全新的关卡等待你的挑战。\n如果你渴望快速成长，在这里，你可以经历新业务从0到1的过程，不断解锁新技能，持续获得成就感。\n我们的目标是星辰大海，期待有想法、敢于冒险、渴望快速成长的你加入！让我们一同见证美团境外业务的征程！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3059284642","sourceKey":"meituan_social","company":"美团","title":"充电宝渠道经理-全国","city":"北京市/上海市/成都市/哈尔滨市/长春市/天津市/石家庄市/呼和浩特市/太原市/济南市/郑州市/合肥市/武汉市/长沙市/杭州市/南京市/福州市/海口市/广州市/昆明市/贵阳市/兰州市/西安市/重庆市/西宁市/银川市/乌鲁木齐市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3059284642&jobShareType=1","duty":"1.负责制定全国充电宝渠道拓展计划，完成全国市场渠道开发目标；\n2.负责渠道资源整合和招商，建立并维护与合作伙伴的良好关系；\n3.负责渠道管理和维护，确保渠道销售目标的实现；\n4.负责监控渠道销售情况，及时调整策略，提高销售绩效。\n5.有大客户开发和运营维护的经验和资源；","requirements":"1.大学专科以上学历，具有3年以上业务开发/渠道管理经验；\n2.具备良好的沟通能力和团队合作精神；\n3.具备较强的市场洞察力和谈判能力，有成功的渠道管理案例者优先考虑；\n4.具备全国范围内的渠道资源和渠道管理经验者优先。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.负责制定全国充电宝渠道拓展计划，完成全国市场渠道开发目标；\n2.负责渠道资源整合和招商，建立并维护与合作伙伴的良好关系；\n3.负责渠道管理和维护，确保渠道销售目标的实现；\n4.负责监控渠道销售情况，及时调整策略，提高销售绩效。\n5.有大客户开发和运营维护的经验和资源；\n\n岗位基本要求\n1.大学专科以上学历，具有3年以上业务开发/渠道管理经验；\n2.具备良好的沟通能力和团队合作精神；\n3.具备较强的市场洞察力和谈判能力，有成功的渠道管理案例者优先考虑；\n4.具备全国范围内的渠道资源和渠道管理经验者优先。\n\n具备以下条件优先\n1.渠道开拓资源和经验；\n2.大客户开发经验\n\n岗位亮点\n1.具有全国范围内的业务拓展和管理机会；\n2.薪资福利优厚，发展空间大；\n3.可带领团队，挑战更高级别职位。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3023913329","sourceKey":"meituan_social","company":"美团","title":"廉正调查专家岗","city":"北京市/上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3023913329&jobShareType=1","duty":"美团廉正监察团队致力于维护公司的廉正准则，和大家一起培育包容、简单、可信的职场环境及合作生态。为进一步强化我们的团队，我们诚邀优秀人才加入，共同打造企业廉正监察领域的TOP Team —— 可靠（Trustworthy）、客观（Objective）、专业（Professional）的团队。\n1.识别廉正领域的风险，及时发现问题线索。\n2.通过现场调查和桌面调查等方式，详尽还原事实细节，全面揭示问题本质。\n3.与其他协同部门紧密合作，共同推动企业廉正风险的有效治理。","requirements":"任职资格：\n1.3年以上相关工作经验（例如监察、合规运营、廉洁从业、内审等），可以开展相关风险防控治理项目运营工作；\n2.具备较强的组织协调和团队协作意识；\n3.逻辑思维严密，善于分析、解决问题，具有较强的沟通能力和写作能力；\n4.协同内外团队支持和落实各项运营工作落地，对用户满意负责；\n5.正直、自律、原则性及保密意识强；\n6.具备数据分析、项目管理经验者优先。","description":"部门介绍\n美团廉正监察团队致力于维护公司的廉正准则，和大家一起培育包容、简单、可信的职场环境及合作生态。为进一步强化我们的团队，我们诚邀优秀人才加入，共同打造企业廉正监察领域的TOP Team —— 可靠（Trustworthy）、客观（Objective）、专业（Professional）的团队。\n\n岗位职责\n美团廉正监察团队致力于维护公司的廉正准则，和大家一起培育包容、简单、可信的职场环境及合作生态。为进一步强化我们的团队，我们诚邀优秀人才加入，共同打造企业廉正监察领域的TOP Team —— 可靠（Trustworthy）、客观（Objective）、专业（Professional）的团队。\n1.识别廉正领域的风险，及时发现问题线索。\n2.通过现场调查和桌面调查等方式，详尽还原事实细节，全面揭示问题本质。\n3.与其他协同部门紧密合作，共同推动企业廉正风险的有效治理。\n\n岗位基本要求\n任职资格：\n1.3年以上相关工作经验（例如监察、合规运营、廉洁从业、内审等），可以开展相关风险防控治理项目运营工作；\n2.具备较强的组织协调和团队协作意识；\n3.逻辑思维严密，善于分析、解决问题，具有较强的沟通能力和写作能力；\n4.协同内外团队支持和落实各项运营工作落地，对用户满意负责；\n5.正直、自律、原则性及保密意识强；\n6.具备数据分析、项目管理经验者优先。\n\n具备以下条件优先\n具有5年以上在财务审计、数据分析、社会调查或商业调查等相关领域的工作经验者优先。\n\n岗位亮点\n1.有价值：参与大型企业治理，成为行业紧缺的ESG人才。\n2.有成长：团队管理扁平，鼓励个人学习成长，工作氛围开放包容。\n3.有机会：可与多个关键部门合作，拓展职业网络。\n4.有意义：通过促进大型企业廉正水平提升，对社会产生积极影响。\n团队积极拥抱AI工具，鼓励用AI提升工作效率，你将有机会在工作中探索AI应用的边界","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2034698307","sourceKey":"meituan_social","company":"美团","title":"中小发华南大区-产品销售","city":"赣州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2034698307&jobShareType=1","duty":"1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","requirements":"1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生；\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位基本要求\n1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生；\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n1.能够与下沉市场生活服务行业中小商户深度沟通，运用专业帮他们经营更好； 2.年轻团队、富有活力，入职即有师傅带教，将获得运营、销售、沟通等技能的专人辅导 3.发展空间大，向上可晋升至管理岗。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:1553972946","sourceKey":"meituan_social","company":"美团","title":"快驴冻品采购","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=1553972946&jobShareType=1","duty":"岗位职责：\n1.将城市内冻品卖家引入到快驴商城售卖，提升城市商品丰富度\n2.运营上线卖家及其商品，提升卖家业绩\n3.日常营促销活动的提报和效果复盘\n4.对接销售和仓配，保障商品的有效售卖和稳定履约","requirements":"1.具有三年以上招商或采购经验，两年以上冻品从业经验\n2.目标感和执行力强，做事耐心负责，不推诿，不卸责\n3.具有较好的逻辑思维和问题解决能力\n4.能接受互联网公司高强度的工作风格","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n岗位职责：\n1.将城市内冻品卖家引入到快驴商城售卖，提升城市商品丰富度\n2.运营上线卖家及其商品，提升卖家业绩\n3.日常营促销活动的提报和效果复盘\n4.对接销售和仓配，保障商品的有效售卖和稳定履约\n\n岗位基本要求\n1.具有三年以上招商或采购经验，两年以上冻品从业经验\n2.目标感和执行力强，做事耐心负责，不推诿，不卸责\n3.具有较好的逻辑思维和问题解决能力\n4.能接受互联网公司高强度的工作风格\n\n具备以下条件优先\n具有长沙本地冻品卖家资源\n\n岗位亮点\n1.大平台，成长机会多\n2.团队氛围活泼","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2195843141","sourceKey":"meituan_social","company":"美团","title":"充电宝渠道经理","city":"福州市/厦门市/南昌市/长沙市/贵阳市/南宁市/昆明市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2195843141&jobShareType=1","duty":"1.负责管理区域内合作商，及时解决合作商的问题与诉求。\n2.负责所管理合作商的数据运营分析，定期走访，协助合作商提高单产，缩短回本周期。\n3.负责当地城市的资源搭建，深挖负责城市资源类型，扩大城市规模，提高美团市占。\n4.负责属地内市场拓展的任务，每月依据公司目标制定自己属地内拓展的策略并落地实施","requirements":"1.大学专科以上学历，有较好的渠道销售业绩，两年以上渠道管理经历。\n​2.有较强的学习能力和适应能力，适应互联网行业的快速发展节奏，具备出色拿结果的能力。\n​3.具备较强的逻辑思维能力，数据分析能力。思维敏捷，能够把握产品优势。高效整合内外部资源促成合作。\n具备以下优先：\n具有渠道管理经验、充电宝行业经验优先。\n数据分析能力:可通过属地内竞争态势及合作商的关键数据指标快速分析出市场情况并落地适合的作战策略。\n属地招商能力：通过评估所辖属地实际下沉市场的实际市场情况，结合公司政策策略，独立完成属地内的合作商的招募和汰换。\n具备经营能力：对合作商的团队管理、盈亏状况等方面能给出指导建议，并能在业务运营层面给出有效的落地解决方案。\n沟通能力：能准确无误、简练的表达自己的观点，把握他人的叙述要点，能熟练应用报表、叙述性文字等形式进行书面汇报，有逻辑地展示论据，论证观点，格式清晰规范 。\n解决问题：能处理和解决充电宝专业领域常见的各类市场问题，有一定思考能力。对于棘手问题了解如何调动周边资源协助自己进行问题的处理。\n具备以下者优先\n属地化建资源：需要在目标属地内生活至少1年，具备可转化的资源储备，并且善于快速结合充电宝行业要求深挖自己属地内的资源。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1.负责管理区域内合作商，及时解决合作商的问题与诉求。\n2.负责所管理合作商的数据运营分析，定期走访，协助合作商提高单产，缩短回本周期。\n3.负责当地城市的资源搭建，深挖负责城市资源类型，扩大城市规模，提高美团市占。\n4.负责属地内市场拓展的任务，每月依据公司目标制定自己属地内拓展的策略并落地实施\n\n岗位基本要求\n1.大学专科以上学历，有较好的渠道销售业绩，两年以上渠道管理经历。\n​2.有较强的学习能力和适应能力，适应互联网行业的快速发展节奏，具备出色拿结果的能力。\n​3.具备较强的逻辑思维能力，数据分析能力。思维敏捷，能够把握产品优势。高效整合内外部资源促成合作。\n具备以下优先：\n具有渠道管理经验、充电宝行业经验优先。\n数据分析能力:可通过属地内竞争态势及合作商的关键数据指标快速分析出市场情况并落地适合的作战策略。\n属地招商能力：通过评估所辖属地实际下沉市场的实际市场情况，结合公司政策策略，独立完成属地内的合作商的招募和汰换。\n具备经营能力：对合作商的团队管理、盈亏状况等方面能给出指导建议，并能在业务运营层面给出有效的落地解决方案。\n沟通能力：能准确无误、简练的表达自己的观点，把握他人的叙述要点，能熟练应用报表、叙述性文字等形式进行书面汇报，有逻辑地展示论据，论证观点，格式清晰规范 。\n解决问题：能处理和解决充电宝专业领域常见的各类市场问题，有一定思考能力。对于棘手问题了解如何调动周边资源协助自己进行问题的处理。\n具备以下者优先\n属地化建资源：需要在目标属地内生活至少1年，具备可转化的资源储备，并且善于快速结合充电宝行业要求深挖自己属地内的资源。\n\n岗位亮点\n大厂工作、周末双休、法定节假日、六险一金、福利好。\n1.销售+管理的工作属性，同序列更高的岗位称重；\n2.双晋升通道（管理晋升&专业晋升）；\n3.成熟且上升的行业，有无限可能。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:1587322460","sourceKey":"meituan_social","company":"美团","title":"餐饮SaaS-大客户销售-渝滇黔","city":"重庆市/昆明市/贵阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=1587322460&jobShareType=1","duty":"1.负责区域内餐饮连锁收银产品的销售和市场商务拓展工作，并为区域整体绩效结果负责；\n2.通过销售拜访，了解商户的业务现状与实际需求,通过电话或面访的形式约见客户，与餐饮连锁企业深度沟通、为客户解决问题，提供SaaS一体化解决方案；\n3.及时跟进客户，做好客户关系的维系和定期回访工作，建议良好的长期合作关系；\n4.执行公司的市场策略及政策，达成业绩考核及个人成长的各项目标；\n5.与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n6.归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n任职要求：\n1.大专以上学历，有销售工作经验、互联网经验或有收银软件/硬件销售工作经验优先；\n2.个性开朗，有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛，出色完成任务能力；\n3.具备较强的人际沟通能力和逻辑思维能力，思维敏捷，能够准确的把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4.富有激情额创新理念，追求个人职业发展和公司利益的双赢，注重职业升华机遇和优质工作氛围；\n5.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6.为人正直，诚实可靠，以公司利益为重。","requirements":"有SaaS行业经验，做过大客户销售，做过大项目，有餐饮行业经验，且过往业绩突出，价值观正，热爱销售，有韧劲，想赚钱。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1.负责区域内餐饮连锁收银产品的销售和市场商务拓展工作，并为区域整体绩效结果负责；\n2.通过销售拜访，了解商户的业务现状与实际需求,通过电话或面访的形式约见客户，与餐饮连锁企业深度沟通、为客户解决问题，提供SaaS一体化解决方案；\n3.及时跟进客户，做好客户关系的维系和定期回访工作，建议良好的长期合作关系；\n4.执行公司的市场策略及政策，达成业绩考核及个人成长的各项目标；\n5.与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n6.归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n任职要求：\n1.大专以上学历，有销售工作经验、互联网经验或有收银软件/硬件销售工作经验优先；\n2.个性开朗，有很强的学习能力和适应能力，适应互联网行业的快速发展，精力充沛，出色完成任务能力；\n3.具备较强的人际沟通能力和逻辑思维能力，思维敏捷，能够准确的把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4.富有激情额创新理念，追求个人职业发展和公司利益的双赢，注重职业升华机遇和优质工作氛围；\n5.热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6.为人正直，诚实可靠，以公司利益为重。\n\n岗位基本要求\n有SaaS行业经验，做过大客户销售，做过大项目，有餐饮行业经验，且过往业绩突出，价值观正，热爱销售，有韧劲，想赚钱。\n\n岗位亮点\nP线可晋升职级，发展空间大，P线也可以转M线，提成上不封顶","jdComplete":true,"sourceStatus":"000"}];
